INSERT INTO `hotels` (id, hotel_code, slug, name, location_name, country, location_type, hotel_type, category, stay_types, address, map_link, description, image_path, is_published) VALUES
(1, 'H262', 'aaram-bagh-agra', 'AARAM BAGH AGRA', 'Agra', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3548.4444640023867!2d78.03659106505121!3d27.205191983002493!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x397470bc290bd65b%3A0xbf557d67b2edd601!2sAram%20Bagh%2C%20Agra%2C%20Uttar%20Pradesh%20282006!5e0!3m2!1sen!2sin!4v1630231904820!5m2!1sen!2sin', 'Situated on the banks of Yamuna River in the city with a variety of historic essence, Agra, Aram Bagh, or Ram Bagh, as it is currently known is a famous tourist location, consisting of gardens built by the Mughal rulers during their tenure of rule in India. The gardens are beautifully constructed, depicting the love for nature that the Mughals had. It was constructed by Babur, the first ruler, who also laid the foundation stone of the Mughal dynasty. Later, Jahangir, son of Akbar, looked after the maintenance of the gardens, followed by Noor Jehan, who made a lot of changes and additions to the structure under her governance. Having Yamuna River as the central element, the garden is mainly themed on water, having four sections which have water drawn from the river itself. In the surrounding areas, the gardens have the residual ruins of some ancient houses which were built with red sand stones.', 'assets/images/hotels/aaram-bagh-agra/1.webp', 1),
(2, 'H735', 'crystal-sarovar-portico-agra', 'CRYSTAL SAROVAR PORTICO - Agra', 'Agra', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Fatehabad Rd, near KFC, Tajganj, Agra, Uttar Pradesh 282001', NULL, 'Stay at CRYSTAL SAROVAR PORTICO, a hotel in Agra, India. The address is Fatehabad Rd, near KFC, Tajganj, Agra, Uttar Pradesh 282001. Popular places to visit in Agra include Taj Mahal, Agra Fort and Fatehpur Sikri.', 'assets/images/hotels/crystal-sarovar-portico-agra/1.webp', 1),
(3, 'H471', 'hotel-clarks-shiraz', 'Hotel Clarks Shiraz', 'Agra', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', '54, Taj Rd, Agra Cantt, Idgah Colony, Agra, Uttar Pradesh 282001', 'https://www.google.com/maps/place/Hotel+Clarks+Shiraz,+Agra/@27.1587697,78.0249711,15z/data=!4m2!3m1!1s0x0:0x6373651b1a1d7209?sa=X&ved=2ahUKEwj9qsLolYX7AhUmumMGHfGmD4oQ_BJ6BAhzEAU', 'Clarks Shiraz, Agra, is a five-star luxury hotel which combines business with pleasure, style with substance, form with function.\n\nLocated 2 km. from the Taj Mahal, in the heart of Agra, and yet free from its din and bustle, The Clarks Shiraz is just 7 km. from the Airport and 3 km. from the Railway Station.', 'assets/images/hotels/hotel-clarks-shiraz/1.webp', 1),
(4, 'H472', 'hotel-taj-resorts', 'Hotel Taj Resorts', 'Agra', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', 'Taj East Gate Rd, Forest Colony, Tajganj, Agra, Uttar Pradesh 282001', 'https://www.google.com/maps/place/Hotel+Taj+Resorts/@27.168209,78.0511305,15z/data=!4m2!3m1!1s0x0:0x59f25aaac8be29a7?sa=X&ved=2ahUKEwjFweaAmIX7AhVe9zgGHXHOCWYQ_BJ6BAhyEAU', 'Hotel Taj Resorts is the perfect destination for your Agra getaway. Situated right next to the Taj Mahal, we offer modern, luxurious and comfortable stays for both tourists and business travellers. World-class amenities backed by impeccable service give you an amazing holiday.', 'assets/images/hotels/hotel-taj-resorts/1.webp', 1),
(5, 'H734', 'howard-plaza-the-fern-agra', 'HOWARD PLAZA THE FERN - Agra', 'Agra', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Fatehabad Rd, Bansal Nagar, Tajganj, Agra, Uttar Pradesh 282001', NULL, 'Located in Agra, India, HOWARD PLAZA THE FERN is part of the Galaxy Heritage World network of hotels and resorts. Find it at Fatehabad Rd, Bansal Nagar, Tajganj, Agra, Uttar Pradesh 282001. Popular places to visit in Agra include Taj Mahal, Agra Fort and Fatehpur Sikri.', 'assets/images/hotels/howard-plaza-the-fern-agra/1.webp', 1),
(6, 'H733', 'radisson-hotel-agra-agra', 'Radisson Hotel Agra - Agra', 'Agra', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'C-2, C-1, Fatehabad Rd, Taj Nagari Phase 1, Agra, Uttar Pradesh 282004', NULL, 'Radisson Hotel Agra is located in Agra, India. Its address is C-2, C-1, Fatehabad Rd, Taj Nagari Phase 1, Agra, Uttar Pradesh 282004. Popular places to visit in Agra include Taj Mahal, Agra Fort and Fatehpur Sikri.', 'assets/images/hotels/radisson-hotel-agra-agra/1.webp', 1),
(7, 'H461', 'the-grand-imperial', 'The Grand Imperial', 'Agra', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', '20, 46, Mahatma Gandhi Rd, Baluganj, Rakabganj, Agra, Uttar Pradesh 282001', 'https://www.google.com/maps/place/The+Grand+Imperial/@27.173284,78.008802,15z/data=!4m8!3m7!1s0x0:0xf92cac04bf14e171!5m2!4m1!1i2!8m2!3d27.173284!4d78.008802', 'The Grand Imperial stationed in Agra is the integration of magnificence and luxury in the classiest way. Inside The Grand Imperial, services like spa, gym, free parking and staff guidance can be availed. As the name suggests, the hotel provides high-class services for all the customers. The rooms have been designed with bright colors that will fill you up with energy and enthusiasm to explore the hotel further. Also, these rooms are well-equipped with all the modern day necessities.\n\nAt The Grand Imperial, rooms are available with garden views so that it soothes your soul down. This hotel is perfect for travels related to business purposes. A diverse range of cuisine like Indian, Chinese & Continental can also be enjoyed at The Grand Imperial. The places of tourist interests are all near the hotel so commuting is very easy. Anyways, an additional cab facility is also present for the customers’ ease.', 'assets/images/hotels/the-grand-imperial/1.webp', 1),
(8, 'H462', 'doubletree-by-hilton-ahmedabad', 'DoubleTree by Hilton Ahmedabad', 'Ahmedabad', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Ambli Rd, Vikram Nagar, Ahmedabad, Gujarat 380058', 'https://www.google.com/maps/place/DoubleTree+by+Hilton+Ahmedabad/@23.0282074,72.5016463,15z/data=!4m8!3m7!1s0x0:0x7395c1af3b86b844!5m2!4m1!1i2!8m2!3d23.0281812!4d72.5016463', 'DoubleTree by Hilton Ahmedabad\nA Cleaner Stay From Check-In to Check-Out We’ve taken additional measures beyond our industry-leading cleaning standards by partnering with Reckitt, maker of Lysol & Dettol, to develop our Hilton CleanStay program. This innovative program builds upon our already rigorous cleaning standards by providing enhanced training for Team Members, increased cleaning of public areas and adjusted food & beverage service, to ensure our guests enjoy a worry-free stay. Due to the current travel environment, hotel amenities and services may be limited. Visit the hotel website for specific property policies and updates. Please check with regional health and government authorities about the evolving health and safety requirements that may be in place at the location of your stay.', 'assets/images/hotels/doubletree-by-hilton-ahmedabad/1.webp', 1),
(9, 'H463', 'eulogia-inn-ahmedabad', 'EULOGIA INN, AHMEDABAD', 'Ahmedabad', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Gota Bridge, Eulogia Hotel Rd, opp. Safal Vivan, Beside PRIME STATUS, Gota, Ahmedabad, Gujarat 382481', 'https://www.google.com/maps/place/Eulogia+Inn/@23.1084498,72.5374183,15z/data=!4m8!3m7!1s0x0:0x7c1128065cd04f47!5m2!4m1!1i2!8m2!3d23.1084498!4d72.5374183', 'Eulogia offers rooms in Ahmedabad, 6 km from Sardar Patel Stadium and 7 km from Gandhi Ashram. This 4-star hotel offers a 24-hour front desk and a concierge service. The tour desk can help arrange some activities and free WiFi is included. This is a pure vegetarian property. At the hotel, each room has a desk and a flat-screen TV. The private bathroom is fitted with free toiletries. All rooms come with a seating area. A buffet breakfast is available every morning at the property. There is an on-site restaurant, which specialises in Indian and Chinese cuisine and also offers Vegan and Vegetarian options. IIM is 8 km from Eulogia, while Nirma University is 2.3 km from the property. Sardar Vallabhbhai Patel International Airport is 10 km away.', 'assets/images/hotels/eulogia-inn-ahmedabad/1.webp', 1),
(10, 'H736', 'regenta-central-antarim-hotel-ahmedabad', 'Regenta Central Antarim Hotel - Ahmedabad', 'Ahmedabad', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Between Girish Coldrink & St. Xaviers Corner, Chimanlal Girdharlal Rd, Navrangpura, Ahmedabad, Gujarat 380006', NULL, 'Stay at Regenta Central Antarim Hotel in Ahmedabad, India. The address is Between Girish Coldrink & St. Xaviers Corner, Chimanlal Girdharlal Rd, Navrangpura, Ahmedabad, Gujarat 380006. Popular places to visit in Ahmedabad include Sabarmati Ashram, Adalaj Stepwell and Kankaria Lake.', 'assets/images/hotels/regenta-central-antarim-hotel-ahmedabad/1.webp', 1),
(11, 'H776', 'hotel-pushkar-palace', 'Hotel Pushkar Palace', 'Ajmer', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; heritage-homes; castles', 'Near, Lake, Choti Basti, Pushkar, Rajasthan 305022', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14284.034146196256!2d74.5563887!3d26.48767!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x396bdd22ffffffff%3A0x7a103945c5f650a1!2sHotel%20Pushkar%20Palace!5e0!3m2!1sen!2sin!4v1711679890911!5m2!1sen!2sin', 'Overlooking Pushkar Lake and hills, this old-world hotel is a 14-minute walk from Camel Safari Mukesh and a 16-minute walk from Brahma Temple. It\'s a 6-minute walk from Chyavanashram bus station.\n\nFeaturing decorative moldings, the refined rooms and suites provide Wi-Fi, flat-screen TVs and air-conditioning, as well as minibars, tea and coffeemaking facilities and private bathrooms; some add lake views.\n\nBreakfast is available. Dining options include an indoor restaurant serving vegetarian meals, and a rooftop restaurant with candlelight and scenic views; there’s no alcohol. Free Wi-Fi', 'assets/images/hotels/hotel-pushkar-palace/1.webp', 1),
(12, 'H775', 'ramada-by-wyndham-ajmer', 'Ramada by Wyndham Ajmer', 'Ajmer', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Sushant City By Ansal Api, N.H.8, Kishangargh Rd, Ajmer, Jaipur - Jodhpur National Hwy, Gegal, Rajasthan 305802', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14277.449760506208!2d74.7566555!3d26.540622!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x396bef8cbada9fc3%3A0xb69a4957423bfdd6!2sRamada%20Hotel%20Ajmer%20(Vegetarian%20Hotel)!5e0!3m2!1sen!2sin!4v1711679376163!5m2!1sen!2sin', 'Set on NH8, this stylish modern hotel is 2.1 km from the Gegal Akhari Railway Station and 19 km from the Nareli Jain Temple.\n\nThe elegant rooms and suites feature contemporary furnishings and provide free Wi-Fi, flat-screen TVs, minibars and tea and coffeemaking equipment. Some have terraces/balconies. Room service is offered.\n\nParking is free, along with a breakfast buffet. There\'s also a stylish restaurant, a bar and a disco open on weekends. Additional amenities include a fitness room and an outdoor pool. Free Wi-Fi', 'assets/images/hotels/ramada-by-wyndham-ajmer/1.webp', 1),
(13, 'H774', 'the-fern-residency-ajmer', 'The Fern Residency Ajmer', 'Ajmer', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Gaurav Path, opp. cinemall, near shani mandir, Anand Nagar, Ajmer, Rajasthan 305001', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14284.728319044036!2d74.6317044!3d26.4820817!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x396be7482622734f%3A0xbebb887734f8b05e!2sThe%20Fern%20Residency%20Ajmer!5e0!3m2!1sen!2sin!4v1711679164543!5m2!1sen!2sin', 'Stay at The Fern Residency Ajmer, a hotel in Ajmer, India. The address is Gaurav Path, opp. cinemall, near shani mandir, Anand Nagar, Ajmer, Rajasthan 305001. Popular places to visit in Ajmer include Ajmer Sharif Dargah, Ana Sagar Lake and Adhai Din Ka Jhonpra.', 'assets/images/hotels/the-fern-residency-ajmer/1.webp', 1),
(14, 'H278', 'lemontree-vembanand-alleppey', 'LEMONTREE VEMBANAND ALLEPPEY', 'Alleppey', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15734.894702732903!2d76.3721241!3d9.6190441!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x9fb82099712efcc2!2sLemon%20Tree%20Vembanad%20Lake%20Resort%2C%20Kerala!5e0!3m2!1sen!2sin!4v1630403883045!5m2!1sen!2sin', 'Fresh, spirited and youthful, Lemon Tree Hotels (LTH) is India\'s largest chain in the mid-priced hotels sector and third largest overall, on the basis of controlling interest in owned and leased rooms, as of June 30, 2017, according to the Horwath Report.This award winning Indian hotel chain opened its first hotel with 49 rooms in May 2004 and operates 57 hotels in 34 cities with 5800+ rooms and over 5000 employees (As on July, 2019).', 'assets/images/hotels/lemontree-vembanand-alleppey/1.webp', 1),
(15, 'H678', 'oxygen-resorts-alleppey', 'Oxygen Resorts - Alleppey', 'Alleppey', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', 'Finishing Point Road, Thathampally, Alappuzha, Kerala 688013', NULL, 'Oxygen Resorts is located in Alleppey, India. Its address is Finishing Point Road, Thathampally, Alappuzha, Kerala 688013. Popular places to visit in Alleppey include Alappuzha Beach, Vembanad Lake and Marari Beach.', 'assets/images/hotels/oxygen-resorts-alleppey/1.webp', 1),
(16, 'H645', 'palmgrove-lake-resort', 'Palmgrove Lake Resort', 'Alleppey', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', 'NT Ward, Punnamada, Alappuzha, Kerala 688006', 'https://www.google.com/maps?rlz=1C1UEAD_enIN1027IN1027&um=1&ie=UTF-8&fb=1&gl=in&sa=X&geocode=KftZrC76hAg7MbaLWmjMmQfK&daddr=NT+Ward,+Punnamada,+Alappuzha,+Kerala+688006', 'Palmgrove Lake Resort lends the healing touch of Ayurvedic wellness combined with Yoga and a stay experience nonpareil. Spread across 3 acres of lush greenery, here is where you could unwind yourself completely, pampered by the loving lull of Nature. Set on a scenic spot where the poetic beauty of backwaters wed the verdant richness of a natural coconut garden, there’s no better place than Best Family resorts in Alleppey to be in, on your visit to Kerala. Rejuvenate yourself, profoundly touched by the virtues of ancient Ayurveda. Rediscover your inner self with the magical power of Yoga and Meditation. Relax, sitting back on your comfy cottage, curiously listening to the chirps of around 23 species of birds that throng the place. Or simply walk through the lawns, gazing at the ornate beauty of the surroundings as you see rows of boats pass by through the lake. If that doesn’t suffice your love for more, embark on a sunrise cruise into the Vembanad Lake right from the resort in Alleppey. You’ll be spoilt for experiences.', 'assets/images/hotels/palmgrove-lake-resort/1.webp', 1),
(17, 'H680', 'ramada-by-wyndham-alleppey-alleppey', 'Ramada by Wyndham Alleppey - Alleppey', 'Alleppey', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Nehru Trophy Boat Race Finishing Point Stadium, Punnamada, Finishing Point, Alappuzha, Kerala 688013', NULL, 'Located in Alleppey, India, Ramada by Wyndham Alleppey is part of the Galaxy Heritage World network of hotels and resorts. Find it at Nehru Trophy Boat Race Finishing Point Stadium, Punnamada, Finishing Point, Alappuzha, Kerala 688013. Popular places to visit in Alleppey include Alappuzha Beach, Vembanad Lake and Marari Beach.', 'assets/images/hotels/ramada-by-wyndham-alleppey-alleppey/1.webp', 1),
(18, 'H464', 'sterling-lake-palace-alleppey', 'Sterling Lake Palace Alleppey', 'Alleppey', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; heritage-homes; castles', 'Thirumala Ward, Chungam, Alappuzha, Kerala 688011', 'https://www.google.com/maps/place/Sterling+Lake+Palace+Alleppey/@9.4947171,76.3615944,15z/data=!4m8!3m7!1s0x0:0x2f931c5fd4195f77!5m2!4m1!1i2!8m2!3d9.4947171!4d76.3615944?hl=en', 'Alleppey, also named as ‘Venice of the East’ by the Viceroy of India Lord Curzon, is one of the oldest trading centers, bridging India’s ties with Greece and Rome during the Middle Ages. The culture of Alleppey has its soul defined in the ‘Sangam Era’ with art, literature, social and economic collaborations with Tamil Nadu, Kerala and Sri Lanka. It also draws its influence from the Dutch and Portuguese settlers of 12th Century, which established Christianity in the region. Sterling Lake Palace Alleppey Resort is centrally located in 14 acres of lush greenery and calm water bodies, parallel to the Vembanad lake. Built with a private lagoon surrounded by backwaters, the resort features 58 luxurious rooms and suites, overlooking the Vembanad Lake – the longest freshwater lake in India. The resort also boasts an Ayurvedic spa, water sports, exotic flavors of the coast and delectable global cuisines. Want to relax? Check out the incredible island swimming pool, and sip your favourite cocktail poolside, while taking in the beauty around you.', 'assets/images/hotels/sterling-lake-palace-alleppey/1.webp', 1),
(19, 'H679', 'time-square-boutique-hotel-alleppey', 'Time Square Boutique Hotel - Alleppey', 'Alleppey', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'PitchuIyer Jn, Cullen Rd, Alappuzha, Kerala 688001', NULL, 'Time Square Boutique Hotel is located in Alleppey, India. Its address is PitchuIyer Jn, Cullen Rd, Alappuzha, Kerala 688001. Popular places to visit in Alleppey include Alappuzha Beach, Vembanad Lake and Marari Beach.', 'assets/images/hotels/time-square-boutique-hotel-alleppey/1.webp', 1),
(20, 'H646', 'hyatt-regency-amritsar', 'Hyatt Regency Amritsar', 'Amritsar', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'MBM Farms, Grand Trunk Rd, adjoining Mall Of Amritsar, Amritsar, Punjab 143001', 'https://www.google.com/maps?rlz=1C1UEAD_enIN1027IN1027&um=1&ie=UTF-8&fb=1&gl=in&sa=X&geocode=KX_u8SzFfBk5MRFi6sJTNkrH&daddr=MBM+Farms,+Grand+Trunk+Rd,+adjoining+Mall+Of+Amritsar,+Amritsar,+Punjab+143001', 'Hyatt Regency Amritsar is a 5-star Deluxe hotel of the city with an inventory of 248 rooms, located at 4.2 kms from the world-renowned Golden Temple. Hyatt Regency Amritsar is a 30 minutes’ drive from the Guru Ram Das International Airport. The hotel is also right adjacent to the Mall of Amritsar on GT road. The location of the hotel makes it the most convenient for leisure travellers across.', 'assets/images/hotels/hyatt-regency-amritsar/1.webp', 1),
(21, 'H259', 'lemon-tree-hotel-amritsar', 'LEMON TREE HOTEL, AMRITSAR', 'Amritsar', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3397.0007048595685!2d74.8580210151534!3d31.63383108133219!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x391964a9a10874fb%3A0x84404964ab91df26!2sLemon%20Tree%20Hotel%20Amritsar!5e0!3m2!1sen!2sin!4v1630225499988!5m2!1sen!2sin', 'Lemon Tree Hotel, Amritsar is located in Model Town, GT Road, on Grand Trunk Road, one of Asia’s longest and most important roadways. The hotel is just a few minutes away from the railway station and Gobind Ghar Fort, and is in close proximity to Sadda Pind and the famed Golden Temple. It is strategically situated close to not just the most famous monuments in the city, but also to the neighboring commercial and financial districts. Within a 4 km radius around the hotel, guests can access some of the most renowned locations of the city, including the ethereal Golden Temple, also known as Harmandir Sahib. It is the most important pilgrimage site for Sikhism and the house of the Akal Takht, the highest seat of earthly authority of the Khalsa. The Gurudwara is known not just as a place of religious worship, but as a beacon of serenity and peace. The historic Jallianwala Bagh, next to the Golden Temple Plaza, houses a memorial of national importance to commemorate the death of peaceful celebrators and stands as a reminder of the Indian fight for freedom. Guests can also easily access Durgiana Temple, the Maharaja Ranjit Singh Museum and the beautiful Amritsar Cantonment Area. Lemon Tree Hotel, Amritsar welcomes you with cheery greetings, friendly smiles and a whiff of the signature lemon fragrance. The hotel offers a mix of 64 rooms and suites, a conference room, a 24x7 multi-cuisine coffee shop - Citrus Café, a rooftop bar – Slounge, as well as a fully equipped fitness center, refreshing swimming pool and wellness spa. The hotel is also supported by a 5,500 sq. ft., state-of-the-art conferencing and meeting space, Tangerine Grand, ideal for corporate gatherings and social events, as well as 550 sq. ft. conference room, Tangerine, which can also be used as a private dining room for elegant intimate gatherings.', 'assets/images/hotels/lemon-tree-hotel-amritsar/1.webp', 1),
(22, 'H466', 'radisson-blu-hotel-amritsar', 'Radisson Blu Hotel Amritsar', 'Amritsar', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Ajnala Road (Airport Road), 8th Mile Stone, Punjab 143001', 'https://www.google.com/maps/place/Radisson+Blu+Hotel+Amritsar/@31.7059121,74.8190215,15z/data=!4m2!3m1!1s0x0:0x580284e749d073f1?sa=X&ved=2ahUKEwiVvZjryIP7AhVTFLcAHTZDDlMQ_BJ6BQiFARAF', 'Radisson Blu Hotel is just 0.9 mi away from Guru Ram Das Ji International Airport (ATQ). It features on-site dining restaurants, an outdoor pool and a fitness center. Free Wi-Fi is available in the entire hotel. A complimentary shuttle service is provided to the Golden Temple at scheduled hours. Jallianwala Bagh and Amritsar Railway Station is 7.5 mi away from the property. Wagah Border is 21 mi away from Radisson Blu Hotel. The Golden Temple is 7.5 mi. All rooms have air conditioning, a satellite flat-screen TV and a mini-bar. Private bathrooms come with free toiletries and shower facilities. For guests’ convenience, the hotel offers a 24-hour front desk and currency exchange service. Travel and sightseeing tours can be arranged at the tour desk. Located at Lobby Level, Proof Bar is ideal for a relaxing evening and offers a wide range of beverages and snacks. Guests can enjoy à la carte and buffet meals offered 24 hours at Tavolo Mondo Restaurant or witness food being cooked in the open show kitchen while relaxing in calm jade decor at Wall of Asia Restaurant.', 'assets/images/hotels/radisson-blu-hotel-amritsar/1.webp', 1),
(23, 'H465', 'regenta-central-amritsar', 'Regenta Central Amritsar', 'Amritsar', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'A - 275, Grand Trunk Rd, East Mohan Nagar, Amritsar, Punjab 143001', 'https://www.google.com/maps/place/Regenta+Central+Amritsar/@31.622673,74.8978978,15z/data=!4m2!3m1!1s0x0:0x7308a4086bd83893?sa=X&ved=2ahUKEwj13pDIxoP7AhUL3HMBHehdDngQ_BJ6BAhnEAU', 'Whether you’re in Amritsar for a productive busness meeting or on a vacation, the Regenta Central Amritsar has the perfect room for you. The hotel is just 1.5kms from the Golden Temple, 12kms from Amritsar International Airport, 3km from Amritsar Railway Terminal, and popular markets.\n\nBook one of our 38 comfortable rooms for an excellent stay in the heart of the city. The hotel also hosts large social gatherings and corporate events in its elegant banquet halls in close proximity.', 'assets/images/hotels/regenta-central-amritsar/1.webp', 1),
(24, 'H677', 'regenta-central-amritsar-amritsar', 'Regenta Central Amritsar - Amritsar', 'Amritsar', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'A - 275, Grand Trunk Rd, East Mohan Nagar, Amritsar, Punjab 143001', NULL, 'Stay at Regenta Central Amritsar, a hotel in Amritsar, India. The address is A - 275, Grand Trunk Rd, East Mohan Nagar, Amritsar, Punjab 143001. Popular places to visit in Amritsar include Golden Temple, Jallianwala Bagh and Wagah Border.', 'assets/images/hotels/regenta-central-amritsar-amritsar/1.webp', 1),
(25, 'H676', 'the-fern-residency-amritsar', 'The Fern Residency - Amritsar', 'Amritsar', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', '33 the, Mall Rd, Amritsar, Punjab 143001', NULL, 'The Fern Residency is a hotel in Amritsar, India. Its address is 33 the, Mall Rd, Amritsar, Punjab 143001. Popular places to visit in Amritsar include Golden Temple, Jallianwala Bagh and Wagah Border.', 'assets/images/hotels/the-fern-residency-amritsar/1.webp', 1),
(26, 'H777', 'cliff-top-club-resort', 'Cliff-top club resort', 'Auli', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', NULL, NULL, 'Located in Auli, India, Cliff-top club resort is part of the Galaxy Heritage World network of hotels and resorts. Popular places to visit in Auli include Auli Artificial Lake, Gorson Bugyal and Chattrakund.', 'assets/images/hotels/cliff-top-club-resort/1.webp', 1),
(27, 'H647', 'lemon-tree-hotel-aurangabad', 'Lemon Tree Hotel, Aurangabad', 'Aurangabad', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'R 7/2, Airport Rd, CIDCO Cannought, Chilkalthana, Aurangabad, Maharashtra 431210', 'https://www.google.com/maps?rlz=1C1UEAD_enIN1027IN1027&um=1&ie=UTF-8&fb=1&gl=in&sa=X&geocode=KbEjAINSyOc7MR0JGZ2AfSn_&daddr=R+7/2,+Airport+Rd,+CIDCO+Cannought,+Chilkalthana,+Aurangabad,+Maharashtra+431210', 'The hotel offers 102 rooms and suites, business center, banquet and meeting Center, a multi-cuisine coffee shop - Citrus Cafe (18 hours), a hip recreation bar - Slounge, as well as an outdoor pool and fitness center to keep you feeling fresh-as-a-lemon.', 'assets/images/hotels/lemon-tree-hotel-aurangabad/1.webp', 1),
(28, 'H468', 'vivanta-aurangabad', 'Vivanta Aurangabad', 'Aurangabad', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', '8-N-12, Dr Rafiq Zakaria Marg, Rauza Bagh, Cidco, Aurangabad, Maharashtra 431003', 'https://www.google.com/maps/place/Vivanta+Aurangabad/@19.907598,75.346467,15z/data=!4m2!3m1!1s0x0:0x4c36e63f4e1aaece?sa=X&hl=en&ved=2ahUKEwi90oHa0IP7AhWY8jgGHaVEA84Q_BJ6BAhrEAU', 'Vivanta Aurangabad sits within landscaped gardens and a running track, just 20-minute drive from Aurangabad Chikkalthana Airport and Railway Station. An outdoor pool, pampering spa treatments and a fitness centre are available. It offers free WiFi access. Tease Bar serves alcoholic and non-alcoholic drinks. Breakfast can be enjoyed at Latitude Restaurant.\n\nThe spacious and air-conditioned rooms are equipped with a satellite TV and personal safe. Private balconies overlook the garden or pool. En suite bathrooms come with a bathtub and shower facilities.\n\nVivanta Aurangabad is a good stop-over for guests visiting the UNESCO World Heritage Sites of Ellora and Ajanta Caves. Free parking is available.\n\nGuests can arrange day trips or rent cars at the tour desk. The hotel also provides business services like fax and photocopying. Laundry services and a souvenir shop are also available. Croquet can be played at the property.\n\nGuests can enjoy Chinese cuisine at the specialty restaurant, Tea House.', 'assets/images/hotels/vivanta-aurangabad/1.webp', 1),
(29, 'H467', 'welcomhotel-by-itc-hotels-rama-international-aurangabad', 'Welcomhotel By ITC Hotels, Rama International, Aurangabad', 'Aurangabad', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'R-3 Chikalthana,Jalna Road, Aurangabad, Maharashtra 431003', 'https://www.google.com/maps/place/Welcomhotel+By+ITC+Hotels,+Rama+International,+Aurangabad/@19.8758946,75.3588411,15z/data=!4m2!3m1!1s0x0:0x38405bac1ce1bafa?sa=X&ved=2ahUKEwjgupSkzIP7AhVg6nMBHelVAYgQ_BJ6BAhyEAU', 'Offering an outdoor swimming pool, a fitness centre and a spa and wellness centre, Welcomhotel by ITC Hotels, Rama International, Aurangabad is located in Aurangabad. The Aurangabad Airport is 4 km. Free WiFi is available.\n\nAir-conditioned room here will provide you with a seating area. There is also an electric kettle. Featuring a shower, private bathroom also comes with free toiletries and slippers. You can enjoy garden view from the room.\n\nAt Welcomhotel by ITC Hotels, Rama International, Aurangabad you will find a 24-hour front desk and a 1 km running track. Other facilities offered at the property include a tour desk and laundry facilities. The property offers free parking.\n\nThe banquet Venue- Sita Hall, is the largest Pillar less Hall in the city, which can be re-arranged into three smaller independent banquet venues- Sita Hall-I, Sita Hall-II, and Sita Hall-III, each separated with sound proof partitions. Sholla - Specialty Restaurant - Local cuisine available\n\nThe hotel is 7 km from Bibi ka Maqbara and 30 km from the Ellora Caves. The Aurangabad Bus Station and the Aurangabad Railway Station are 7 km away. 16 Kms from Shendra Industrial area and WALUJ MIDC is 17 Kms away and 110 Kms from Ajanta\n\nThe in-house restaurant serves Indian, Chinese and continental delights. Room service is available throughout the day.', 'assets/images/hotels/welcomhotel-by-itc-hotels-rama-international-aurangabad/1.webp', 1),
(30, 'AYD02', 'ramayana-hotel', 'Ramayana Hotel', 'Ayodhya', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Ramayana Hotel, Main Road, Ayodhya, India', 'https://maps.google.com/?q=Ramayana%20Hotel%20Ayodhya', 'Experience luxury hospitality at Ramayana Hotel in Ayodhya, featuring modern amenities and exceptional service.', 'assets/images/hotels/ramayana-hotel/1.webp', 1),
(31, 'H280', 'daun-bali-seminyak-bali', 'DAUN BALI SEMINYAK BALI', 'Bali', 'Indonesia', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15776.81765170293!2d115.1638141!3d-8.6721012!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x4a7c75dcd0db8c7a!2sDaun%20Bali%20Seminyak%20Hotel%20(previously%20ZIA%20Bali%20Seminyak)!5e0!3m2!1sen!2sin!4v1630405289093!5m2!1sen!2sin', 'Daun Bali Seminyak Hotel is the ideal introduction for a modern design rooms combined with a smart hotel system, providing a new stay-at-hotel experience. Situated just right in the best spot in Seminyak with 90 rooms from Superior Room to Penthouse Room, ready to accommodate your needs.', 'assets/images/hotels/daun-bali-seminyak-bali/1.webp', 1),
(32, 'H485', 'grand-hyatt-bali', 'Grand Hyatt Bali', 'Bali', 'Indonesia', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Kawasan Wisata Nusa Dua BTDC, Jl. Nusa Dua, Benoa, South Kuta, Badung Regency, Bali 80363, Indonesia', 'https://www.google.com/maps/place/Grand+Hyatt+Bali/@-8.8036711,115.2332213,15z/data=!4m2!3m1!1s0x0:0x3d410f454cdae814?sa=X&ved=2ahUKEwj0-8u9o4z7AhVeg2MGHTtuDx4Q_BJ6BQiUARAF', 'Grand Hyatt Bali hotel is the crown jewel of resorts in Nusa Dua with 5-star facilities, located moments from a world-class convention centre and steps away from Bali Collection shopping centre. Just 15 minutes from Bali Airport, our hotel is suitable for both business and leisure with its blend of culture, Balinese hospitality, tropical sceneries, and modern convenience', 'assets/images/hotels/grand-hyatt-bali/1.webp', 1),
(33, 'H486', 'hotel-taum-resort-bali', 'Hotel Taum Resort Bali', 'Bali', 'Indonesia', 'INTERNATIONAL', 'RESORT', 'INTERNAL', 'resorts', 'Jl. Lb. Sari No.37-39, Kerobokan Kelod, Kec. Kuta Utara, Kabupaten Badung, Bali 80361, Indonesia', 'https://www.google.com/maps/place/Hotel+Taum+Resort+Bali/@-8.676894,115.1597197,15z/data=!4m8!3m7!1s0x0:0xd9890ba403ec0d46!5m2!4m1!1i2!8m2!3d-8.6768934!4d115.1597199?hl=en', 'Centrally located in Seminyak, Taum Resort Bali offers modern and well-designed studios with free WiFi. An outdoor pool, rooftop garden and pampering spa treatments are available.', 'assets/images/hotels/hotel-taum-resort-bali/1.webp', 1),
(34, 'H279', 'mantra-sakala-resort-bali', 'MANTRA SAKALA RESORT BALI', 'Bali', 'Indonesia', 'INTERNATIONAL', 'RESORT', 'INTERNAL', 'resorts', NULL, NULL, 'Jl. Pratama No.95, Benoa, Kec. Kuta Sel., Kabupaten Badung, Bali 80361, Indonesia', 'assets/images/hotels/mantra-sakala-resort-bali/1.webp', 1),
(35, 'H281', 'park-hotel-nusa-dua-bali', 'PARK HOTEL NUSA DUA BALI', 'Bali', 'Indonesia', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15771.628990725032!2d115.2089118!3d-8.7947844!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x797d2b744884b84!2sThe%20Bali%20Bay%20View%20Hotel%20Suites%20%26%20Villas!5e0!3m2!1sen!2sin!4v1630405716494!5m2!1sen!2sin', 'Set on an unassuming street in South Kuta, this polished hotel in a low-key building is 4 km from Nusa Dua Beach along the Bali Sea and 13 km from the Ngurah Rai International Airport. Refined rooms have free Wi-Fi, flat-screen TVs, coffeemakers and balconies. Suites add kitchens, sitting areas and dining spaces. Luxe villas come with private pools. Room service is available 24/7. Amenities include a laid-back bar and an elegant restaurant with terrace dining, plus 2 pools (1 with sea views), a spa and a fitness room. An area shuttle is included. Breakfast is offered for a surcharge. Parking is available. An airport shuttle can be arranged.', 'assets/images/hotels/park-hotel-nusa-dua-bali/1.webp', 1),
(36, 'H487', 'ramada-encore-by-wyndham-seminyak-bali', 'Ramada Encore by Wyndham Seminyak Bali', 'Bali', 'Indonesia', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Jl. Dewi Saraswati III, Seminyak, Kec. Kuta, Kota Denpasar, Bali 80361, Indonesia', 'https://www.google.com/maps/place/Ramada+Encore+by+Wyndham+Seminyak+Bali/@-8.6854918,115.1761508,15z/data=!4m2!3m1!1s0x0:0xa68eb71c1a7af0d7?sa=X&hl=en&ved=2ahUKEwjkutK0qYz7AhVO6zgGHQVXB9kQ_BJ6BAh-EAU', 'Ramada Encore by Wyndham Seminyak Bali is a 4-star hotel, sitting comfortably on approximately 10,000 square meters of land with a 2200 square meter swimming lagoon pool, situated in trendy Seminyak area, a popular area for all tourists that has its own charm and bustling lifestyle. It is located in a peaceful location but still within a short distance from all modern conveniences and enjoyments. In around 10 minutes you can reach Seminyak Square, main hubs for Bali’s best exotic attractions. Our complimentary shuttle service can drop you off at some popular destinations around Kuta-Seminyak area. Ramada Encore by Wyndham Seminyak Bali is an ideal choice for leisure and business.', 'assets/images/hotels/ramada-encore-by-wyndham-seminyak-bali/1.webp', 1),
(37, 'BANAR01', 'brijrama-palace', 'BrijRama Palace', 'Banaras', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; heritage-homes; castles', 'BrijRama Palace, Main Road, Banaras, India', 'https://maps.google.com/?q=BrijRama%20Palace%20Banaras', 'Experience luxury hospitality at BrijRama Palace in Banaras, featuring modern amenities and exceptional service.', 'assets/images/hotels/brijrama-palace/1.webp', 1),
(38, 'BANAR02', 'suryauday-haveli', 'Suryauday Haveli', 'Banaras', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels; heritage-homes', 'Suryauday Haveli, Main Road, Banaras, India', 'https://maps.google.com/?q=Suryauday%20Haveli%20Banaras', 'Experience luxury hospitality at Suryauday Haveli in Banaras, featuring modern amenities and exceptional service.', 'assets/images/hotels/suryauday-haveli/1.webp', 1),
(39, 'BDP01', 'bandipur-safari-lodge', 'Bandipur Safari Lodge', 'Bandipur', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts; eco-lodges', 'Bandipur Safari Lodge, Main Road, Bandipur, India', 'https://maps.google.com/?q=Bandipur%20Safari%20Lodge%20Bandipur', 'Experience luxury hospitality at Bandipur Safari Lodge in Bandipur, featuring modern amenities and exceptional service.', 'assets/images/hotels/bandipur-safari-lodge/1.webp', 1),
(40, 'BDP02', 'dhole-s-den', 'Dhole\'s Den', 'Bandipur', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Dhole\'s Den, Main Road, Bandipur, India', 'https://maps.google.com/?q=Dhole\'s%20Den%20Bandipur', 'Experience luxury hospitality at Dhole\'s Den in Bandipur, featuring modern amenities and exceptional service.', 'assets/images/hotels/dhole-s-den/1.webp', 1)
INSERT INTO `hotels` (id, hotel_code, slug, name, location_name, country, location_type, hotel_type, category, stay_types, address, map_link, description, image_path, is_published) VALUES
(41, 'H274', 'bangalore-lemon-tree', 'BANGALORE LEMON TREE', 'Bangalore', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, NULL, 'Lake facing, Lemon Tree Hotel, City Center Bengaluru, is situated less than 1 km from Commercial Street and St. Mary’s Basilica. It offers a spa and rooftop swimming pool. Free parking is provided. Lemon Tree Hotel is located in the central business district, a 30-minute drive from Koramanagala. Bengaluru International Airport is a 45-minute ride away. The property is in close proximity to MG Road and Brigade Road. Bagmane Tech Park, Manyata Tech Park and Embassy Golf Links are within a 10 km radius. Modern rooms are decorated with colourful pieces of artwork and come fitted with a DVD player and flat-screen TV with cable channels. Free Wi-Fi is provided for 30 minutes per room. Guests can work out in the fitness centre and head for a well-deserved massage after. Currency exchanges and sightseeing arrangements can be made at the tour desk. The hotel also has a business centre. Citrus Café specialises in all-day international delights while pan-Asian cuisine is served at Republic of Noodles. Drinks are featured at Slounge. We speak your language!', 'assets/images/hotels/bangalore-lemon-tree/1.webp', 1),
(42, 'H649', 'holiday-inn-bengaluru-racecourse-an-ihg-hotel', 'Holiday Inn Bengaluru Racecourse, an IHG Hotel', 'Bangalore', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Ward No.94, 16/1, Seshadri Rd, Gandhi Nagar, Bengaluru, Karnataka 560009', 'https://www.google.com/maps?rlz=1C1UEAD_enIN1027IN1027&um=1&ie=UTF-8&fb=1&gl=in&sa=X&geocode=KZ2T650RFq47MThLe-fX_MSP&daddr=Ward+No.94,+16/1,+Seshadri+Rd,+Gandhi+Nagar,+Bengaluru,+Karnataka+560009', 'Conveniently located along Seshadri Road across Bangalore Turf Club Holiday Inn Bengaluru Racecourse is about thirty four km from Kempegowda International Airport. We are easily accessible to Kempegowda Bus Station and Bengaluru City Junction Railway Station just within one km of the hotel. We are also close to attractions like Cubbon Park UB City Central College Cricket Ground and corporate buildings like Canara Bank RBI NABARD State Bank India Office. The 272 well appointed rooms include 22 premium rooms with private balcony and 22 suites with Individual living room and facilities like microwave and dining area to attract long stay guests. Travel easily to other parts of the city with readily available taxis in the area. Enjoy free Wi Fi throughout the hotel. Kick start your day with power breakfast and enjoy our high quality bedding and power shower experience to recharge after a fun filled day of activities.', 'assets/images/hotels/holiday-inn-bengaluru-racecourse-an-ihg-hotel/1.webp', 1),
(43, 'H689', 'hotel-royal-orchid-suites-whitefield-banglore', 'Hotel Royal Orchid Suites - Whitefield - Banglore', 'Bangalore', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Vaswani Pinnacle annexe, Whitefield Main Rd, Bengaluru, Karnataka 560066', NULL, 'Located in Bangalore, India, Hotel Royal Orchid Suites is part of the Galaxy Heritage World network of hotels and resorts. Find it at Vaswani Pinnacle annexe, Whitefield Main Rd, Bengaluru, Karnataka 560066. Popular places to visit in Bangalore include Bangalore Palace, Lalbagh Botanical Garden and Cubbon Park.', 'assets/images/hotels/hotel-royal-orchid-suites-whitefield-banglore/1.webp', 1),
(44, 'H282', 'ibis-bengaluru-hosur-road', 'ibis Bengaluru Hosur Road', 'Bangalore', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15556.436770517588!2d77.6320229!3d12.9006997!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x90b37bc9353d1814!2sibis%20Bengaluru%20Hosur%20Road!5e0!3m2!1sen!2sin!4v1630407821157!5m2!1sen!2sin', 'Set in a striking high-rise building, this unpretentious hotel is 9 km from Bellandur Lake, and the shops and restaurants on Brigade Road.\n\nCompact modern rooms with understated decor provide flat-screen TVs, free Wi-Fi and desks, as well as tea and coffeemaking facilities. Room service is offered 24/7.\n\nParking is free. Amenities include a vibrant contemporary restaurant, a sleek bar and a gym. An airport shuttle is available for a fee.', 'assets/images/hotels/ibis-bengaluru-hosur-road/1.webp', 1),
(45, 'H283', 'lemontree-electronic-city-bangalore', 'LEMONTREE ELECTRONIC CITY BANGALORE', 'Bangalore', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15560.158407346418!2d77.6596037!3d12.8407175!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x3e220ca549c2a013!2sLemon%20Tree%20Hotel%2C%20Electronics%20City%2C%20Bangalore!5e0!3m2!1sen!2sin!4v1630408916939!5m2!1sen!2sin', 'A 5-minute walk from the nearest bus stop, this modern, upscale hotel is 13 km from Jagannath Temple and 15 km from Bannerghatta Biological Park.\n\nPolished rooms with contemporary styling feature free Wi-Fi, satellite TV and DVD players, plus tea and coffeemaking facilities. Upgraded rooms add minifridges, while suites offer minibars, microwaves and separate living areas.\n\nFree breakfast and parking are provided. There’s a casual international cafe, and a pan-Asian restaurant serving street food. Other amenities include a trendy bar with a PlayStation and a pool table, plus a fitness room, a spa and an outdoor pool.', 'assets/images/hotels/lemontree-electronic-city-bangalore/1.webp', 1),
(46, 'H648', 'radisson-blu-bengaluru-outer-ring-road', 'Radisson Blu Bengaluru Outer Ring Road', 'Bangalore', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', '90/4, Dr Puneeth Rajkumar Rd, Marathahalli Village, Marathahalli, Bengaluru, Karnataka 560037', 'https://www.google.com/maps?rlz=1C1UEAD_enIN1027IN1027&um=1&ie=UTF-8&fb=1&gl=in&sa=X&geocode=KS1w93bwE647MRnoxlxA5w-F&daddr=90/4,+Dr+Puneeth+Rajkumar+Rd,+Marathahalli+Village,+Marathahalli,+Bengaluru,+Karnataka+560037', 'Inspired by the urban art of living, the Radisson Blu Bengaluru Outer Ring Road offers elegant décor and a range of top-notch amenities in the Marathahalli area. We are an upper upscale business hotel located strategically at Marathahalli Junction between the heart of the city and the major business district (Sarjarpur, Outer Ring Road and Whitefield) at the IT hub of India’s Silicon Valley. The hotel is a confluence of leisure and business, making it the perfect choice for business travelers and guests looking for unrivaled comfort. With 218 rooms across six categories as well as five restaurants, a convention center and a vibrant nightclub, the Radisson Blu has everything that India’s next generation of travelers seeks.', 'assets/images/hotels/radisson-blu-bengaluru-outer-ring-road/1.webp', 1),
(47, 'H688', 'royal-orchid-resort-and-convention-centre-banglore', 'Royal Orchid Resort & Convention Centre - Banglore', 'Bangalore', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', 'Jakkur Flying Club, Near, Bellary Rd, Allalasandra, Yelahanka, Bengaluru, Karnataka 560065', NULL, 'Located in Bangalore, India, Royal Orchid Resort & Convention Centre is part of the Galaxy Heritage World network of hotels and resorts. Find it at Jakkur Flying Club, Near, Bellary Rd, Allalasandra, Yelahanka, Bengaluru, Karnataka 560065. Popular places to visit in Bangalore include Bangalore Palace, Lalbagh Botanical Garden and Cubbon Park.', 'assets/images/hotels/royal-orchid-resort-and-convention-centre-banglore/1.webp', 1),
(48, 'H474', 'starlit-suites-ecity-bengaluru', 'Starlit Suites Ecity Bengaluru', 'Bangalore', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Smondo Suites, E 39/275, Smondoville Road, Neotown, phase-1, Electronic City, Bengaluru, Karnataka 560100', 'https://www.google.com/maps/place/Starlit+Suites+Ecity+Bengaluru/@12.8218485,77.6592222,15z/data=!4m2!3m1!1s0x0:0xaf8e8a54ea0345d5?sa=X&ved=2ahUKEwjC_Y_AoYX7AhXI-jgGHXXQDEMQ_BJ6BAh9EAU', 'Starlit Suites is a pioneer in bridging the gap between traditional 4* hotels and serviced apartments. Our endeavour is to provide our guests with all the services and facilities they are accustomed to with the comfort of a hotel the and warmth of a home. We believe in giving you “a home every time you check-in” Keeping true to our aspirations, all our Aparthotels  have specious suites, ergonomic meeting facilities, delectable F&B outlets well-appointed gymnasium, swimming pool and business centre. At Starlit Suites we have designed our Suites keeping in mind the comforts that the discerning traveller needs to function optimally given the hectic schedules and deadlines that are being juggled daily.', 'assets/images/hotels/starlit-suites-ecity-bengaluru/1.webp', 1),
(49, 'H690', 'vividus-hotels-banglore', 'Vividus Hotels - Banglore', 'Bangalore', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Kumarakrupa Rd, Madhava Nagar, Gandhi Nagar, Benaluru, Karnataka 560001', NULL, 'Vividus Hotels is located in Bangalore, India. Its address is Kumarakrupa Rd, Madhava Nagar, Gandhi Nagar, Benaluru, Karnataka 560001. Popular places to visit in Bangalore include Bangalore Palace, Lalbagh Botanical Garden and Cubbon Park.', 'assets/images/hotels/vividus-hotels-banglore/1.webp', 1),
(50, 'H285', 'al-meroz-hotel-bangkok', 'Al Meroz Hotel Bangkok', 'Bangkok', 'Thailand', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15502.17295820601!2d100.6038516!3d13.7460811!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xbffd5d228f34aee8!2sAl%20Meroz%20Hotel%20Bangkok!5e0!3m2!1sen!2sin!4v1630411387923!5m2!1sen!2sin', 'Set on a major city road, this elegant hotel in an Arabian-inspired building is a 4-minute walk from the Foundation of the Islamic Center of Thailand, 10 km from shops at MBK Center and 3 km from soccer matches at Rajamangala National Stadium.\n\nChic, warmly decorated rooms feature free Wi-Fi, flat-screens, prayer mats and minifridges. The upscale suites add living areas and 4-poster beds. Room service is available 24/7.\n\nArea shuttles and welcome drinks are free. A laid-back eatery and an understated Mediterranean restaurant offer halal dishes and non-alcoholic drinks. There\'s also a gender-segregated rooftop pool and a gym, plus a prayer room.', 'assets/images/hotels/al-meroz-hotel-bangkok/1.webp', 1),
(51, 'H495', 'furama-silom', 'Furama Silom', 'Bangkok', 'Thailand', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '533 Si Lom, Silom, Bang Rak, Bangkok 10500, Thailand', 'https://www.google.com/maps/place/Furama+Silom/@13.72476,100.525299,15z/data=!4m2!3m1!1s0x0:0xe0a544b9c50a103b?sa=X&ved=2ahUKEwiU3-X00oz7AhUy6jgGHRwHCdgQ_BJ6BAh-EAU', 'Furama Silom Hotel is about 25 km from Suvarnabhumi Airport and within 1.5 km of Hualumphong Train Station. The hotel is also a short walk from Patpong Night Market.', 'assets/images/hotels/furama-silom/1.webp', 1),
(52, 'H496', 'president-park-hotel', 'President Park Hotel', 'Bangkok', 'Thailand', 'INTERNATIONAL', 'HOTEL', 'ASSOCIATED', 'hotels', 'Khlong Toei, Bangkok 10110, Thailand', 'https://www.google.com/maps/place/Khlong+Toei,+Bangkok,+Thailand/data=!4m2!3m1!1s0x30e29f08b614220d:0x40100b25de28ee0?sa=X&ved=2ahUKEwiB27q_1Iz7AhWp4jgGHcnLBIcQ8gF6BAh0EAE', 'Enjoy a stay in spacious and luxurious rooms and partake in recreational activities offered at the President Park Hotel, Bangkok.', 'assets/images/hotels/president-park-hotel/1.webp', 1),
(53, 'H284', 'prime-hotel-central-station-bangkok', 'PRIME HOTEL CENTRAL STATION BANGKOK', 'Bangkok', 'Thailand', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15502.73573401651!2d100.5153928!3d13.7375757!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x6d195bdc3ace443e!2sThe%20Quarter%20Bangkok%20Hotel!5e0!3m2!1sen!2sin!4v1630410902485!5m2!1sen!2sina', 'In a sleek modern building, this upscale hotel is a 4-minute walk from Hua Lamphong train station, and 5 km from the shopping and entertainment at MBK Center.\n\nThe stylish rooms come with free Wi-Fi, flat-screen TVs, and tea and coffeemakers, as well as desks and safes. Suites add living areas. Room service is offered, and kids 11 and under stay with adults at no charge.\n\nThere\'s an elegant restaurant offering high-end Chinese cuisine, along with a casual cafe; breakfast is available for a fee. There are 2 bars (1 poolside), in addition to a spa, and a fitness center with a sauna and steam rooms.', 'assets/images/hotels/prime-hotel-central-station-bangkok/1.webp', 1),
(54, 'H469', 'country-inn-bhimtal', 'Country Inn Bhimtal', 'Bhimtal', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Bhowali - Kutani Rd, Mehragaon, Uttarakhand 263136', 'https://www.google.com/maps/place/Country+Inn+Bhimtal/@29.367394,79.5421979,15z/data=!4m8!3m7!1s0x0:0x672d12b633f3b312!5m2!4m1!1i2!8m2!3d29.3674813!4d79.542215', 'Located in the pristine hills of Bhimtal, about 30 minutes drive from Nainital Lake and just 10 minutes drive from the picturesque Bhimtal Lake, this resort spread across 14 acres of sprawling gardens is the best in region and has won many awards for its outstanding services. The resort offers a wide range of cuisines making it an ideal destination for your hill station holiday. The fun games, activities and adventure available in this region combine to make your holiday filled with many thrills one seeks while in the mountainous terrains. The resort offers ample parking space and has provision for your driver accommodation also.This luxury family resort offers excellent view of the hills and has a whole lot of fun games and activities built in for the entire family. A holiday here will give you the thrills that one looks forward to while taking a break. The perfect holiday getaway for all seasons. Country Inn resorts are pet friendly.', 'assets/images/hotels/country-inn-bhimtal/1.webp', 1),
(55, 'H651', 'the-fern-hillside-resort-bhimtal', 'The Fern Hillside Resort, Bhimtal', 'Bhimtal', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', '69, June Estate, Bhowali Range, Bhimtal, Uttarakhand 263136', 'https://www.google.com/maps?rlz=1C1UEAD_enIN1027IN1027&um=1&ie=UTF-8&fb=1&gl=in&sa=X&geocode=Ka0J0Y48mKA5MdQpsndMaY7f&daddr=69,+June+Estate,+Bhowali+Range,+Bhimtal,+Uttarakhand+263136', 'The Fern Hillside Resort, Bhimtal is a premium resort with 30 luxurious rooms with a contemporary design, offering highest level of comfort. The resort is best suited for business and leisure travelers; it offers world class hospitality along with natural wonders the valley has to offer.', 'assets/images/hotels/the-fern-hillside-resort-bhimtal/1.webp', 1),
(56, 'H650', 'the-rosefinch-sarovar-portico-bhimtal', 'The Rosefinch Sarovar Portico Bhimtal', 'Bhimtal', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'June Estate Rd, Bhimtal, Uttarakhand 263136', 'https://www.google.com/maps?rlz=1C1UEAD_enIN1027IN1027&um=1&ie=UTF-8&fb=1&gl=in&sa=X&geocode=KZMqip0omKA5MRFQiCWRZH0R&daddr=June+Estate+Rd,+Bhimtal,+Uttarakhand+263136', 'Rosefinch Sarovar Portico is an exquisitely designed resort in Bhimtal that overlooks the emerald green Bhimtal Lake and makes for a perfect sojourn for both business and leisure travellers. Nestled in nature, the property is centrally located to nearby tourist destinations like Nainital, Mukteshwar & Jim Corbett National Park. Local attractions include the renowned Kaichi Dham, Mathpal\'s Folk Museum, Nakuchiatal Lake and offers various adventurous water activities. The resort features three living spaces viz. Deluxe Rooms, Luxury Rooms and Family Rooms.', 'assets/images/hotels/the-rosefinch-sarovar-portico-bhimtal/1.webp', 1),
(57, 'H478', 'courtyard-by-marriott-bhopal', 'Courtyard by Marriott Bhopal', 'Bhopal', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Db City, Arera Hills, Bhopal, Madhya Pradesh 462011', 'https://www.google.com/maps/place/Courtyard+by+Marriott+Bhopal/@23.2331557,77.4297087,15z/data=!4m8!3m7!1s0x0:0xa455a4bc62fc4ac2!5m2!4m1!1i2!8m2!3d23.2331557!4d77.4297087', 'Featuring a spacious landscape pool, Courtyard Bhopal offers elegantly furnished rooms with floor-to-ceiling glass windows. It also has 1 restaurants and 1 bars with 24-hour in-room dining.\n\nLocated 7 km away from Bhopal Railway Station, the property is also 17 km away from the historical Jamma Mosque and 18 km from Raja Bhoj International Airport. Airport Shuttle Services are available at a surcharge.\n\nAir-conditioned rooms are fitted with ironing facilities, a flat-screen TV and a laptop size safe. Tea/coffee making facilities and a minibar are included. The spacious attached bathroom comes with shower facilities and toiletries.\n\nMomo Café serves Indian, Chinese and Continental cuisines. Éclair – The Bake Shop offers various snacks and savouries. Refreshing drinks can be enjoyed at Corner Bar.\n\nEnjoy a good workout at the fitness centre or rent a car with vehicle rental services while a 24-hour front desk can assist with meeting facilities, laundry/dry cleaning services and travel arrangements', 'assets/images/hotels/courtyard-by-marriott-bhopal/1.webp', 1),
(58, 'H479', 'enrise-by-sayaji-best-banquet-hotel-in-bhopal', 'Enrise by Sayaji - Best Banquet hotel in Bhopal', 'Bhopal', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Van Vihar Rd, Near Sair Sapata, Prempura, Bhopal, Madhya Pradesh 462002', 'https://www.google.com/maps/place/Enrise+by+Sayaji+-+Best+Banquet+hotel+in+Bhopal/@23.2194819,77.372799,15z/data=!4m8!3m7!1s0x0:0x1552ca074661d825!5m2!4m1!1i2!8m2!3d23.2194819!4d77.372799', 'Set in Bhopal, 3.2 km from Van Vihar National Park, Enrise by Sayaji Bhopal offers accommodation with a restaurant, free private parking, a fitness centre and a bar. This 3-star hotel offers a 24-hour front desk, room service and free WiFi. The hotel features family rooms. The hotel will provide guests with air-conditioned rooms with a desk, a kettle, a fridge, a safety deposit box, a flat-screen TV and a private bathroom with a shower. The units feature a wardrobe. Enrise by Sayaji Bhopal offers a continental or buffet breakfast. Museum of Man is 3.7 km from the accommodation, while Habibganj Station is 7.7 km away. The nearest airport is Raja Bhoj Airport, 16 km from Enrise by Sayaji Bhopal.', 'assets/images/hotels/enrise-by-sayaji-best-banquet-hotel-in-bhopal/1.webp', 1),
