(65, 'H499', 'hard-rock-hotel-tenerife', 'Hard Rock Hotel Tenerife', 'Canary Islands', 'Spain', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Avenida Adeje 300, Av. Playa Paraíso, s/n, 38678 Adeje, Santa Cruz de Tenerife, Spain', 'https://www.google.com/maps/dir//Hard+Rock+Hotel+Tenerife,+Avenida+Adeje+300,+Av.+Playa+Para%C3%ADso,+s%2Fn,+38678+Adeje,+Santa+Cruz+de+Tenerife,+Spain/@28.1210355,-16.8457067,12z/data=!4m8!4m7!1m0!1m5!1m1!1s0xc6a911c471a79fb:0xc3536f1cf2873e6d!2m2!1d-16.7756664!2d28.1210533?hl=en-GB', 'Luxe rooms & suites in a hip hotel with 10 restaurants/bars, 3 pools & regular live entertainment', 'assets/images/hotels/hard-rock-hotel-tenerife/1.webp', 1),
(66, 'H498', 'hotel-thb-tropical-island', 'Hotel THB Tropical Island', 'Canary Islands', 'Spain', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'C. la Fragata, 2, 35580 Lanzarote, Las Palmas, Spain', 'https://www.google.com/maps/place/C.+la+Fragata,+2,+35580+Playa+Blanca,+Las+Palmas,+Spain/@28.871322,-13.8242752,17z/data=!3m1!4b1!4m5!3m4!1s0xc46374cfe3aa949:0xb8f7850bfe4b4df5!8m2!3d28.871322!4d-13.8242752', 'Hotel THB Tropical Island is a big resort located in Playa Blanca, Lanzarote. The hotel offers 15 Pools for adults and children and an adult only area with pool and bar. The hotel features 414 premium apartments with free wifi and balcony or terrace. The hotel has a buffet restaurant and 2 a la carte restaurants. Entertainment for adults and children. Tennis, football, miniclub , gym and a complete SPA. El Hotel THB Tropical Island es un gran complejo ubicado en Playa Blanca, Lanzarote. El hotel ofrece 15 piscinas para adultos y niños y un área solo para adultos con piscina y bar. El hotel cuenta con 414 apartamentos premium con wifi gratuito y balcón o terraza. El hotel tiene un restaurante buffet y 2 restaurantes a la carta. Entretenimiento para adultos y niños. Tenis, fútbol, miniclub, gimnasio y un completo SPA', 'assets/images/hotels/hotel-thb-tropical-island/1.webp', 1),
(67, 'H270', 'lemon-tree-hotel-chandigarh', 'LEMON TREE HOTEL CHANDIGARH', 'Chandigarh', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13721.816276649943!2d76.8033715!3d30.7056329!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xe0e8a9bccc7a28ba!2sLemon%20Tree%20Hotel%2C%20Chandigarh!5e0!3m2!1sen!2sin!4v1630388960220!5m2!1sen!2sin', 'Relaxed rooms feature free Wi-Fi, flat-screen TVs, DVD players and desks, plus safes, minibars, and tea and coffeemaking facilities. Suites add living areas and microwaves. Room service is available. Breakfast is complimentary. There\'s also a restaurant and a relaxed bar with a pool table. Additional amenities include a gym, a spa and an outdoor pool, plus a business centre and meeting space. Parking is available.', 'assets/images/hotels/lemon-tree-hotel-chandigarh/1.webp', 1),
(68, 'H292', 'park-plaza-zirakpur-chandigarh', 'PARK PLAZA ZIRAKPUR CHANDIGARH', 'Chandigarh', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13731.479760412503!2d76.8224672!3d30.6376228!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x45e2bcd3cdc71c1c!2sPark%20Plaza%20Chandigarh%20Zirakpur!5e0!3m2!1sen!2sin!4v1631010969496!5m2!1sen!2sin', 'Since hotel policies regarding early check-in (generally before 2:00 pm) or late checkout (generally after 12:00 pm) vary by location and by hotel, please call the hotel directly prior to your arrival to make any necessary arrangements. Direct hotel phone numbers can be found on your confirmation email or on the hotel information page.\n\nIf your travel plans change, you can cancel or modify your reservation in accordance with the hotel\'s cancellation policy as stated during the reservation process.\n\nHotel room rates vary by date and by the number of adults occupying a single room. To accommodate more guests, you need to change your reservation. You will be notified of any additional charges prior to confirming your updated reservation.\n\nAlthough individual hotel policies may vary, most hotels have a minimum age requirement of 21 years old. Please call the hotel directly prior to your arrival to make any necessary arrangements. Direct hotel phone numbers can be found in your confirmation email or on the respective hotel information page.', 'assets/images/hotels/park-plaza-zirakpur-chandigarh/1.webp', 1),
(69, 'H674', 'ramada-plaza-by-wyndham-chandigarh-zirakpur-chandigarh', 'Ramada Plaza by Wyndham Chandigarh Zirakpur - Chandigarh', 'Chandigarh', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Ambala Chandigarh Expressway, Chandigarh Rd, Zirakpur, Punjab 140603', NULL, 'Ramada Plaza by Wyndham Chandigarh Zirakpur is a hotel in Chandigarh, India. Its address is Ambala Chandigarh Expressway, Chandigarh Rd, Zirakpur, Punjab 140603. Popular places to visit in Chandigarh include Rock Garden, Sukhna Lake and Zakir Hussain Rose Garden.', 'assets/images/hotels/ramada-plaza-by-wyndham-chandigarh-zirakpur-chandigarh/1.webp', 1),
(70, 'H675', 'regenta-central-cassia-zirakpur-chandigarh', 'REGENTA CENTRAL CASSIA ZIRAKPUR - Chandigarh', 'Chandigarh', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Patiala Rd, Green Enclave, Lohgarh, Zirakpur, Punjab 140603', NULL, 'Located in Chandigarh, India, REGENTA CENTRAL CASSIA ZIRAKPUR is part of the Galaxy Heritage World network of hotels and resorts. Find it at Patiala Rd, Green Enclave, Lohgarh, Zirakpur, Punjab 140603. Popular places to visit in Chandigarh include Rock Garden, Sukhna Lake and Zakir Hussain Rose Garden.', 'assets/images/hotels/regenta-central-cassia-zirakpur-chandigarh/1.webp', 1),
(71, 'H662', 'regenta-central-deccan-chennai-chennai', 'Regenta Central Deccan Chennai - Chennai', 'Chennai', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', '36, Royapettah High Rd, Jagadambal Colony, Sripuram, Teachers Colony, Royapettah, Chennai, Tamil Nadu 600014', NULL, 'Regenta Central Deccan Chennai is a hotel in Chennai, India. Its address is 36, Royapettah High Rd, Jagadambal Colony, Sripuram, Teachers Colony, Royapettah, Chennai, Tamil Nadu 600014. Popular places to visit in Chennai include Marina Beach, Kapaleeshwarar Temple and Fort St. George.', 'assets/images/hotels/regenta-central-deccan-chennai-chennai/1.webp', 1),
(72, 'H480', 'radisson-blu-kochi', 'Radisson Blu Kochi', 'Cochin', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Metro Junction, Sahodaran Ayyappan Rd, Elamkulam, Kochi, Kerala 682020', 'https://www.google.com/maps/place/Radisson+Blu+Kochi/@9.9676064,76.3072482,15z/data=!4m2!3m1!1s0x0:0x54974bd38aab09b8?sa=X&ved=2ahUKEwi_teCpuoj7AhVC73MBHaIZDs8Q_BJ6BAh6EAU', 'Featuring stylish interiors and a friendly staff committed to providing the best experience possible, the Radisson Blu Kochi stands out as one of the best upper upscale hotels in the city. The hotel is located in Kochi’s city center and within 100 meters of the Elamkulam Metro Station, making prominent businesses, transport stops, and prime shopping destinations like LuLu Mall and MG Road easily accessible. Just 10 minutes away, you can explore the city’s waterfront. Willingdon Island, housing the city’s port, naval base, and many businesses and attractions, is within a 20-minute drive.\n\nDuring your stay, you can relax in style with a swim in our rooftop pool or a massage treatment at our on-site spa. A well-equipped fitness center lets you keep up with your exercise routine, and our business center is available for last-minute work preparations. You can always find something delicious at our four on-site restaurants and our chic bar. Need to meet with clients? Our on-site meeting facilities provide the perfect spot.', 'assets/images/hotels/radisson-blu-kochi/1.webp', 1),
(73, 'CJB02', 'the-residency-towers', 'The Residency Towers', 'Coimbatore', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'The Residency Towers, Main Road, Coimbatore, India', 'https://maps.google.com/?q=The%20Residency%20Towers%20Coimbatore', 'Experience luxury hospitality at The Residency Towers in Coimbatore, featuring modern amenities and exceptional service.', 'assets/images/hotels/the-residency-towers/1.webp', 1),
