(79, 'DED02', 'hotel-madhuban', 'Hotel Madhuban', 'Dehradun', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Hotel Madhuban, Main Road, Dehradun, India', 'https://maps.google.com/?q=Hotel%20Madhuban%20Dehradun', 'Experience luxury hospitality at Hotel Madhuban in Dehradun, featuring modern amenities and exceptional service.', 'assets/images/hotels/hotel-madhuban/1.webp', 1),
(80, 'DED01', 'hyatt-regency-dehradun', 'Hyatt Regency Dehradun', 'Dehradun', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Hyatt Regency Dehradun, Main Road, Dehradun, India', 'https://maps.google.com/?q=Hyatt%20Regency%20Dehradun%20Dehradun', 'Experience luxury hospitality at Hyatt Regency Dehradun in Dehradun, featuring modern amenities and exceptional service.', 'assets/images/hotels/hyatt-regency-dehradun/1.webp', 1)
INSERT INTO `hotels` (id, hotel_code, slug, name, location_name, country, location_type, hotel_type, category, stay_types, address, map_link, description, image_path, is_published) VALUES
(81, 'H653', 'haut-monde-hill-stream-resort-dhanaulti', 'Haut Monde Hill Stream Resort - Dhanaulti', 'Dhanaulti', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', 'Kokliyal Gaon, Patti Saklana, Tehsil Dhanaulti, Dehradun, Uttarakhand 248001', NULL, 'Stay at Haut Monde Hill Stream Resort in Dhanaulti, India. The address is Kokliyal Gaon, Patti Saklana, Tehsil Dhanaulti, Dehradun, Uttarakhand 248001. Popular places to visit in Dhanaulti include Eco Park, Surkanda Devi Temple and Potato Farm.', 'assets/images/hotels/haut-monde-hill-stream-resort-dhanaulti/1.webp', 1),
(82, 'H482', 'citrus-classic-hotel-mcleodganj', 'Citrus Classic Hotel Mcleodganj', 'Dharamshala', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Temple Rd, near Dalai Lama Temple, McLeod Ganj, Dharamshala, Himachal Pradesh 176219', 'https://www.google.com/maps/place/Citrus+Classic+Hotel+Mcleodganj/@32.2344178,76.3246938,15z/data=!4m2!3m1!1s0x0:0x562b319bc0120c8a?sa=X&ved=2ahUKEwjChZ3Zv4j7AhW07TgGHR26AyoQ_BJ6BAh6EAU', 'Boasting a garden, Citrus Classic Mcleodganj is set in Dharamshala in the Himachal Pradesh region, 6.4 km from HPCA Stadium and 3.2 km from McLeod Ganj. Among the facilities of this property are a restaurant, a 24-hour front desk and room service, along with free WiFi. The hotel has family rooms.\n\nAll guest rooms come with air conditioning, a flat-screen TV with satellite channels, a kettle, a shower, a hairdryer and a desk. With a private bathroom fitted with a bath and free toiletries, some units at the hotel also feature a balcony. At Citrus Classic Mcleodganj, the rooms are equipped with a seating area.\n\nGuests at the accommodation can enjoy a continental or a buffet breakfast.\n\nCitrus Classic Mcleodganj offers a terrace.\n\nDharmsala is 4.5 km from the hotel, while Dharamshala is 6.6 km from the property. The nearest airport is Kangra Airport, 15 km from Citrus Classic Mcleodganj.', 'assets/images/hotels/citrus-classic-hotel-mcleodganj/1.webp', 1),
(83, 'H657', 'himgiri-resort-n-spa-by-shree-hari-hotels-dharamshala', 'Himgiri Resort n Spa by Shree Hari Hotels - Dharamshala', 'Dharamshala', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts; wellness-retreats', 'Naddi, Upper, McLeod Ganj, Dharamshala, Himachal Pradesh 176216', NULL, 'Himgiri Resort n Spa by Shree Hari Hotels is located in Dharamshala, India. Its address is Naddi, Upper, McLeod Ganj, Dharamshala, Himachal Pradesh 176216. Popular places to visit in Dharamshala include HPCA Stadium, Tsuglagkhang Complex and Dalai Lama Temple.', 'assets/images/hotels/himgiri-resort-n-spa-by-shree-hari-hotels-dharamshala/1.webp', 1),
(84, 'H656', 'hotel-shivani-international-dharamshala', 'Hotel Shivani International  - Dharamshala', 'Dharamshala', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Bhagsu Nag, Dharamshala, Himachal Pradesh 176219', NULL, 'Stay at Hotel Shivani International in Dharamshala, India. The address is Bhagsu Nag, Dharamshala, Himachal Pradesh 176219. Popular places to visit in Dharamshala include HPCA Stadium, Tsuglagkhang Complex and Dalai Lama Temple.', 'assets/images/hotels/hotel-shivani-international-dharamshala/1.webp', 1),
(85, 'H275', 'nibaana-dharamshala', 'NIBAANA DHARAMSHALA', 'Dharamshala', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13503.302402398449!2d76.3803637!3d32.2089297!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x14d9b0b69fa7978c!2sNibaana%20-%20A%20Luxury%20Resort%20in%20Dharamshala!5e0!3m2!1sen!2sin!4v1630393412218!5m2!1sen!2sin', 'Boasting a garden, bar and views of river, Nibaana - A Luxury Resort in Dharamshala is set in Dharamshala, 6 km from HPCA Stadium. Among the facilities of this property are a restaurant, a 24-hour front desk and room service, along with free WiFi. The rooms are equipped with a balcony with a mountain view. All guest rooms come with air conditioning, a flat-screen TV with satellite channels, a kettle, a shower, a hairdryer and a wardrobe. At the resort, all rooms include a private bathroom with free toiletries. Continental and buffet breakfast options are available every morning at Nibaana. The accommodation offers a terrace. The area is popular for cycling, and bike hire and car hire are available at Nibaana - A Luxury Resort in Dharamshala. The nearest airport is Kangra Airport, 14 km from the resort. We speak your language!', 'assets/images/hotels/nibaana-dharamshala/1.webp', 1),
(86, 'H387', 'aloft-dubai-creek', 'Aloft Dubai Creek', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', NULL, NULL, 'Facing a bustling highway, this trendy hotel is 6 km from both Dubai International Airport and the Dubai Museum, which features the oldest existing building in Dubai. The bright rooms and suites offer free Wi-Fi, flat-screen TVs and minibars, plus tea and coffeemaking equipment, safes and floor-to-ceiling windows. Airy, vivid suites add Nespresso machines. Room service is available 24/7.\n\nParking is complimentary. Other amenities include a screening room, a gym, and a colourful, modern lounge with a bar and regular live music. There\'s also a sleek cafe, a Chinese restaurant, and a rooftop pool with city views. Breakfast is provided (fee).', 'assets/images/hotels/aloft-dubai-creek/1.webp', 1),
(87, 'H784', 'avani-deira-dubai-hotel', 'Avani Deira Dubai Hotel', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'ASSOCIATED', 'hotels', 'Corner Abu Baker Al Siddique and Sallahudin Road Opp Al Muraqqabat Police Station - Dubai - United Arab Emirates', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14431.988684767224!2d55.3295651!3d25.2706806!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3e5f5cc7207443e7%3A0xbd604b9c4399f34f!2sAvani%20Deira%20Dubai%20Hotel!5e0!3m2!1sen!2sin!4v1717384258609!5m2!1sen!2sin', 'This modern hotel is 9 km from the Dubai World Trade Centre, 4 km from the Dubai Gold Souk and Spice Souk traditional markets, and 13 km from the Burj Khalifa skyscraper.\n\nContemporary rooms feature flat-screen TVs, free Wi-Fi, rainfall showers, and tea and coffeemaking facilities. Suites add sitting areas, living rooms and terraces.\n\nTransfers to nearby shopping areas are complimentary. There\'s a heated rooftop pool, a fitness centre and a sauna. International and Indian dishes are served in a pair of restaurants. There\'s also a cocktail lounge.', 'assets/images/hotels/avani-deira-dubai-hotel/1.webp', 1),
(88, 'H502', 'best-western-plus-pearl-creek', 'Best Western Plus Pearl Creek', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Deira Creek - 90 Baniyas Rd - Deira - Al Rigga - Dubai - United Arab Emirates', 'https://www.google.com/maps/place/Best+Western+Plus+Pearl+Creek/@25.2677858,55.3046898,15z/data=!4m2!3m1!1s0x0:0x66e3a61eda35c860?sa=X&ved=2ahUKEwiTu5WrgY37AhVcoGMGHa8jDNIQ_BJ6BAh1EAU', 'Property Location With a stay at Best Western Premier Deira, you\'ll be centrally located in Dubai, within a 10-minute drive of Sahara Centre and Al-Maktoum Stadium. This 4-star hotel is 10.7 mi (17.3 km) from Dubai Mall and 11.1 mi (17.9 km) from Burj Khalifa. Rooms Make yourself at home in one of the 250 air-conditioned rooms featuring minibars and LCD televisions. Complimentary wireless Internet access keeps you connected, and satellite programming is available for your entertainment. Private bathrooms with shower/tub combinations feature deep soaking bathtubs and complimentary toiletries. Conveniences include safes and desks, and housekeeping is provided daily. Amenities Don\'t miss out on the many recreational opportunities, including a nightclub, a health club, and an indoor pool. Additional features at this hotel include complimentary wireless Internet access, concierge services, and gift shops/newsstands. Dining Enjoy a meal at the restaurant or snacks in the coffee shop/café. The hotel also offers 24-hour room service. Wrap up your day with a drink at the bar/lounge. Buffet breakfasts are served on weekdays from 7:00 AM to 10:30 AM for a fee. Business, Other Amenities Featured amenities include a business center, express check-in, and express check-out. Planning an event in Dubai? This hotel has 3057 square feet (284 square meters) of space consisting of conference space and meeting rooms.Rooms are irresistibly charming and urbane. The room is cosy in character with modern decor and memorable city views. The rooms are spacious and comfortable with plenty of natural daylight.', 'assets/images/hotels/best-western-plus-pearl-creek/1.webp', 1),
(89, 'H392', 'city-seasons-towers-hotel-dubai', 'City Seasons Towers Hotel Dubai', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', NULL, NULL, 'Set at BurJuman shopping mall, this sleek high-rise hotel is 2 km fomr the Dubai Museum and 9 km from landmark Burj Khalifa. Casual rooms come with free Wi-FI, flat-screen TVs and minifridges, as well as tea and coffeemaking facilities. Upgraded rooms add balconies. Suites provide separate living rooms.\n\nParking is complimentary. There\'s also a buffet restaurants, a lounge and a bar. Other amenities include a rooftop pool with a terrace and sunloungers, plus a gym and a spa. Breakfast is available for a fee.', 'assets/images/hotels/city-seasons-towers-hotel-dubai/1.webp', 1),
(90, 'H489', 'courtyard-by-marriott-dubai-green-community', 'Courtyard by Marriott Dubai, Green Community', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Green Community Village - Dubai - United Arab Emirates', 'https://www.google.com/maps/dir//Courtyard+by+Marriott+Dubai,+Green+Community+-+Green+Community+Village+-+Dubai+-+United+Arab+Emirates/@25.0034491,55.0948589,12z/data=!4m8!4m7!1m0!1m5!1m1!1s0x3e5f7326bf1b2e65:0x6171ac6c226c8204!2m2!1d55.1648992!2d25.0034655?hl=en-GB', 'Overlooking a picturesque lake, Copthorne Lakeview Hotel Dubai, Green Community offers an outdoor pool area that includes a separate children’s pool for the little ones and a relaxing terrace. The hotel adjoins a shopping mall which includes a large grocery shop, Choithrams, a nail salon, a hairdresser, a kids play area and several restaurants. Free WiFi is offered in the public areas. Ibn Battuta Mall is only 6 km away from the property. The contemporary air-conditioned rooms include a flat-screen TV and a seating area. All rooms include a private bathroom fitted with a shower and tub and offer free toiletries along with a hairdryer. Some rooms also include a balcony overlooking the tranquil lake and pool. Copthorne Lakeview Hotel Dubai, Green Community offers a choice of dining options, including a specialty all day dining restaurant, a Poolside Bar and a British style gastro-pub, Neighborhood. The newly refurbished contemporary banquet spaces include a private entrance. Opposite to the banquet spaces, the property offers a large outdoor terrace that can be connected to the venue to host special events and is perfect for an outdoor reception or break-out area. Guests can stay fit at the property’s fitness centre. Jumeirah beach is only a 15 minute drive from the property. Guests will find 3 championship golf courses within a 15-minute drive and the famous Ski Dubai is just 20 minutes away by car. IMG World and Dubai Parks and Resorts is a 20 minute drive from the property. The nearest airport is Al Maktoum International Airport which is a 20 minute drive from Copthorne Lakeview Hotel, Dubai.', 'assets/images/hotels/courtyard-by-marriott-dubai-green-community/1.webp', 1),
(91, 'H501', 'donatello-hotel-dubai', 'Donatello Hotel Dubai', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Sheikh Zayed Road, Al Barsha 1, Near Mall Of The Emirates - Dubai - United Arab Emirates', 'https://www.google.com/maps/place/Donatello+Hotel+Dubai/@25.115527,55.193946,15z/data=!4m2!3m1!1s0x0:0x9b8e109da78bf24c?sa=X&ved=2ahUKEwjtw4HbgI37AhX2g2MGHbaWDasQ_BJ6BQiAARAF', 'An oasis in the heart of the vibrant city of Dubai, this 4-star city-hotel aims to provide the most pleasant experience in every visit. The hotel is a mix of modern design and classic refinement blended with kind and personal service, traits that will make every guest feel right at home. Ideally located on Sheikh Zayed Road, mid-way between Downtown Dubai and Dubai Marina, the hotel offers convenient access to the city’s business hubs, popular malls, and tourist destinations making it a preferred place to stay for holiday tourists as well as business travelers.', 'assets/images/hotels/donatello-hotel-dubai/1.webp', 1),
(92, 'H785', 'emirates-grand-hotel', 'Emirates Grand Hotel', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'ASSOCIATED', 'hotels', '116957 Sheikh Zayed Rd - Trade Centre - Trade Centre 1 - Dubai - United Arab Emirates', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14439.027439109926!2d55.2742973!3d25.2114208!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3e5f43d7fdef48eb%3A0x3ad81bc6e76bae1d!2sEmirates%20Grand%20Hotel!5e0!3m2!1sen!2sin!4v1717384729623!5m2!1sen!2sin', 'Next to Financial Center Station, this relaxed apartment hotel is 5 km from Museum of The Future, and 4 km from both Burj Khalifa and the World Trade Centre. It\'s 12 km from Dubai International Airport.\n\nWarmly furnished apartments feature floor-to-ceiling windows and city views. All come with Wi-Fi and TVs, plus kitchenettes and sitting areas.\n\nThere\'s a 31st-floor restaurant offering panoramic city views, as well as an indoor pool, a gym, and a spa area with a sauna, a steam room and a hot tub. Breakfast is available.', 'assets/images/hotels/emirates-grand-hotel/1.webp', 1),
(93, 'H389', 'four-points-by-sheraton-downtown-dubai', 'Four Points by Sheraton Downtown Dubai', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', NULL, NULL, 'This upscale hotel with a glass facade is 6 km from the Dubai Gold Souk and 10 km from The Dubai Fountain. Modern rooms feature Wi-Fi and flat-screen TVs, plus floor-to-ceiling windows and minibars. Upgraded rooms have sitting areas. Suites add separate living rooms, dining areas, additional bathrooms and kitchenettes with washer/dryers. Room service is available.\n\nParking is complimentary. There are 3 restaurants, including a warm Italian eatery and a pub with big-screen sports, along with a coffee shop. There’s also a business centre and a gym, plus a hot tub, a sauna, and an outdoor pool with a sun deck.', 'assets/images/hotels/four-points-by-sheraton-downtown-dubai/1.webp', 1),
(94, 'H314', 'grand-excelsior-hotel-bur-dubai', 'Grand Excelsior Hotel Bur Dubai', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14434.343618843672!2d55.2922491!3d25.2508687!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x526be4296ee833e0!2sGrand%20Excelsior%20Hotel%20Bur%20Dubai!5e0!3m2!1sen!2sin!4v1631863143947!5m2!1sen!2sin', 'This upscale hotel is 8 km from The Dubai Mall and 7 km from the Dubai Spice Souk.\n\nFeaturing free Wi-Fi, the polished rooms with Arabic decor also come with flat-screen TVs, minibars, and tea and coffeemaking facilities. Upgraded rooms add access to a lounge. Luxe suites add whirlpool tubs, and separate living and/or dining areas. Room service is available 24/7.\n\nThere are 5 bars and restaurants including a refined international restaurant and a laid-back bar. There’s also a gym and a rooftop pool, plus a steam room, a sauna and a business center.', 'assets/images/hotels/grand-excelsior-hotel-bur-dubai/1.webp', 1),
(95, 'H377', 'holiday-inn-dubai-festival-city', 'Holiday Inn Dubai Festival City', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', NULL, NULL, 'This modern, polished hotel is an 11-minute walk from Dubai Festival City Mall and 6 km from Dubai International Airport. The airy rooms and suites feature free Wi-Fi, flat-screen TVs and minifridges, plus tea and coffeemaking facilities. Upgraded options add balconies or terraces. Suites add living areas or rooms with pull-out sofas. Kids age 12 and under stay at no charge with an adult. Room service is available 24/7.\n\nAmenities include a restaurant and a cafe. There\'s also a rooftop pool and a poolside bar, plus a fitness centre. A business centre and meeting space are also available.', 'assets/images/hotels/holiday-inn-dubai-festival-city/1.webp', 1),
(96, 'H385', 'hyatt-regency-dubai-creek-heights', 'Hyatt Regency Dubai Creek Heights', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', NULL, NULL, 'In a 34-storey modern tower overlooking Dubai Creek, this upscale hotel featuring a glass-domed lobby is 1 km from the bustling WAFI Mall. Featuring city and creek views, the sleek rooms offer free Wi-Fi, flat-screen TVs and iPod docks, plus minibars, and marble bathrooms with rainfall showers. Club rooms add free breakfast, while 1- to 3-bedroom suites have living rooms. There\'s 24/7 room service.\n\nValet parking is free. There are 6 restaurants and bars, including a Mexican eatery, and a top-floor bar with panoramic views. Other amenities include 2 gyms, a spa, and a pool with a swim-up bar, plus an 18-hole golf course and 2 grand ballrooms.', 'assets/images/hotels/hyatt-regency-dubai-creek-heights/1.webp', 1),
(97, 'H391', 'mercure-gold-hotel-al-mina-road-dubai', 'Mercure Gold Hotel Al Mina Road Dubai', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', NULL, NULL, 'Set in a building featuring ornate metalwork, this upscale hotel is 4 km from Dubai World Trade Centre and 8 km from the Burj Khalifa skyscraper. Bright rooms with floor-to-ceiling windows and a modern vibe feature free Wi-Fi, flat-screen TVs, minibars, and tea and coffeemaking facilities. Upgraded rooms have rainfall showers; suites add living rooms. Room service is available 24 hours.\n\nAmenities include 2 airy restaurants, with 1 serving international cuisine 24/7 and 1 serving Indian cuisine, plus a bar with regular live music. There\'s also a gym, a spa and a rooftop pool. Parking is available. Breakfast is extra.', 'assets/images/hotels/mercure-gold-hotel-al-mina-road-dubai/1.webp', 1),
(98, 'H313', 'park-regis-dubai', 'Park Regis Dubai', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14434.536625991943!2d55.3013456!3d25.2492443!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x779746d793ebc81c!2sPark%20Regis%20Kris%20Kin%20Hotel!5e0!3m2!1sen!2sin!4v1631863005486!5m2!1sen!2sin', 'An 8-minute walk from BurJuman Metro Station 1, this premium hotel is 4 km from the Dubai World Trade Centre and 8 km from The Dubai Mall.\n\nFeaturing floor-to-ceiling windows, the contemporary rooms offer free Wi-Fi, flat-screens and minibars, plus tea and coffeemaking facilities. Suites include living rooms, and access to a club lounge with perks such as drinks. Room service is available.\n\nAmenities include 2 sleek restaurants serving international cuisine, plus a sports bar and a nightclub. There\'s a gym, a hot tub, a sauna and a steam room, while a rooftop outdoor pool offers city views. A hair salon is also provided, plus a conference centre.', 'assets/images/hotels/park-regis-dubai/1.webp', 1),
(99, 'H312', 'ramada-by-wyndham-downtown-dubai', 'Ramada by Wyndham Downtown Dubai', 'Dubai', 'United Arab Emirates', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d17173.71292909442!2d55.268536111314816!3d25.192145088990205!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x78bd29d63e677212!2sRamada%20by%20Wyndham%20Downtown%20Dubai!5e0!3m2!1sen!2sin!4v1631862481980!5m2!1sen!2sin', 'A 9-minute walk from Jumeirah Lakes Towers Metro Station 1 & 2, this upscale hotel is 4 km from Emirates Golf Club and 10.7 km from Palm Jumeirah.\n\nThe chic rooms come with free WiFi, flat-screen TVs and 24-hour room service; many have balconies and fully equipped kitchens. Upgraded options add separate living areas. Kids 17 and under stay free with an adult.\n\nThe property has 4 restaurants (for Mediterranean, Chinese, Japanese and English cuisine), a lounge and a pastry shop. There\'s also an outdoor pool and a hot tub, plus a fitness center, 4 meeting rooms and a business center. An airport shuttle is available.', 'assets/images/hotels/ramada-by-wyndham-downtown-dubai/1.webp', 1),
(100, 'H268', 'gangtok-lemon-tree', 'GANGTOK LEMON TREE', 'Gangtok', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14175.868149156448!2d88.608043!3d27.345499!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x8bba67d12f8ef5b9!2sLemon%20Tree%20Hotel%2C%20Gangtok!5e0!3m2!1sen!2sin!4v1630388096765!5m2!1sen!2sin', 'Enjoy recreational amenities such as an outdoor pool and a fitness center.Know Before You Go Only registered guests are allowed in the guestrooms. Free in-room WiFi has a 1-device limit. WiFi in public areas is also free and has a 1-device limit. Renovations and Closures The property is undergoing renovations. The following areas are affected: Bar/loungeFitness facilitiesSpa The following facilities are closed until further notice:Bar/LoungeFitness facilitiesSpa During renovations, the hotel will make every effort to minimize noise and disturbance.Gym, spa, and bar are currently not available at the property,The property is located in Sikkim. As per the law, all foreigners must obtain Inner Line Permit (ILP) to visit Sikkim. These can be obtained from all Indian Missions, Sikkim Tourism Offices at New Delhi, Kolkata, District Magistrates Office of Darjeeling, Siliguri, and Rangpo on the strength of an Indian Visa.With a stay at Lemon Tree Hotel Gangtok in Gangtok, you\'ll be convenient to Ganesh Tok and Enchey Monastery. At the foot of the Himalayas, this relaxed hotel with sloping roofs and arched windows is 5 km from the Enchey Monastery, 8 km from Sikkim Himalayan Zoological Park and 30 km from Pakyong Airport. Unfussy rooms feature flat-screen TVs, Wi-Fi access, and tea and coffeemaking equipment, as well as safes. Upgraded suites add separate living areas. DVD players and minifridges are available on request. A breakfast buffet is complimentary. Other amenities include a casual restaurant, a bar and an outdoor pool, plus a spa, a fitness centre and meeting facilities.', 'assets/images/hotels/gangtok-lemon-tree/1.webp', 1),
(101, 'H317', 'golden-crest-gangtok', 'golden crest gangtok', 'Gangtok', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14178.971127804616!2d88.6070871!3d27.3212375!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x75c96931ea1d8a37!2sThe%20Golden%20Crest%20Hotel!5e0!3m2!1sen!2sin!4v1631872695690!5m2!1sen!2sin', 'Nestled among trees, this laid-back hotel is a kilometre from the museum at the Namgyal Institute of Tibetology, and 6 km from the Banjhakri Falls and Energy Park theme park.\n\nThe warmly decorated rooms come with free Wi-Fi, TVs, and tea and coffeemaking facilities. Upgraded rooms add scenic views, and some have air-conditioning. Room service is available 24/7.\n\nBreakfast and parking are complimentary. There\'s also an understated restaurant that offers international cuisine.', 'assets/images/hotels/golden-crest-gangtok/1.webp', 1),
(102, 'H483', 'mann-tamarind-residency', 'Mann Tamarind Residency', 'Gangtok', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'JN Rd, next to Mann Sidlon Residency, below Mitokgang, Chandmari, Gangtok, Sikkim 737101', 'https://www.google.com/maps/place/Mann+Tamarind+Residency,+Gangtok/@27.3376614,88.6240059,15z/data=!4m2!3m1!1s0x0:0x4fb8d5218af5c7c7?sa=X&hl=en&ved=2ahUKEwjty_HR_4n7AhVo8zgGHbjPCKwQ_BJ6BAhzEAU', 'The Tamarind Residency, a rare jewel nestled in the lap of the Himalayas offers natural beauty with breath taking valley view, tastefully designed decor that will arouse your senses for a perfect dream holiday in lavish Sikkimese hospitality. The Tamarind Residency in Gangtok is the only family owned, family run hotel in the 3 star categories focused in perfecting your experience.Our views are exactly as what you would like for a luxurious stay in a hill-station in the serene atmosphere of the snowy mountain range.We are located on the Ridge which is perfect tourist spot. The Ridge Park along with Flower Exhibition Centre is perhaps the only place which has special attachment in every Sikkimese Life.', 'assets/images/hotels/mann-tamarind-residency/1.webp', 1),
(103, 'H484', 'royal-orchid-and-spa', 'Royal Orchid & Spa', 'Gangtok', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; wellness-retreats', 'Indira Bypass Rd, Upper Sichey, Arithang, Gangtok, Sikkim 737101', 'https://www.google.com/maps/place/Jain+Group+%7C+Royal+Orchid+%26+Spa+%7C/@27.3347429,88.6128742,15z/data=!4m2!3m1!1s0x0:0x8fd539b869840115?sa=X&ved=2ahUKEwiZyJaogIr7AhU47zgGHQ3XCPIQ_BJ6BAh_EAU', 'Discover a world of indelible experiences at Jain Group Hotels where fine dining and prompt service converge with in-room technologies and pre-eminent rooms and suites. We offer you healthy vegetarian & Jain meals, rooms with the best comfort features, relaxing spa services, hospitality that makes you feel close to home, all in the midst of majestic mountains and calming destinations. We pride ourselves because of our taste and health friendly chefs, warm and welcoming decor, the options of both luxury and budget stays.', 'assets/images/hotels/royal-orchid-and-spa/1.webp', 1),
(104, 'H666', 'summit-namnang-courtyard-and-spa-gangtok-gangtok', 'Summit Namnang Courtyard & Spa, Gangtok - Gangtok', 'Gangtok', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels; wellness-retreats', 'Nam Nang Rd, below Big Bazaar, Vishal Gaon, Gangtok, Sikkim 737101', NULL, 'Summit Namnang Courtyard & Spa, Gangtok is a hotel in Gangtok, India. Its address is Nam Nang Rd, below Big Bazaar, Vishal Gaon, Gangtok, Sikkim 737101. Popular places to visit in Gangtok include Nathula Pass, MG Marg and Rumtek Monastery.', 'assets/images/hotels/summit-namnang-courtyard-and-spa-gangtok-gangtok/1.webp', 1),
(105, 'H668', 'the-fern-denzong-hotel-and-spa-gangtok', 'The Fern Denzong Hotel & Spa - Gangtok', 'Gangtok', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels; wellness-retreats', 'Kazi Rd, Vishal Gaon, Gangtok, Sikkim 737101', NULL, 'Located in Gangtok, India, The Fern Denzong Hotel & Spa is part of the Galaxy Heritage World network of hotels and resorts. Find it at Kazi Rd, Vishal Gaon, Gangtok, Sikkim 737101. Popular places to visit in Gangtok include Nathula Pass, MG Marg and Rumtek Monastery.', 'assets/images/hotels/the-fern-denzong-hotel-and-spa-gangtok/1.webp', 1),
(106, 'H667', 'udaan-hotels-woodberry-hotel-and-spa-gangtok', 'Udaan Hotels | Woodberry Hotel & Spa - Gangtok', 'Gangtok', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels; wellness-retreats', 'Near Swastik Gate, Upper Burtuk, Gangtok, Sikkim 737101', NULL, 'Located in Gangtok, India, Woodberry Hotel & Spa is part of the Galaxy Heritage World network of hotels and resorts. Find it at Near Swastik Gate, Upper Burtuk, Gangtok, Sikkim 737101. Popular places to visit in Gangtok include Nathula Pass, MG Marg and Rumtek Monastery.', 'assets/images/hotels/udaan-hotels-woodberry-hotel-and-spa-gangtok/1.webp', 1),
(107, 'H542', 'hotel-manisha-international', 'Hotel Manisha International', 'Gaya', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Station Road Infront Of petrol Pump, Bihar 823001', 'https://www.google.com/maps/place/Hotel+Manisha+International/@24.8010021,85.0003811,15z/data=!4m2!3m1!1s0x0:0x975c7ff7661096ca?sa=X&ved=2ahUKEwiF-PONwpL7AhUMt2MGHQ-VBLoQ_BJ6BAhyEAU', 'Hotel Manisha International in Gaya Railway Station, Gaya\nHotel Manisha International listed under Hotels in Gaya Railway Station, Gaya. Check Address, Contact Number, Ratings & Reviews, Photos, Maps etc, on Justdial.\n\nWhether it is a vacation with family or a business trip, everyone looks for safe hotels Hotels that have the best facilities. Apart from the basic facilities, some of the exclusive places also have a spa, kid\'s area, pool and more to offer the best service to the guests. From bed and breakfast to complimentary meals, you can enjoy some of the best services when you book the right place.\n\nHotel Manisha International in Gaya Railway Station Gaya welcomes people from all walks of life. It has some of the best services, such as Tour Assistance, Shuttle Services, Daily Housekeeping, 24x7 Facility Manager Present to make the stay memorable.', 'assets/images/hotels/hotel-manisha-international/1.webp', 1),
(108, 'H654', 'maha-bodhi-hotel-resort-and-convention-centre-gaya', 'Maha Bodhi Hotel,Resort and Convention Centre - Gaya', 'Gaya', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', 'Hariharpur, Bihar 823004', NULL, 'Stay at Maha Bodhi Hotel,Resort and Convention Centre in Gaya, India. The address is Hariharpur, Bihar 823004. Popular places to visit in Gaya include Mahabodhi Temple, Bodhi Tree and Great Buddha Statue.', 'assets/images/hotels/maha-bodhi-hotel-resort-and-convention-centre-gaya/1.webp', 1),
(109, 'GEO01', 'radisson-blu-iveria-tbilisi', 'Radisson Blu Iveria Tbilisi', 'Georgia', 'Georgia', 'INTERNATIONAL', 'HOTEL', 'ASSOCIATED', 'hotels', 'Radisson Blu Iveria Tbilisi, Main Road, Georgia, Georgia', 'https://maps.google.com/?q=Radisson%20Blu%20Iveria%20Tbilisi%20Georgia', 'Experience luxury hospitality at Radisson Blu Iveria Tbilisi in Georgia, featuring modern amenities and exceptional service.', 'assets/images/hotels/radisson-blu-iveria-tbilisi/1.webp', 1),
(110, 'GEO02', 'rooms-hotel-kazbegi', 'Rooms Hotel Kazbegi', 'Georgia', 'Georgia', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Rooms Hotel Kazbegi, Main Road, Georgia, Georgia', 'https://maps.google.com/?q=Rooms%20Hotel%20Kazbegi%20Georgia', 'Experience luxury hospitality at Rooms Hotel Kazbegi in Georgia, featuring modern amenities and exceptional service.', 'assets/images/hotels/rooms-hotel-kazbegi/1.webp', 1),
(111, 'H371', 'cygnett-inn-celestiial-goa', 'Cygnett Inn Celestiial Goa', 'Goa', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15376.656416112774!2d73.764768!3d15.529331!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x4ab7a693ae6eb4c7!2sCygnett%20Inn%20Celestiial!5e0!3m2!1sen!2sin!4v1632484113526!5m2!1sen!2sin\'', 'A 6-minute walk from the beach, this modern hotel is 6 km from the Shanta Durga Temple and 11 km from the 18th-century Chapora Fort.\n\nElegant rooms feature marble floors and dark wood furnishings, as well as free Wi-Fi and flat-screen TVs. All have minibars, and tea and coffeemaking equipment, plus balconies offering city views. Room service is available.\n\nComplimentary breakfast is served in a chic restaurant that specialises in seafood. There\'s also an outdoor pool.', 'assets/images/hotels/cygnett-inn-celestiial-goa/1.webp', 1),
(112, 'H370', 'golden-tulip-grand-view-resort-goa', 'Golden Tulip Grand View Resort Goa', 'Goa', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', NULL, 'ttps://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15377.993863563957!2d73.7739797!3d15.5113865!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xa3bdbda41832d6a0!2sGolden%20Tulip%20Grand%20View%20Resort%20Candolim%20Goa!5e0!3m2!1sen!2sin!4v1632483758015!5m2!1sen!2sin', 'A 12-minute walk from Candolim Beach, this upscale hotel is 5 km from the Fort Aguada lighthouse and 11 km from the Casino Royale Goa.\n\nContemporary rooms with balconies provide flat-screen TVs, free Wi-Fi and minibars, as well as desks, safes, and tea and coffeemaking facilities. The 2-bedroom apartments add kitchenettes and living rooms. Room service is offered 24/7.\n\nParking and a breakfast buffet are complimentary. A spa has hot tubs and saunas. Other amenities include a sleek restaurant/bar next to an outdoor pool and kids\' pool, plus a gym, tennis courts, and a game room with table tennis.', 'assets/images/hotels/golden-tulip-grand-view-resort-goa/1.webp', 1),
(113, 'H671', 'i-love-bell-bottoms-goa', 'I Love Bell Bottoms - Goa', 'Goa', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', '544, 2, Ozran Beach Rd, Coutinho Vaddo, Anjuna, Goa 403509', NULL, 'I Love Bell Bottoms is a hotel in Goa, India. Its address is 544, 2, Ozran Beach Rd, Coutinho Vaddo, Anjuna, Goa 403509. Popular places to visit in Goa include Baga Beach, Calangute Beach and Dudhsagar Falls.', 'assets/images/hotels/i-love-bell-bottoms-goa/1.webp', 1),
(114, 'H272', 'lemon-tree-hotel-candolim', 'LEMON TREE HOTEL CANDOLIM', 'Goa', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15377.566725575514!2d73.7685555!3d15.5171196!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xb188e4f6c0eb7dfb!2sLemon%20Tree%20Hotel%20Candolim%2C%20Goa!5e0!3m2!1sen!2sin!4v1630391017995!5m2!1sen!2sin', 'The resort offers 65 beautiful rooms and suites. All ground floor rooms provide access to a compact private garden. The six heritage rooms and suite, housed in a century old Portuguese mansion, have been restored to their original glory and appointed with all modern amenities.', 'assets/images/hotels/lemon-tree-hotel-candolim/1.webp', 1),
(115, 'H761', 'resort-de-coracao-calangute-goa', 'Resort De coracao - Calangute Goa', 'Goa', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', 'Gauravaddo, Near St. Anthony Chapel, Calangute, Goa 403516', '-', 'Resort De coracao is located in Goa, India. Its address is Gauravaddo, Near St. Anthony Chapel, Calangute, Goa 403516. Popular places to visit in Goa include Baga Beach, Calangute Beach and Dudhsagar Falls.', 'assets/images/hotels/resort-de-coracao-calangute-goa/1.webp', 1),
(116, 'H340', 'resort-de-coracao-goa', 'Resort De Coracao, Goa', 'Goa', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15376.174425541865!2d73.7644206!3d15.5357929!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xaff63729b3184061!2sResort%20De%20Coracao%20By%20FIRST%20HALT%20-%20Calangute%20%2CGoa!5e0!3m2!1sen!2sin!4v1632035150348!5m2!1sen!2sin', 'An 11-minute walk from Calangute Beach, this unassuming resort is 6 minutes\' walk from the nearest bus stop, and 11 km from the Salim Ali Bird Sanctuary.\n\nThe casual rooms feature Wi-Fi, satellite TV and private balconies. They also offer minibars and rainfall showers, as well as tea and coffeemaking facilities. Upgraded rooms and suites add separate living areas. Room service is available.\n\nAmenities include an outdoor pool, a poolside bar, a multi-cuisine restaurant and fitness facilities. There\'s also a hot tub, a steam room, a business centre and a conference room. Breakfast is available', 'assets/images/hotels/resort-de-coracao-goa/1.webp', 1),
(117, 'H670', 'somy-resort-goa', 'Somy Resort - Goa', 'Goa', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', 'Naikawaddo, Bardez, Opp. HDFC Bank, Calangute, Goa 403516', NULL, 'Stay at Somy Resort in Goa, India. The address is Naikawaddo, Bardez, Opp. HDFC Bank, Calangute, Goa 403516. Popular places to visit in Goa include Baga Beach, Calangute Beach and Dudhsagar Falls.', 'assets/images/hotels/somy-resort-goa/1.webp', 1),
(118, 'H669', 'stone-woods-resort-and-spa-goa', 'Stone Woods Resort & SPA - Goa', 'Goa', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts; wellness-retreats', 'Stone Wood Resort & Spa Asvewada, Ashwem-Morjim Road, Goa, Goa 403527', NULL, 'Stone Woods Resort & SPA is located in Goa, India. Its address is Stone Wood Resort & Spa Asvewada, Ashwem-Morjim Road, Goa, Goa 403527. Popular places to visit in Goa include Baga Beach, Calangute Beach and Dudhsagar Falls.', 'assets/images/hotels/stone-woods-resort-and-spa-goa/1.webp', 1),
(119, 'H319', 'the-acacia-hotel-and-spa-goa', 'The Acacia Hotel & Spa Goa', 'Goa', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels; wellness-retreats', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15377.874099268098!2d73.7691382!3d15.5129942!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x36c5508f56167721!2sThe%20Acacia%20Hotel%20%26%20Spa%20Goa!5e0!3m2!1sen!2sin!4v1631873639142!5m2!1sen!2sin', 'Across the road from a bus stop along a bustling commercial street, this polished hotel with views of the Arabian Sea is a 14-minute walk from Candolim Beach and 5 km from Fort Aguada, a 17th-century Portuguese stronghold.\n\nFeaturing balconies, the chic rooms have Wi-Fi, flat-screen TVs and minibars, plus tea and coffeemaking facilities. Suites add living rooms. Room service is available.\n\nBreakfast is served in a casual 24-hour eatery. There\'s also a rooftop restaurant with sea views, as well as a fine dining venue with an Arthurian theme. Other amenities include an outdoor pool and a tranquil spa', 'assets/images/hotels/the-acacia-hotel-and-spa-goa/1.webp', 1),
(120, 'H672', 'the-ivy-anjuna-goa', 'The Ivy Anjuna - Goa', 'Goa', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'D mello Vaddo, near Starco Junction, Anjuna, Goa 403502', NULL, 'Located in Goa, India, The Ivy Anjuna is part of the Galaxy Heritage World network of hotels and resorts. Find it at D mello Vaddo, near Starco Junction, Anjuna, Goa 403502. Popular places to visit in Goa include Baga Beach, Calangute Beach and Dudhsagar Falls.', 'assets/images/hotels/the-ivy-anjuna-goa/1.webp', 1)
