(121, 'H664', 'itc-fortune-global-select-gurgaon', 'ITC FORTUNE GLOBAL SELECT - Gurgaon', 'Gurgaon', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Global Arcade, Mehrauli-Gurgaon Rd, Sector 26, Gurugram, Haryana 122002', NULL, 'Stay at ITC FORTUNE GLOBAL SELECT, a hotel in Gurgaon, India. The address is Global Arcade, Mehrauli-Gurgaon Rd, Sector 26, Gurugram, Haryana 122002. Popular places to visit in Gurgaon include Cyber Hub, Kingdom of Dreams and Sultanpur National Park.', 'assets/images/hotels/itc-fortune-global-select-gurgaon/1.webp', 1),
(122, 'H665', 'ramada-by-wyndham-gurgaon-central-gurgaon', 'Ramada by Wyndham Gurgaon Central - Gurgaon', 'Gurgaon', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Plot 2, Bhagwan Mahaveer Marg, Sector 44, Gurugram, Haryana 122003', NULL, 'Stay at Ramada by Wyndham Gurgaon Central, a hotel in Gurgaon, India. The address is Plot 2, Bhagwan Mahaveer Marg, Sector 44, Gurugram, Haryana 122003. Popular places to visit in Gurgaon include Cyber Hub, Kingdom of Dreams and Sultanpur National Park.', 'assets/images/hotels/ramada-by-wyndham-gurgaon-central-gurgaon/1.webp', 1),
(123, 'H546', 'radisson-gwalior', 'Radisson Gwalior', 'Gwalior', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Plot No. 13-14, behind Sada Office, City Center, Mahalgaon, Gwalior, Madhya Pradesh 474011', 'https://www.google.com/maps/place/Radisson+Gwalior/@26.2053022,78.1917612,15z/data=!4m2!3m1!1s0x0:0x6c45fc2dda1a61f2?sa=X&ved=2ahUKEwjI5NvfypL7AhX69DgGHQTvBmEQ_BJ6BQiBARAF', 'Located in the centre of Gwalior’s corporate district, Radisson Gwalior provides a perfect home base for business and leisure travelers seeking proximity to Rajmata Vijaya Raje Scindia Air Terminal (GWL) and the offices of businesses like SBI and HDFC Bank. Make your visit memorable when you tour the temples and palaces at Gwalior Fort, less than seven kilometers from the hotel, or take the three-kilometer drive to DB City mall to shop. If you’re in town for meetings in Malanpur, the city’s industrial hub is just about 25 kilometers away. After a day of meetings, touring temples or shopping, return to the hotel to enjoy a delicious meal and relax by the swimming pool. You can also recharge with a workout in our fitness center', 'assets/images/hotels/radisson-gwalior/1.webp', 1),
(124, 'H295', 'ambrosia-sarovar-portico-haridwar', 'AMBROSIA SAROVAR PORTICO HARIDWAR', 'Haridwar', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13834.949425994719!2d77.988196!3d29.9006676!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x8b656ac45007c649!2sAmbrosia%20Sarovar%20Portico%20I%20Hotel%20in%20Haridwar!5e0!3m2!1sen!2sin!4v1631011793852!5m2!1sen!2sin', 'One of our top picks in HaridwÄÂr. Ambrosia Sarovar Portico is located 200 m from the Crystal Water Park, and 14 km from Roorkee Railway Station. It offers 2 dining options, a fitness centre and free Wi-Fi access. Air-conditioned guest rooms are fitted with a minibar, tea/coffee making facilities and a flat-screen TV with satellite channels. The en suite bathroom comes with toiletries and shower. The tour desk can assist with making travel arrangements. Laundry and dry cleaning services are offered. Clove Restaurant serves a variety of Indian and international dishes. Drinks can be enjoyed at the Bubbles Bar. Sarovar Portico Ambrosia is a 60-minute drive from Jolly Grant Airport. Rishikesh is 30 km away. We speak your language!', 'assets/images/hotels/ambrosia-sarovar-portico-haridwar/1.webp', 1),
(125, 'H547', 'fortune-park-hotel-in-haridwar', 'Fortune Park - Hotel in Haridwar', 'Haridwar', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Fortune Park - Hotel in Haridwar', 'https://www.google.com/maps/place/Fortune+Park+-+Hotel+in+Haridwar/@29.9189608,78.0582097,15z/data=!4m2!3m1!1s0x0:0x2026e73cee6cbcb9?sa=X&ved=2ahUKEwjFtPjyzJL7AhXy-DgGHUQ2DmIQ_BJ6BAh5EAU', 'Fortune Park, Haridwar is strategically located on the National Highway 58 (NH-58) and is just 12 km away from Har ki Pauri. Business travellers can easily reach the industrial hub, SIDCUL as it is only 5 km away from the property. The hotel is well equipped with modern and upscale amenities and offers efficient service at great value to the discerning traveller. The hotel offers a selection of 48 spacious & contemporary rooms and suites, a Multicuisine restaurant, 24 hrs In-Room dining, Fitness Centre and a Pastry Shop.', 'assets/images/hotels/fortune-park-hotel-in-haridwar/1.webp', 1),
(126, 'H767', 'hotel-flora', 'Hotel Flora', 'Haridwar', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'बहादराबाद, Industrial Area, Haridwar, Uttarakhand 249403', '-', 'Located in Haridwar, India, Hotel Flora is part of the Galaxy Heritage World network of hotels and resorts. Find it at बहादराबाद, Industrial Area, Haridwar, Uttarakhand 249403. Popular places to visit in Haridwar include Har Ki Pauri, Mansa Devi Temple and Chandi Devi Temple.', 'assets/images/hotels/hotel-flora/1.webp', 1),
(127, 'H661', 'regenta-orkos-haridwar', 'Regenta Orkos - Haridwar', 'Haridwar', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Motichur, Rishikesh Highway, Haripur Kalan, Haridwar, Uttarakhand 249205', NULL, 'Located in Haridwar, India, Regenta Orkos is part of the Galaxy Heritage World network of hotels and resorts. Find it at Motichur, Rishikesh Highway, Haripur Kalan, Haridwar, Uttarakhand 249205. Popular places to visit in Haridwar include Har Ki Pauri, Mansa Devi Temple and Chandi Devi Temple.', 'assets/images/hotels/regenta-orkos-haridwar/1.webp', 1),
(128, 'H660', 'the-fern-residency-haridwar', 'The Fern Residency - Haridwar', 'Haridwar', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'NH-58, Rishikesh Rd, opposite Dev Sanskriti University, Haridwar, Uttarakhand 249411', NULL, 'The Fern Residency is a hotel in Haridwar, India. Its address is NH-58, Rishikesh Rd, opposite Dev Sanskriti University, Haridwar, Uttarakhand 249411. Popular places to visit in Haridwar include Har Ki Pauri, Mansa Devi Temple and Chandi Devi Temple.', 'assets/images/hotels/the-fern-residency-haridwar/1.webp', 1),
(129, 'H574', 'hyderabad-marriott-hotel-and-convention-centre', 'Hyderabad Marriott Hotel & Convention Centre', 'Hyderabad', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Tank Bund Rd, opposite Hussain Sagar, Bhagyalaxmi Nagar, Lake, Hyderabad, Telangana 500080', 'https://www.google.com/maps/place/Hyderabad+Marriott+Hotel+%26+Convention+Centre/@17.4242848,78.4871452,15z/data=!4m2!3m1!1s0x0:0x491645e2972a865b?sa=X&ved=2ahUKEwiG87zcyZf7AhWETWwGHYzaCKIQ_BJ6BQiAARAF', 'Overlooking Hussain Sagar Lake, Hyderabad Marriott Hotel & Convention Centre blends fresh style and traditional aesthetics to provide premium accommodation for the business and leisure traveler. Situated in the heart of the city, our Hyderabad, India hotel is conveniently located just 35 mins from the Rajiv Gandhi International Airport and has an easy access to the business districts US Consulate, HICC, Hitech City; along with the historic monuments like SalarJung Museum, Charminar, Golkonda & Laad Bazaar. An ideal destination for conventions, we house a Convention Centre with the latest AV and interpretation facilities. The hotel’s picturesque location with 13,000 sq ft of outdoor spaces and sumptuous restaurants make it a popular Convention destination in India.', 'assets/images/hotels/hyderabad-marriott-hotel-and-convention-centre/1.webp', 1),
(130, 'H368', 'mercure-hyderabad', 'Mercure Hyderabad', 'Hyderabad', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15227.50902502306!2d78.4566974!3d17.4176772!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x7ea2985c469f1ed8!2sMercure%20Hyderabad%20KCP!5e0!3m2!1sen!2sin!4v1632483310756!5m2!1sen!2sin', 'Set in the Banjara Hills district, this modern hotel is 10 minutes\' walk from Khairatabad Railway Station, 3 km from the hilltop Birla Mandir temple and 9 km from the 16th-century Charminar mosque.\n\nWarmly decorated rooms come with iPod docks, limited free Wi-Fi and flat-screen TVs, along with minifridges, safes and desks. All offer tea and coffeemaking facilities; some have themed decor. Room service is available.\n\nAmenities include an all-day restaurant, a rooftop eatery and a cafe, plus a bar/lounge, a gym and a business center. There are also 5 meeting rooms, as well as an airport shuttle (fee). Parking is available.', 'assets/images/hotels/mercure-hyderabad/1.webp', 1),
(131, 'H548', 'novotel-hyderabad-convention-centre', 'Novotel Hyderabad Convention Centre', 'Hyderabad', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'P O Bag 1101, near Hitec City, Kondapur, Telangana 500081', 'https://www.google.com/maps/place/Novotel+Hyderabad+Convention+Centre/@17.4727877,78.3731923,15z/data=!4m2!3m1!1s0x0:0xf7ffe9c0885c159b?sa=X&ved=2ahUKEwiwpPGQz5L7AhXFt2MGHZ9vAFkQ_BJ6BQiTARAF', 'Novotel Hyderabad Convention Centre is located in Hyderabad\'s IT and Business district and is connected to South Asia\'s finest & largest pillar free convention centre - Hyderabad International Convention Centre, offering state-of-the-art exhibition, meeting and convention services. The hotel, located in HITEC City is 45 minutes drive from The Rajiv Gandhi International Airport and spread over 15 acres. It has been designed to provide a comfortable and a friendly environment for the business and leisure traveler. Key features are Hi-speed internet, Wi-Fi enabled rooms, award winning wine and dine options: Food Exchange, La Cantina, Le Cafe, The Bar, 24 hrs fitness centre, outdoor pool & jogging track and a spa/salon.', 'assets/images/hotels/novotel-hyderabad-convention-centre/1.webp', 1),
(132, 'H655', 'the-manohar-hyderabad', 'The Manohar - Hyderabad', 'Hyderabad', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Begumpet Airport Road, Motilal Nehru Nagar, Begumpet, Hyderabad, Telangana 500016', NULL, 'Stay at The Manohar, a hotel in Hyderabad, India. The address is Begumpet Airport Road, Motilal Nehru Nagar, Begumpet, Hyderabad, Telangana 500016. Popular places to visit in Hyderabad include Charminar, Golkonda Fort and Hussain Sagar Lake.', 'assets/images/hotels/the-manohar-hyderabad/1.webp', 1),
(133, 'IDN01', 'hotel-indonesia-kempinski-jakarta', 'Hotel Indonesia Kempinski Jakarta', 'Indonesia', 'Indonesia', 'INTERNATIONAL', 'HOTEL', 'ASSOCIATED', 'hotels', 'Hotel Indonesia Kempinski Jakarta, Main Road, Indonesia, Indonesia', 'https://maps.google.com/?q=Hotel%20Indonesia%20Kempinski%20Jakarta%20Indonesia', 'Experience luxury hospitality at Hotel Indonesia Kempinski Jakarta in Indonesia, featuring modern amenities and exceptional service.', 'assets/images/hotels/hotel-indonesia-kempinski-jakarta/1.webp', 1),
(134, 'IDN02', 'the-mulia-bali', 'The Mulia Bali', 'Indonesia', 'Indonesia', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'The Mulia Bali, Main Road, Indonesia, Indonesia', 'https://maps.google.com/?q=The%20Mulia%20Bali%20Indonesia', 'Experience luxury hospitality at The Mulia Bali in Indonesia, featuring modern amenities and exceptional service.', 'assets/images/hotels/the-mulia-bali/1.webp', 1),
(135, 'H652', 'hotel-regenta-central-indore-indore', 'HOTEL REGENTA CENTRAL INDORE - Indore', 'Indore', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'OMAXE CITY 2, Mumbai - Agra National Hwy, BYPASS, Indore, Madhya Pradesh 453771', NULL, 'HOTEL REGENTA CENTRAL INDORE is located in Indore, India. Its address is OMAXE CITY 2, Mumbai - Agra National Hwy, BYPASS, Indore, Madhya Pradesh 453771. Popular places to visit in Indore include Rajwada Palace, Lal Bagh Palace and Kanch Mandir.', 'assets/images/hotels/hotel-regenta-central-indore-indore/1.webp', 1),
(136, 'H507', 'holiday-inn-istanbul-old-city-an-ihg-hotel', 'Holiday Inn Istanbul - Old City, an IHG Hotel', 'Istanbul', 'Turkey', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Gencturk Cad. Sirvanizade Sok, Vezneciler Cd. No:5, 34134 Fatih/İstanbul', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KSE3Bk6IucoUMdxCZBvTT2TV&daddr=Holiday+Inn+Istanbul+-+Old+City,+an+IHG+Hotel,+Gencturk+Cad.+Sirvanizade+Sok,+Vezneciler+Cd.+No:5,+34134+Fatih/%C4%B0stanbul,+Turkey', 'Located in the Old City of Istanbul, Holiday Inn Istanbul - Old City is a 12-minute walk from the Grand Bazaar. Among the facilities of this property are a spa and fitness centre, business centre, restaurant, paid valet parking, 24-hour front desk and room service, along with free WiFi throughout the property. The hotel is close to popular attractions like Sultanahmet Square, Hagia Sophia Museum, Blue Mosque, Topkapi Palace and Basilica Cistern.', 'assets/images/hotels/holiday-inn-istanbul-old-city-an-ihg-hotel/1.webp', 1),
(137, 'H506', 'radisson-blu-hotel-istanbul-ottomare', 'Radisson Blu Hotel Istanbul Ottomare', 'Istanbul', 'Turkey', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Kazlıçeşme, Abay Cd No: 223, 34020 Zeytinburnu/İstanbul, Turkey', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KaPFxbGdu8oUMc5UjOjY32N-&daddr=Kazl%C4%B1%C3%A7e%C5%9Fme,+Radisson+Blu+Hotel+Istanbul+Ottomare,+Abay+Cd+No:+223,+34020+Zeytinburnu/%C4%B0stanbul,+Turkey', 'Whether you\'re traveling for business or leisure, you\'ll enjoy a relaxing stay at the Radisson Blu Hotel, Istanbul Ottomare. With a beautiful location on the Sea of Marmara, the Radisson Blu Hotel Istanbul Ottomare offers scenic accommodation during your stay in this exquisite area. Conveniently located next to Istanbul\'s Old Town, our Ottomare hotel places you in the bustling Zeytinburnu district. We offer 133 elegant rooms and suites with contemporary features like marble bathrooms, plush bedding and free high-speed Wi-Fi. Brew fresh coffee and tea in the comfort of your room each morning, or visit our on-site Veranda Restaurant,for the daily Super Breakfast Buffet. Our stylish bar and Starbucks in the lobby and pool areas make sure you are never far from a refreshing drink or snack Other facilities at the hotel include our Exclusive Spa, which features a fitness center, sauna, Turkish bath and swimming pools.', 'assets/images/hotels/radisson-blu-hotel-istanbul-ottomare/1.webp', 1),
(138, 'H760', 'bhanwar-singh-palace-jaipur', 'Bhanwar Singh Palace Jaipur', 'Jaipur', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; heritage-homes; castles', 'Opposite Solitaire Park, Ajmer Highway, 1, Km After Highway, King, Bagru, Rajasthan 303007', '-', 'Set on a 9-hectare property, this upscale hotel just off the NH48 road is 2 km from Manipal University Jaipur and 4 km from Solitaire Industrial Park.\n\nWarm rooms with a traditional decor offer safes, minifridges and TVs. Upgraded rooms have 4-poster beds, balconies and/or terraces. Suites feature minibars and separate living areas. Room service is available 24/7.\n\nThere’s an outdoor pool flanked by palm trees. Other amenities include an airy upscale restaurant and a prayer room, as well as meeting and special event space for up to 2,000 guests.', 'assets/images/hotels/bhanwar-singh-palace-jaipur/1.webp', 1),
(139, 'H728', 'four-points-by-sheraton-jaipur-h728', 'FOUR POINTS BY SHERATON - Jaipur', 'Jaipur', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'City Square, Tonk Rd, Vasundhara Colony, Jaipur, Rajasthan 302018', NULL, 'Located in Jaipur, India, FOUR POINTS BY SHERATON is part of the Galaxy Heritage World network of hotels and resorts. Find it at City Square, Tonk Rd, Vasundhara Colony, Jaipur, Rajasthan 302018. Popular places to visit in Jaipur include Hawa Mahal, Amber Fort and City Palace.', 'assets/images/hotels/four-points-by-sheraton-jaipur-h728/1.webp', 1),
(140, 'H363', 'four-points-by-sheraton-jaipur', 'Four Points by Sheraton Jaipur', 'Jaipur', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14236.873359748703!2d75.7958555!3d26.8648033!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xbece5cb668ea930c!2sFour%20Points%20by%20Sheraton%20Jaipur%2C%20City%20Square!5e0!3m2!1sen!2sin!4v1632480332904!5m2!1sen!2sin', 'A 15-minute walk from Gandhinagar Jaipur railway station, this high-end hotel in a modern building overlooking the Aravalli mountains is 9 km from the iconic pink Hawa Mahal palace.\n\nFeaturing city or hill views, the contemporary rooms and suites offer flat-screens, minibars, and tea and coffeemaking facilities. Upgraded rooms add free Wi-Fi. Suites have living areas. Room service is available.\n\nParking and breakfast are free. There\'s an airy restaurant, a trendy bar and a warm lounge, as well as an outdoor pool, a 24-hour fitness room and a spa.', 'assets/images/hotels/four-points-by-sheraton-jaipur/1.webp', 1),
(141, 'H779', 'grand-hotel-and-suites-jaipur', 'grand hotel and suites jaipur', 'Jaipur', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'The Grand Anukampa, Ajmer Rd, Shyam Nagar, Jaipur, Rajasthan 302019', NULL, 'The Grand Hotels and Suites is a great choice for travellers looking for a 4 star star hotel in Jaipur. This Hotel stands out as one of the highly recommended hotel in Jaipur. Hotel is rated 3.5 out of 5, which is considered as very good.\n\nFrom all the 4 Star hotels in Jaipur, The Grand Hotels and Suites is very much popular among the tourists. A smooth check-in/check-out process, flexible policies and friendly management garner great customer satisfaction for this property. The Hotel has standard Check-In time as 02:00 PM and Check-Out time as 12:00 PM. It is a couple-friendly property, hence it is absolutely safe for unmarried couples to stay here. You can find numerous hotels in Jaipur under different categories and The Grand Hotels and Suites is one the best hotel under its category. Also you can book The Grand Hotels and Suites from our partner website MakeMyTrip.Com.', 'assets/images/hotels/grand-hotel-and-suites-jaipur/1.webp', 1),
(142, 'H362', 'hilton-jaipur', 'Hilton Jaipur', 'Jaipur', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14232.310543025778!2d75.7838055!3d26.9010311!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x6c886175dc6cde79!2sHilton%20Jaipur!5e0!3m2!1sen!2sin!4v1632479475545!5m2!1sen!2sin', 'A 10-minute walk from Bais Godam train station, this modern, upscale hotel is 4 km from the grand Birla Mandir temple and 6 km from the City Palace.\n\nThe casual rooms feature neutral tones, and floor-to-ceiling windows with city or mountain views. All are equipped with Wi-Fi (fee), flat-screen TVs and minibars. Upgraded rooms add private balconies, and some have access to an exclusive lounge providing complimentary breakfast, snacks and drinks. Suites add separate living rooms and sunken tubs.\n\nThe hotel offers 2 restaurants, a trendy bar and a lounge. Other amenities include an outdoor pool, a fitness room, and a spa area with massage services.', 'assets/images/hotels/hilton-jaipur/1.webp', 1),
(143, 'H549', 'hotel-royal-orchid', 'Hotel Royal Orchid', 'Jaipur', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Opposite to BSNL Office Near, Durgapura Flyover, Tonk Rd, Durgapura, Jaipur, Rajasthan 302018', 'https://www.google.com/maps/place/Hotel+Royal+Orchid/@26.844936,75.792987,15z/data=!4m2!3m1!1s0x0:0x33bd1b7b613d87ea?sa=X&ved=2ahUKEwjWtJHUhpX7AhXCR2wGHX9PATcQ_BJ6BAh3EAU', 'Strategically located just 2.5 Kms from Jaipur airport and 10 kms from the city railway station, Hotel Royal Orchid with its elegant furnishing, decor and blend of sophistication, flamboyance with a relaxed attitude make this an ideal stay for all discerning travellers with free WI-FI. The guests can calm their senses at the roof-top swimming pool or indulge in gastronomic delights at \'Tiger Trail\' and at the 24 hour coffee shop \'Limelight and can even lighten their spirit at \'Salsa\'- the signature lounge bar after a day of hectic bustle.This upscale 5 star property houses 139 rooms along with 9 plunge pool rooms which includes a plunge pool suite with the finest amenities and elegant furnishings. Its banqueting facility, with ample parking space , luscious lawns and a large pre- function area makes it an ideal venue not only for video conferences, product launches but also a perfect destination for weddings .Hotel Royal Orchid Jaipur is one such dream wedding destination \' which makes your wedding a charming and unforgettable experience.Traveling to Jaipur and staying at this hotel will surely leave you mesmerized with a memory which will want you coming back for more.', 'assets/images/hotels/hotel-royal-orchid/1.webp', 1),
(144, 'H763', 'hotel-sarang-palace-boutique-stays-and-candlelight-dining', 'Hotel Sarang Palace - Boutique Stays & Candlelight Dining', 'Jaipur', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; heritage-homes; castles', 'A- 40, Subhash Nagar Rd, Near Peetal Factory, Subash Nagar, Shastri Nagar, Jaipur, Rajasthan 302016', '-', '-Set 3 km from Jaipur Junction railway station, this relaxed hotel with an ornate facade is 4 km from both 18th-century City Palace and hilltop Nahargarh Fort.\n\nCasual, colourful rooms offer free Wi-Fi, flat-screens and sitting areas. Upgraded rooms add minifridges, balconies, terraces and/or fort views. Family rooms sleep up to 6 guests. Room service is available 24/7.\n\nA train station shuttle is complimentary. Other amenities include 2 international restaurants and a rooftop cafe. There’s also a lounge and event space. Breakfast is available for a surcharge.', 'assets/images/hotels/hotel-sarang-palace-boutique-stays-and-candlelight-dining/1.webp', 1),
(145, 'H264', 'lemon-tree-premier-jaipur', 'LEMON TREE PREMIER JAIPUR', 'Jaipur', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14227.968793675918!2d75.7917488!3d26.9354618!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xcb6f1d9b790088d9!2sLemon%20Tree%20Premier%2C%20Jaipur!5e0!3m2!1sen!2sin!4v1630232985535!5m2!1sen!2sin', 'The plush and spacious interiors at Lemon Tree Premier, Jaipur take the zing up a notch. The Lemon Tree Premier chain of upscale business and leisure hotels elevates the Lemon Tree experience while retaining the same freshness, quirkiness and energy that Lemon Tree is well known for. Lemon Tree Premier pampers the style conscious and upbeat traveler with its personalized services, premium in-room amenities, award winning restaurants and fun experiences. Full view', 'assets/images/hotels/lemon-tree-premier-jaipur/1.webp', 1),
(146, 'H365', 'park-prime-jaipur', 'Park Prime Jaipur', 'Jaipur', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14231.293595090929!2d75.8027106!3d26.9090993!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xdc55ce90d25be944!2sPark%20Prime!5e0!3m2!1sen!2sin!4v1632480877077!5m2!1sen!2sin', 'A 4-minute walk from Statue Circle, this upscale hotel in a modern building is 6 minutes on foot from the Birla Auditorium and 2 km from the Jamnalal Bajaj Marg train station.\n\nWarm rooms and a suite offer free Wi-Fi, flat-screen TVs, safes and minibars, plus tea and coffeemaking facilities. Room service is available 24/7.\n\nA breakfast buffet is included. Amenities consist of a plush lobby lounge, a buffet restaurant and a wood-panelled bar, as well as both a rooftop pool and an eatery with city views. There\'s a fitness room. Ayurvedic treatments can be arranged.', 'assets/images/hotels/park-prime-jaipur/1.webp', 1),
(147, 'H550', 'radisson-jaipur-city-center', 'Radisson Jaipur City Center', 'Jaipur', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Khasa Kothi Circle, MI Rd, Jaipur, Rajasthan 302001', 'https://www.google.com/maps/place/Radisson+Jaipur+City+Center/@26.9197187,75.7945611,15z/data=!4m2!3m1!1s0x0:0x20e0bf7a01c79cb0?sa=X&ved=2ahUKEwjejsH-h5X7AhWZTGwGHfW4B6gQ_BJ6BQiIARAF', 'Located in the heart of India’s famed Golden Triangle, Radisson Jaipur City Center sits just minutes from the city’s imposing forts and majestic palaces. Thanks to our convenient location within easy reach of railway, metro and bus stations, our hotel’s modern rooms serve as an ideal home base for visiting attractions like Hawa Mahal, City Palace and Amber Fort. Travelling for work? Jaipur International Airport (JAI) is just a 25-minute drive away and major business hubs are less than five kilometres from the hotel. Need to prepare for a meeting. Take advantage of our on-site business center and free Wi-Fi. For a satisfying breakfast or an elaborate gourmet meal, visit one of our hotel’s four on-site restaurants. After meeting with clients or touring Jaipur\'s historic palaces, stop by Revive Gym & Spa to recharge with a jog in the fitness center or a soak in our steam room.', 'assets/images/hotels/radisson-jaipur-city-center/1.webp', 1),
(148, 'H729', 'royal-orchid-cental-jaipur', 'ROYAL ORCHID CENTAL - Jaipur', 'Jaipur', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'No. A-26, A, 2, Sawai Jai Singh Hwy, Kanti Nagar, Bani Park, Jaipur, Rajasthan 302016', NULL, 'ROYAL ORCHID CENTAL is a hotel in Jaipur, India. Its address is No. A-26, A, 2, Sawai Jai Singh Hwy, Kanti Nagar, Bani Park, Jaipur, Rajasthan 302016. Popular places to visit in Jaipur include Hawa Mahal, Amber Fort and City Palace.', 'assets/images/hotels/royal-orchid-cental-jaipur/1.webp', 1),
(149, 'H730', 'the-fern-an-ecotel-hotel-jaipur-jaipur', 'The Fern An Ecotel Hotel, Jaipur - Jaipur', 'Jaipur', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Plot No. 3, Airport Plaza, Tonk Rd, Chandrakala Colony, Mata colony, Jaipur, Rajasthan 302018', NULL, 'Stay at The Fern An Ecotel Hotel, Jaipur in Jaipur, India. The address is Plot No. 3, Airport Plaza, Tonk Rd, Chandrakala Colony, Mata colony, Jaipur, Rajasthan 302018. Popular places to visit in Jaipur include Hawa Mahal, Amber Fort and City Palace.', 'assets/images/hotels/the-fern-an-ecotel-hotel-jaipur-jaipur/1.webp', 1),
(150, 'H758', 'the-florence-resort', 'THE FLORENCE RESORT', 'Jaipur', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', 'Near 31 no bus stand, Niwaru Rd, Jhotwara, Jaipur, Rajasthan 302012', NULL, 'Located in Jaipur, 5.9 miles from Jaipur Train Station, The Florence Resort has accommodations with a seasonal outdoor swimming pool, free private parking, a garden and a restaurant. With free WiFi, this 4-star resort offers room service and a 24-hour front desk. Staff on site can arrange a shuttle service.\n\nComplete with a private bathroom equipped with a bidet and free toiletries, all rooms at the resort have a flat-screen TV and air conditioning, and selected rooms also offer a seating area. All guest rooms feature a safety deposit box.\n\nGuests at The Florence Resort can enjoy a vegetarian breakfast.\n\nCity Palace is 6.1 miles from the accommodation, while Jantar Mantar is 6.1 miles from the property. The nearest airport is Jaipur International Airport, 11 miles from The Florence Resort.', 'assets/images/hotels/the-florence-resort/1.webp', 1),
(151, 'H732', 'chokhi-dhani-the-palace-hotel-jaisalmer-jaisalmer', 'Chokhi Dhani The Palace Hotel Jaisalmer - Jaisalmer', 'Jaisalmer', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels; heritage-homes; castles', 'Barmer Road, NH15, opposite Maheshwari Hospital, Jaisalmer, Rajasthan 345001', NULL, 'Chokhi Dhani The Palace Hotel Jaisalmer is located in Jaisalmer, India. Its address is Barmer Road, NH15, opposite Maheshwari Hospital, Jaisalmer, Rajasthan 345001. Popular places to visit in Jaisalmer include Jaisalmer Fort, Sam Sand Dunes and Patwon Ki Haveli.', 'assets/images/hotels/chokhi-dhani-the-palace-hotel-jaisalmer-jaisalmer/1.webp', 1),
(152, 'H731', 'chowki-dhani-palace-in-desert-camp-jaisalmer', 'CHOWKI DHANI PALACE IN DESERT CAMP - Jaisalmer', 'Jaisalmer', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels; desert-camps; heritage-homes; castles; camp-nights', 'Sam Road Kanoi, near Bunes Parking, Jaisalmer, Rajasthan 345001', NULL, 'Located in Jaisalmer, India, CHOWKI DHANI PALACE IN DESERT CAMP is part of the Galaxy Heritage World network of hotels and resorts. Find it at Sam Road Kanoi, near Bunes Parking, Jaisalmer, Rajasthan 345001. Popular places to visit in Jaisalmer include Jaisalmer Fort, Sam Sand Dunes and Patwon Ki Haveli.', 'assets/images/hotels/chowki-dhani-palace-in-desert-camp-jaisalmer/1.webp', 1),
(153, 'H762', 'highness-desert-camp', 'Highness Desert Camp', 'Jaisalmer', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; desert-camps; camp-nights', 'sam sand dunes, v/p, Kanoi, Rajasthan 345001', '-', 'Stay at Highness Desert Camp, a hotel in Jaisalmer, India. The address is sam sand dunes, v/p, Kanoi, Rajasthan 345001. Popular places to visit in Jaisalmer include Jaisalmer Fort, Sam Sand Dunes and Patwon Ki Haveli.', 'assets/images/hotels/highness-desert-camp/1.webp', 1),
(154, 'H297', 'saira-fort-sarovar-portico-jaisalmer', 'SAIRA FORT SAROVAR PORTICO JAISALMER', 'Jaisalmer', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; castles', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14229.427385562343!2d70.9450152!3d26.9238995!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x728ecf3c0c347396!2sSairafort%20Sarovar%20Portico%2C%20Jaisalmer!5e0!3m2!1sen!2sin!4v1631076804314!5m2!1sen!2sin', 'Jaisalmer, nicknamed as "The Golden city" of Rajasthan is also a world heritage site. The yellow sand and the sandstone used in every architecture gives the city a beautiful golden hue making it the Queen of the Desert. In this Golden city, Sairafort Sarovar Portico is a beautiful haveli styled hotel that offers guests from across the world a traditional Rajputani welcome, warm attentive services and all modern day comforts. Rooms & suites are spacious and resplendent with luxurious amenities. All day dining offers a choice of delectable global & local cuisine. Step out of the hotel and explore the beauty of this desert city in unique ways. From sightseeing the heritage forts, temples and cultural & war museums to viewing performing arts like Kalbelia dances & desert folk music to shopping Camel leather bags and more... Enjoy this magical city best in winter when the electrifying desert festival is held.', 'assets/images/hotels/saira-fort-sarovar-portico-jaisalmer/1.webp', 1),
(155, 'JMK01', 'the-lalit-grand-palace-srinagar', 'The Lalit Grand Palace Srinagar', 'Jammu and Kashmir', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; heritage-homes; castles', 'The Lalit Grand Palace Srinagar, Main Road, Jammu and Kashmir, India', 'https://maps.google.com/?q=The%20Lalit%20Grand%20Palace%20Srinagar%20Jammu%20and%20Kashmir', 'Experience luxury hospitality at The Lalit Grand Palace Srinagar in Jammu and Kashmir, featuring modern amenities and exceptional service.', 'assets/images/hotels/the-lalit-grand-palace-srinagar/1.webp', 1),
(156, 'JMK02', 'vivanta-dal-view', 'Vivanta Dal View', 'Jammu and Kashmir', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Vivanta Dal View, Main Road, Jammu and Kashmir, India', 'https://maps.google.com/?q=Vivanta%20Dal%20View%20Jammu%20and%20Kashmir', 'Experience luxury hospitality at Vivanta Dal View in Jammu and Kashmir, featuring modern amenities and exceptional service.', 'assets/images/hotels/vivanta-dal-view/1.webp', 1),
(157, 'H724', 'acorn-hideaway-resort-and-spa-jim-corbett-jim-corbett', 'Acorn Hideaway Resort & Spa Jim Corbett - Jim Corbett', 'Jim Corbett', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts; wellness-retreats', '❮', NULL, 'Acorn Hideaway Resort & Spa Jim Corbett is located in Jim Corbett, India. Popular places to visit in Jim Corbett include Jim Corbett National Park, Corbett Falls and Garjiya Devi Temple.', 'assets/images/hotels/acorn-hideaway-resort-and-spa-jim-corbett-jim-corbett/1.webp', 1),
(158, 'H772', 'corbett-aroma-park-resort', 'Corbett Aroma Park Resort', 'Jim Corbett', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', 'Village Dhikuli, Ramnagar, Uttarakhand 244715', '-', 'Corbett Aroma Park Resort is located in Jim Corbett, India. Its address is Village Dhikuli, Ramnagar, Uttarakhand 244715. Popular places to visit in Jim Corbett include Jim Corbett National Park, Corbett Falls and Garjiya Devi Temple.', 'assets/images/hotels/corbett-aroma-park-resort/1.webp', 1),
(159, 'H759', 'corbett-nirvana-resort', 'Corbett Nirvana Resort', 'Jim Corbett', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', 'Village -Patkote, Sitavani Road, nearby Baagh Resort, Ram Nagar, Ramnagar, Uttarakhand 263159', '-', 'Located in Jim Corbett, India, Corbett Nirvana Resort is part of the Galaxy Heritage World network of hotels and resorts. Find it at Village -Patkote, Sitavani Road, nearby Baagh Resort, Ram Nagar, Ramnagar, Uttarakhand 263159. Popular places to visit in Jim Corbett include Jim Corbett National Park, Corbett Falls and Garjiya Devi Temple.', 'assets/images/hotels/corbett-nirvana-resort/1.webp', 1),
(160, 'H551', 'corbett-river-creek-luxury-resorts-in-jim-corbett', 'Corbett River Creek - Luxury Resorts In Jim Corbett', 'Jim Corbett', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', 'Plot No 4158, Jim Corbett National Park, NH 121, Village jhadgaon, Tehsil Sult, Dist Almorah, Marchula, Uttarakhand 244715', 'https://www.google.com/maps/place/Corbett+River+Creek+-+Luxury+Resorts+In+Jim+Corbett/@29.6075783,79.095359,15z/data=!4m2!3m1!1s0x0:0x6d625c4a280d95d7?sa=X&ved=2ahUKEwiGir7qiZX7AhWcTWwGHRldAsYQ_BJ6BAh9EAU', 'Corbett river Creek Resort and Spa is located in the northern periphery of Corbett National Park, on the banks of river Ramganga and a small hill creek, surrounded by mountains and thick forest of Sal and Semal trees, the resort is an ideal location for wildlife sighting, bird spotting and angling. Durgadevi safari zone is nearest to The Corbett River Creek resort and spa which is ideal for jungle expeditions and Safari.', 'assets/images/hotels/corbett-river-creek-luxury-resorts-in-jim-corbett/1.webp', 1)
