(176, 'KNP01', 'kanha-earth-lodge', 'Kanha Earth Lodge', 'Kanha National Park', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts; eco-lodges', 'Kanha Earth Lodge, Main Road, Kanha National Park, India', 'https://maps.google.com/?q=Kanha%20Earth%20Lodge%20Kanha%20National%20Park', 'Experience luxury hospitality at Kanha Earth Lodge in Kanha National Park, featuring modern amenities and exceptional service.', 'assets/images/hotels/kanha-earth-lodge/1.webp', 1),
(177, 'KNP02', 'mahua-kothi', 'Mahua Kothi', 'Kanha National Park', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels; heritage-homes', 'Mahua Kothi, Main Road, Kanha National Park, India', 'https://maps.google.com/?q=Mahua%20Kothi%20Kanha%20National%20Park', 'Experience luxury hospitality at Mahua Kothi in Kanha National Park, featuring modern amenities and exceptional service.', 'assets/images/hotels/mahua-kothi/1.webp', 1),
(178, 'KSL02', 'hotel-alasia', 'Hotel Alasia', 'Kasauli', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Hotel Alasia, Main Road, Kasauli, India', 'https://maps.google.com/?q=Hotel%20Alasia%20Kasauli', 'Experience luxury hospitality at Hotel Alasia in Kasauli, featuring modern amenities and exceptional service.', 'assets/images/hotels/hotel-alasia/1.webp', 1),
(179, 'KSL01', 'the-kasauli-resort', 'The Kasauli Resort', 'Kasauli', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', 'The Kasauli Resort, Main Road, Kasauli, India', 'https://maps.google.com/?q=The%20Kasauli%20Resort%20Kasauli', 'Experience luxury hospitality at The Kasauli Resort in Kasauli, featuring modern amenities and exceptional service.', 'assets/images/hotels/the-kasauli-resort/1.webp', 1),
(180, 'H559', 'lemon-tree-hotel-katra', 'Lemon Tree Hotel, Katra', 'Katra', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Railway Rd, Katra, Jammu and Kashmir 182301', 'https://www.google.com/maps/place/Lemon+Tree+Hotel,+Katra/@32.985639,74.9382905,15z/data=!4m2!3m1!1s0x0:0x477cb1b66025cbd6?sa=X&hl=en&ved=2ahUKEwiInKnckZX7AhWLTGwGHd88CoEQ_BJ6BAh3EAU', 'Lemon Tree Hotel, Katra Introduction: Just 5 minutes from the railway station, Lemon Tree Hotel, Katra offers captivating views of the Trikuta Mountains, the celestial abode of the holy shrine of Vaishno Devi. It is also just 3 kms from BaanGanga, the point from where the Climb commences, and in close proximity to the Heli-Ticket Counter, making it a perfect destination for the pilgrims. A vibrant atrium lobby ushers you into 70 stylish and spacious rooms that help you unwind with their fresh and bright interiors, smart in-room amenities, refreshing services and a close to home comfort. Together with an all vegetarian multi-cuisine coffee shop - Citrus Café, a rejuvenating spa by Nirvana and a well equipped conference room, the hotel leaves no stone unturned to pamper and delight its guests.', 'assets/images/hotels/lemon-tree-hotel-katra/1.webp', 1),
(181, 'H720', 'rama-trident-katra', 'RAMA TRIDENT - Katra', 'Katra', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Railway Rd, near AMBIKA CHOWK, Katra, Jammu and Kashmir 182301', NULL, 'RAMA TRIDENT is a hotel in Katra, India. Its address is Railway Rd, near AMBIKA CHOWK, Katra, Jammu and Kashmir 182301. Popular places to visit in Katra include Vaishno Devi Temple, Bhairavnath Temple and Sanjichhat.', 'assets/images/hotels/rama-trident-katra/1.webp', 1),
(182, 'H719', 'the-grand-sharan-katra-h719', 'The Grand Sharan - Katra', 'Katra', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Bus Stand, opp. Small Kalka Mandir, Railway Link Road, near New, Katra, Jammu and Kashmir 182301', NULL, 'Located in Katra, India, The Grand Sharan is part of the Galaxy Heritage World network of hotels and resorts. Find it at Bus Stand, opp. Small Kalka Mandir, Railway Link Road, near New, Katra, Jammu and Kashmir 182301. Popular places to visit in Katra include Vaishno Devi Temple, Bhairavnath Temple and Sanjichhat.', 'assets/images/hotels/the-grand-sharan-katra-h719/1.webp', 1),
(183, 'H560', 'the-grand-sharan-katra', 'The Grand Sharan katra', 'Katra', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'opp Small Kalka Mandir Bus Stand, Railway, Link Road, near New, Katra, Jammu and Kashmir 182301', 'https://www.google.com/maps/place/The+Grand+Sharan+katra/@32.9867425,74.9296858,15z/data=!4m2!3m1!1s0x0:0xb14d3d0900cd878f?sa=X&ved=2ahUKEwjlu9SQkpX7AhVxSmwGHRdBDDQQ_BJ6BAhtEAU', 'Brand new property managed by Jassritha Hotels Pvt Ltd, Gurgaon. It has 42 Spacious rooms in superior/ family/ triple, executive categories and royal, prestige, Mahtab and Imperial Suites. Multi cuisine restaurant, Oval Box offering BEST Indian, Chinese, Gujarati, continental food in town. Health Club facilities. 32" LED TVs, tea/coffee makers, running hot & cold water, laundry services.', 'assets/images/hotels/the-grand-sharan-katra/1.webp', 1),
(184, 'H561', 'welcomhotel-by-itc-hotels-katra', 'Welcomhotel By ITC Hotels, Katra', 'Katra', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', '9, Shrine view SMVD Chowk, Katra, Katra, Jammu and Kashmir 182301', 'https://www.google.com/maps/place/Welcomhotel+By+ITC+Hotels,+Katra/@32.9894346,74.922414,15z/data=!4m2!3m1!1s0x0:0x30b28ffbadc71d44?sa=X&amp;ved=2ahUKEwjuu-SFk5X7AhUDSmwGHSjCCwwQ_BJ6BQiHARAF', 'A warm & welcoming hotel, imbued with the spirit of piety & worship, offering the highest standards of hospitality to the pilgrims of the shrine of Mata Vaishno Devi. The perfect host for pilgrims visiting the holy shrine of Mata Vaishno Devi 83 well-appointed rooms & suites and 2 dining outlets', 'assets/images/hotels/welcomhotel-by-itc-hotels-katra/1.webp', 1),
(185, 'H769', 'nature-valley-resort-kausani', 'Nature Valley Resort, Kausani', 'Kausani', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', 'Baijnath, Tea Garden Road, Kausani, Uttarakhand 263639', '-', 'Stay at Nature Valley Resort, Kausani in Kausani, India. The address is Baijnath, Tea Garden Road, Kausani, Uttarakhand 263639. Popular places to visit in Kausani include Anasakti Ashram, Rudradhari Falls and Caves and Baijnath Temple.', 'assets/images/hotels/nature-valley-resort-kausani/1.webp', 1),
(186, 'H780', 'blanket-hotel-and-spa-luxury-5-star-resorts-in-munnar-h780', 'Blanket Hotel & Spa | Luxury 5 Star Resorts in Munnar', 'Kerala', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts; wellness-retreats', 'Attukad Waterfalls, Aluva - Munnar Rd, Pallivasal, Kerala 685565', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15714.313105148654!2d77.057221!3d10.051616!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3b0799008f4576d9%3A0xe2dd95518617596!2sBlanket%20Hotel%20%26%20Spa%20%7C%20Luxury%205%20Star%20Resorts%20in%20Munnar!5e0!3m2!1sen!2sin!4v1714664836133!5m2!1sen!2sin', 'On a leafy hill station surrounded by tea plantations, this luxurious resort is a 12-minute walk from Attukad Waterfall and 2 km from the NH85.\n\nRelaxed, contemporary rooms in earth tones include flat-screen TVs, Wi-Fi and minibars, as well as tea and coffeemaking facilities. Some add whirlpool baths, dining tables and/or furnished balconies offering hill or waterfall views. Room service is available 24/7.\n\nBreakfast is available. There\'s an international restaurant and a modern open-air bistro. Amenities include an outdoor infinity pool, a fitness centre and a serene spa. There’s also a game room. A doctor is on call.', 'assets/images/hotels/blanket-hotel-and-spa-luxury-5-star-resorts-in-munnar-h780/1.webp', 1),
(187, 'H334', 'hilton-garden-inn-trivandrum', 'Hilton Garden Inn Trivandrum', 'Kerala', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15783.986254798792!2d76.9502923!3d8.4997131!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xe7e90338343b20b1!2sHilton%20Garden%20Inn%20Trivandrum!5e0!3m2!1sen!2sin!4v1631956545805!5m2!1sen!2sin', 'Amid commercial properties, this upscale hotel is 2 km from both Trivandrum Central train station, and art and natural history exhibits at Napier Museum.\n\nRefined, warm rooms offer free Wi-Fi, flat-screen TVs, safes and minibars, as well as tea and coffeemaking facilities. Upgraded rooms add sofabeds, while suites have living rooms. Room service is available, and kids age 18 years and under stay with parents at no extra cost.\n\nParking is free. There\'s a casual restaurant, along with 2 bars. Other amenities include a ballroom, a convenience store, a gym and an outdoor pool. Breakfast is offered for a surcharge.', 'assets/images/hotels/hilton-garden-inn-trivandrum/1.webp', 1),
(188, 'H277', 'hotel-airlink-castle-kochi-kerala', 'HOTEL AIRLINK CASTLE KOCHI KERALA', 'Kerala', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; castles', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15709.257780254304!2d76.3549697!3d10.1550752!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x7c9294b0fd74dcda!2sHotel%20Airlink%20Castle!5e0!3m2!1sen!2sin!4v1630399199101!5m2!1sen!2sin', 'Hotel Airlink Castle is an exquisite Five Star Luxury Hotel, located at the portals of Cochin International Airport, Nedumabassery, Cochin and Kerala, India. Airlink Castle offers you 54 centrally air conditioned rooms with all modern facilities. All the rooms are designed for comfort with beautifully carved woodwork and furniture and a lookout to extensive coconut gardens. The multi-cuisine restaurants, 24 hour coffee shop, business room, health club, the activity center, board rooms, conference halls, rooftop swimming pool with a garden around, a premium bar well stocked with Scotch whiskies, French wines etc. will make your stay enjoyable and rejuvenating whether your stay is for business or leisure.', 'assets/images/hotels/hotel-airlink-castle-kochi-kerala/1.webp', 1),
(189, 'H564', 'hyatt-regency-thrissur', 'Hyatt Regency Thrissur', 'Kerala', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Civil Lines Rd, Puzhakkal, Ayyanthole, Thrissur, Kerala 680003', 'https://www.google.com/maps/place/Hyatt+Regency+Thrissur/@10.5415219,76.1843391,15z/data=!4m2!3m1!1s0x0:0xa0a805da1c22245b?sa=X&ved=2ahUKEwjXu-yplpX7AhUWRmwGHcnzDv0Q_BJ6BQiAARAF', 'Hyatt Regency Thrissur offers a selection of locally inspired experiences with modern rooms, thoughtfully designed meeting and social spaces, and intuitive service. Known as the Cultural Capital of Kerala guests can easily visit the Bible Tower (Puthanpally), Vadakunnathan or Cheraman Jumah Masjid at ease.', 'assets/images/hotels/hyatt-regency-thrissur/1.webp', 1),
(190, 'H266', 'lemon-tree-vembanad-lake-resort-kerala', 'LEMON TREE VEMBANAD LAKE RESORT KERALA', 'Kerala', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15734.894702732903!2d76.3721241!3d9.6190441!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x9fb82099712efcc2!2sLemon%20Tree%20Vembanad%20Lake%20Resort%2C%20Kerala!5e0!3m2!1sen!2sin!4v1630384355277!5m2!1sen!2sin', 'Lemon Tree Vembanad Lake Lemon Tree Vembanad Lake Resort Kerala Cherthala Lemon Tree Vembanad Lake Kerala Cherthala Hotel Lemon Tree Vembanad Lake Resort, Kerala Cherthala Cherthala Lemon Tree Vembanad Lake Resort, Kerala Hotel Lemon Tree Vembanad Lake Resort, Kerala Cherthala Lemon Tree Vembanad Lake Resort Kerala Lemon Tree Vembanad Lake Kerala Hotel Lemon Tree Vembanad Lake Resort, Kerala Lemon Tree Vembanad Lake Resort Lemon Tree Vembanad Kerala Lemon Tree Vembanad Lake Resort Lemon Tree Vembanad Lake Resort, Kerala Hotel Lemon Tree Vembanad Lake Resort, Kerala Cherthala Lemon Tree Vembanad Lake Resort, Kerala Hotel Cherthala Vembanad Lake Resort Lemon Tree Vembanad Lake Resort, Muhamma Hotel Alappuzha Lemon Tree Vembanad Lake Resort, Muhamma Kerala/Alappuzha, India Lemon Tree Vembanad Lake Resort Kerala Lemon Tree Resort Kerala Lemon Tree Vembanad Lake Kerala See less Policies Please note: To comply with local law, no alcohol will be served in this property on the first day of every month. For more details, please contact the property using the information on the reservation confirmation received after booking. Only registered guests are allowed in the guestrooms. Pool access available from 8 AM to 8 PM. Please note that cultural norms and guest policies may differ by country and by property. The policies listed are provided by the property. Reservations are required for massage services and can be made by contacting the property before arrival at the number on the booking confirmation.', 'assets/images/hotels/lemon-tree-vembanad-lake-resort-kerala/1.webp', 1),
(191, 'H260', 'oxygen-resort-alleppey', 'OXYGEN RESORT ALLEPPEY', 'Kerala', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15740.368425011298!2d76.3493677!3d9.5007183!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x11b31b85990f6ea9!2sOxygen%20Resorts%20Alleppey!5e0!3m2!1sen!2sin!4v1630226455699!5m2!1sen!2sin', 'Chemmanur International Holidays and Resorts Private Limited; which is part of the Hospitality & Leisure Division of the Chemmanur International Group along with the grand project namely The Oxygen City, is the Chairman, Dr. Boby Chemmanur’s ambitious foray into the hospitality industry. This resonates in the mission & vision statement which emphasizes on the dire need to revolutionize the vacation ownership industry & emerge as the most trusted brand by following the business principles of ensuring credibility & transparency, simplified product features thereby creating ease of use & a high value proposition for the customer, all of which should eventually lead to the much required pull & a complete departure from the conventional timeshare businesses. Though the business has been well accepted as an excellent option to eliminate the risk of low hotel occupancy coupled with the huge market potential for family holidays..', 'assets/images/hotels/oxygen-resort-alleppey/1.webp', 1),
(192, 'H289', 'poetree-sarovar-portico-thekkady', 'POETREE SAROVAR PORTICO THEKKADY', 'Kerala', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15734.341438690795!2d77.1569331!3d9.6309239!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xb5d150e7c7208538!2sPoetree%20Sarovar%20Portico%2C%20Thekkady!5e0!3m2!1sen!2sin!4v1631005962273!5m2!1sen!2sin', 'Located at a unique vantage point atop a hill & embraced by acres of untouched land & lush forest, Poetree is an eco-resort in Thekkady, India. Wildlife enthusiasts visiting the famous Periyar Wildlife Sanctuary will be pleased to find an experiential eco-resort that promises more than just luxurious accommodation. Poetree Sarovar Portico is situated on a mountain at Ottakathalamedu near Thekkady, with a breathtaking view of the Sahyadri Mountains and the Periyar Lake. The 51 peace-filled rooms and cottages are a perfect balance of luxurious accommodation and rustic ambience, enveloped in verdant foliage and offering panoramic scenic views. The resort also offers ultra-modern business facilities for conferences and corporate offsites. Why Stay With Us? Extremely picturesque hilltop location Eco friendly resort Rooms with breathtaking views', 'assets/images/hotels/poetree-sarovar-portico-thekkady/1.webp', 1),
(193, 'H562', 'vivanta-thiruvananthapuram', 'Vivanta Thiruvananthapuram', 'Kerala', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Extra Police Rd, Nandavanam, Palayam, Thiruvananthapuram, Kerala 695033', 'https://www.google.com/maps/place/Vivanta+Thiruvananthapuram/@8.5046185,76.9533594,15z/data=!4m2!3m1!1s0x0:0xeb8003df7c2be80c?sa=X&ved=2ahUKEwi5_LWplJX7AhX7bGwGHVM-DqkQ_BJ6BAh1EAU', 'Vivanta Thiruvananthapuram is located in the centre of city in close proximity to major government offices and commercial hubs. With just a 20 minutes drive from Trivandrum International Airport, the hotel offers 108 brand new state of the art rooms. There is one speciality restaurant (Kerala Cuisine), an All Day Dining and a Cafe. The hotel is also just 30 minutes drive to IT Hub - Technopark', 'assets/images/hotels/vivanta-thiruvananthapuram/1.webp', 1),
(194, 'KDL02', 'ambience-resort', 'Ambience Resort', 'Khandala', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', 'Ambience Resort, Main Road, Khandala, India', 'https://maps.google.com/?q=Ambience%20Resort%20Khandala', 'Experience luxury hospitality at Ambience Resort in Khandala, featuring modern amenities and exceptional service.', 'assets/images/hotels/ambience-resort/1.webp', 1),
(195, 'KDL01', 'hotel-ruby-regency', 'Hotel Ruby Regency', 'Khandala', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Hotel Ruby Regency, Main Road, Khandala, India', 'https://maps.google.com/?q=Hotel%20Ruby%20Regency%20Khandala', 'Experience luxury hospitality at Hotel Ruby Regency in Khandala, featuring modern amenities and exceptional service.', 'assets/images/hotels/hotel-ruby-regency/1.webp', 1),
(196, 'H573', 'crowne-plaza-kochi', 'Crowne Plaza Kochi', 'Kochi', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Xi/641A Kundanoor Junction NH-47 Bypass PO, Maradu, Kochi, Kerala 682304', 'https://www.google.com/maps/place/Crowne+Plaza+Kochi/@9.9341249,76.3186795,15z/data=!4m2!3m1!1s0x0:0x31d935bec35a2b35?sa=X&ved=2ahUKEwjHmPzWyJf7AhXgSGwGHa3RCh8Q_BJ6BQiIARAF', 'Celebrate business success at the Crowne Plaza Kochi with a touch of leisure and panoramic views of backwaters and exquisite cuisine combined with rejuvenation at our Aira Spa.\n\nCrowne Plaza Kochi is ideally located on the new business district of city NH 47 Bypass and provides easy access to Info Park Kakkanad, Cochin Special Economic Zone, M.G. Road, Cochin Port, Shipyard, Naval Base, major sightseeing areas like Fort Kochi, Mattancherry and is 45 minutes away from Cochin International Airport.\n\nThe hotel offers 269 spacious business rooms and suites with excellent views of the backwaters and the city. Our variety of authentic culinary outlets, extensive spa and leisure facilities, and high-tech meeting spaces that can accommodate up to 900 people, all within a tranquil waterfront setting, makes Crowne Plaza Kochi the preferred international brand for business, leisure and events.\n\nOur Aira Spa is one of the largest hotel spas in Kerala, with a dedicated area of 25,000 sq. ft.', 'assets/images/hotels/crowne-plaza-kochi/1.webp', 1),
(197, 'H566', 'hotel-kodai-international', 'Hotel Kodai International', 'Kodaikanal', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', '17/328, Laws Ghat Rd, Kodaikanal, Tamil Nadu 624101', 'https://www.google.com/maps/place/Hotel+Kodai+International/@10.2427792,77.4984708,15z/data=!4m8!3m7!1s0x0:0xb0c107763305ca15!5m2!4m1!1i2!8m2!3d10.2427792!4d77.4984708', 'Hotel Kodai International offers luxury hotel stay in Kodaikanal, South India like hospitality, orderliness, efficient maintenance and luxury. Hotel Kodai International is sure to offer you a memorable stay at Kodaikanal, South India.', 'assets/images/hotels/hotel-kodai-international/1.webp', 1),
(198, 'H565', 'le-poshe-by-sparsa', 'Le Poshe by Sparsa', 'Kodaikanal', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'No.25, Sivanadi Road, Kodaikanal, Tamil Nadu 624101', 'https://www.google.com/maps/place/Le+Poshe+by+Sparsa/@10.2451383,77.4960863,15z/data=!4m2!3m1!1s0x0:0x25c1250f9ba3f9a7?sa=X&ved=2ahUKEwilmc2FvZb7AhXC4nMBHbF9DhQQ_BJ6BAhkEAU', 'A unique collection of eco-friendly and eco sensitive resorts, developed at spiritual / leisure / adventure destinations. From the luxuriously appointed villas to the captivatingly picturesque ambiance, from the delightfully alluring spas to a revitalizing gym area, from the mesmerizing ethnic charisma to the plush ultramodern facilities, from the finest selection of cuisine to the warm and attentive service, the Sparsa experience is unparalleled.', 'assets/images/hotels/le-poshe-by-sparsa/1.webp', 1),
(199, 'H567', 'sterling-kodai-lake', 'Sterling Kodai Lake', 'Kodaikanal', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'New Kodai Lake, 44, Gymkhana Rd, near Brindavan School, LakeView, Kodaikanal, Tamil Nadu 624101', 'https://www.google.com/maps/place/Sterling+Kodai+Lake/@10.2304726,77.4806,15z/data=!4m2!3m1!1s0x0:0x3bc19f6623abe0b0?sa=X&ved=2ahUKEwjxp7TKwZb7AhWpTmwGHVL8BTIQ_BJ6BAh7EAU', 'Sterling Kodai Lake gives you a first hand opportunity to spend quality time at the star shaped Kodai lake which magnetically attracts tourists from far and wide destinations. The plush rooms, landscaped gardens and everything in between is designed to complement the English style villas that dot the quaint hill station.', 'assets/images/hotels/sterling-kodai-lake/1.webp', 1),
(200, 'H721', 'hotel-kempton-kolkata', 'Hotel Kempton - Kolkata', 'Kolkata', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', '3, Marquis Street, Fire Brigade Head Quarter, Esplanade, Dharmatala, Taltala, Kolkata, West Bengal 700016', NULL, 'Located in Kolkata, India, Hotel Kempton is part of the Galaxy Heritage World network of hotels and resorts. Find it at 3, Marquis Street, Fire Brigade Head Quarter, Esplanade, Dharmatala, Taltala, Kolkata, West Bengal 700016. Popular places to visit in Kolkata include Victoria Memorial, Howrah Bridge and Dakshineswar Kali Temple.', 'assets/images/hotels/hotel-kempton-kolkata/1.webp', 1)
INSERT INTO `hotels` (id, hotel_code, slug, name, location_name, country, location_type, hotel_type, category, stay_types, address, map_link, description, image_path, is_published) VALUES
(201, 'H568', 'novotel-kolkata-hotel-and-residences', 'Novotel Kolkata - Hotel & Residences', 'Kolkata', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Cf 11 Action Area 1C New Town, Rajarhat, Kolkata, West Bengal 700156', 'https://www.google.com/maps/place/Novotel+Kolkata+-+Hotel+%26+Residences/@22.5796615,88.4618306,15z/data=!4m8!3m7!1s0x0:0xb81242f6fef0e357!5m2!4m1!1i2!8m2!3d22.5797016!4d88.4618696', 'Located on the main road connecting Netaji Subhash Chandra Bose International airport and the growing IT and commercial hub of Kolkata. Novotel Kolkata Hotel and Residences has 340 rooms with 12 suits and 48 service apartments. It also has an all day dining restaurant ‘The Square’, Sante the 24x7 bar, Blue Tokai Coffee Roasters, swimming pool, health club, spa. It also has an Executive lounge, WIFI and extensive MICE facilities which includes over 30,000 Sqft Banquet space, 12 meeting rooms, 5 ballrooms, out of which 3 grand ballrooms and the largest open air garden terrace with banqueting facilities for up to 1000 guests.', 'assets/images/hotels/novotel-kolkata-hotel-and-residences/1.webp', 1),
(202, 'H569', 'taj-bengal', 'Taj Bengal', 'Kolkata', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', '34-B, Belvedere Rd, Alipore, Kolkata, West Bengal 700027', 'https://www.google.com/maps/place/Taj+Bengal/@22.5376899,88.3344526,15z/data=!4m8!3m7!1s0x0:0xabaefc78ba555397!5m2!4m1!1i2!8m2!3d22.5376899!4d88.3344526', 'Taj Bengal, designed by the legendary Bob Fox, stands as an elegant Kolkata landmark. It is in close proximity to the commercial centre, Government Offices and Consulates, and must-see sights like the Victoria Memorial, Royal Calcutta Race Course, Horticulture Gardens, National Library and the Zoological Gardens. Iconic host to Heads of State, dignitaries and international business head-honchos, it is geared to the needs of the global business traveller.', 'assets/images/hotels/taj-bengal/1.webp', 1),
(203, 'H570', 'the-lalit-great-eastern-kolkata', 'The LaLiT Great Eastern Kolkata', 'Kolkata', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Dalhousie Square 1, 2,3, Old Court House St, Ward Number 1, Kolkata, West Bengal 700069', 'https://www.google.com/maps/place/The+LaLiT+Great+Eastern+Kolkata/@22.5681542,88.349876,15z/data=!4m8!3m7!1s0x0:0x122a931b2e38319f!5m2!4m1!1i2!8m2!3d22.5681542!4d88.349876', 'Asia\'s first luxury hotel, The Lalit Great Eastern is a heritage landmark located in the main business and shopping district of Kolkata. Restored and renovated over a period of seven years, the hotel holds the distinction of being the longest continuously operating hotel for 165 years. Built in 1841 as Auckland Hotel, it has been referred to as the \'Jewel of the East\' and the \'Best Hotel East of the Suez\'. Over the years, the hotel has been the favourite haunt of royalty and celebrities from across the world. The Lalit Great Eastern, now restored to its original glory, is an amalgamation of the styles of 3 different eras of history - Victorian, Edwardian and Contemporary, reflected in Heritage Block 1, Heritage Block 2 and the New Block respectively. The original Heritage Block radiates the charm of the British Colonial Era, while the Modern Block incorporates a contemporary look and feel. These blocks have been seamlessly connected despite their distinct character and decor.', 'assets/images/hotels/the-lalit-great-eastern-kolkata/1.webp', 1),
(204, 'KSI01', 'hotel-kosi-grand', 'Hotel Kosi Grand', 'Kosi', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Hotel Kosi Grand, Main Road, Kosi, India', 'https://maps.google.com/?q=Hotel%20Kosi%20Grand%20Kosi', 'Experience luxury hospitality at Hotel Kosi Grand in Kosi, featuring modern amenities and exceptional service.', 'assets/images/hotels/hotel-kosi-grand/1.webp', 1),
(205, 'KSI02', 'hotel-radhika-palace', 'Hotel Radhika Palace', 'Kosi', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels; heritage-homes; castles', 'Hotel Radhika Palace, Main Road, Kosi, India', 'https://maps.google.com/?q=Hotel%20Radhika%20Palace%20Kosi', 'Experience luxury hospitality at Hotel Radhika Palace in Kosi, featuring modern amenities and exceptional service.', 'assets/images/hotels/hotel-radhika-palace/1.webp', 1),
(206, 'H789', 'deevana-krabi-resort', 'Deevana Krabi Resort', 'Krabi', 'Thailand', 'INTERNATIONAL', 'RESORT', 'ASSOCIATED', 'resorts', '90 Moo3 Aonang Soi 8, Ao Nang, Mueang Krabi District, Krabi 81180, Thailand', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15802.30891729108!2d98.8183641!3d8.0424469!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3051bff447fa8841%3A0xeb21d6ec6e55e21d!2sDeevana%20Krabi%20Resort!5e0!3m2!1sen!2sin!4v1717386411109!5m2!1sen!2sin', 'On a hill surrounded by tropical greenery, this refined resort is a kilometer from Noppharat Thara Beach and 2 km from Ao Nang Beach. It\'s 26 km from Krabi Airport.\n\nCasual rooms with balconies feature free Wi-Fi and flat-screen TVs, plus minibars, and en suite bathrooms with rainfall showers. Bi-level suites include living rooms, and terraces with pool or garden views.\n\nAmenities include a seafood restaurant and 2 bars, as well as 2 outdoor pools, a hot tub and a garden area.', 'assets/images/hotels/deevana-krabi-resort/1.webp', 1),
(207, 'H788', 'holiday-style-ao-nang-beach-resort-krabi', 'Holiday Style Ao Nang Beach Resort, Krabi', 'Krabi', 'Thailand', 'INTERNATIONAL', 'RESORT', 'ASSOCIATED', 'resorts; beach-houses', '123/3 Moo 3, Ao Nang Beach, Muang Ao Nang, Krabi 81180, Thailand', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15802.348434161731!2d98.8141809!3d8.0414328!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3051bf0b9cf2a261%3A0xa88731f22f8a4ce8!2zSG9saWRheSBTdHlsZSBBbyBOYW5nIEJlYWNoIFJlc29ydCwgS3JhYmkgKOC4ruC4reC4peC4tOC5gOC4lOC4ouC5jCDguYTguKrguJXguKXguYwg4Lit4LmI4Liy4Lin4LiZ4Liy4LiHIOC4muC4teC4iiDguKPguLXguKrguK3guKPguYzguJcg4LiB4Lij4Liw4Lia4Li1KQ!5e0!3m2!1sen!2sin!4v1717386129752!5m2!1sen!2sin', 'Looking for simplicity with a twist, a lively locale and great sleep? Holiday Style Ao Nang Beach Resort, Krabi lets you have it all. Only a minute walk from the Nopparat Thara beach, our resort in Ao Nang is within a 2-minute walk to the night market and fabulous nearby attractions. At the Holiday Style Ao Nang Beach Resort, Krabi we\'ve made sure that you get quality sleep-inducing beds, black-out curtains and the right room temperature, we are the cozy haven you\'re searching for, giving you that perfect night’s sleep you always crave. Maybe you just want to chill at our resort near Ao Nang Beach, so why not swim a few laps or re-fuel at Calm Restaurant with your friends or family. Whether you\'re looking to play, rest or do a bit of both, Holiday Style Ao Nang Beach Resort, Krabi is the right place to have fun. That’s a promise.', 'assets/images/hotels/holiday-style-ao-nang-beach-resort-krabi/1.webp', 1),
(208, 'H786', 'hula-hula-resort-and-spa', 'Hula Hula Resort and Spa', 'Krabi', 'Thailand', 'INTERNATIONAL', 'RESORT', 'ASSOCIATED', 'resorts; wellness-retreats', '222 Khlong Hang Rd, Ao Nang, Mueang Krabi District, Krabi 81180, Thailand', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15802.280343288048!2d98.8200216!3d8.0431801!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x30519461115fc549%3A0xa5a9c4cf0402a9d1!2sHula%20Hula%20Resort%20and%20Spa!5e0!3m2!1sen!2sin!4v1717385395852!5m2!1sen!2sin', 'Hula Hula Resort and Spa is located in Krabi, Thailand. Its address is 222 Khlong Hang Rd, Ao Nang, Mueang Krabi District, Krabi 81180, Thailand. Popular places to visit in Krabi include Railay Beach, Phi Phi Islands and Ao Nang Beach.', 'assets/images/hotels/hula-hula-resort-and-spa/1.webp', 1),
(209, 'H790', 'pakasai-resort', 'Pakasai Resort', 'Krabi', 'Thailand', 'INTERNATIONAL', 'RESORT', 'ASSOCIATED', 'resorts', '88 Moo 3 Aonang Muang Krabi 81000, Thailand', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15802.490184200715!2d98.8194885!3d8.0377941!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3051c00facb4053f%3A0x16ade59b90f449db!2sPakasai%20Resort!5e0!3m2!1sen!2sin!4v1717386553610!5m2!1sen!2sin', 'This upscale beach resort overlooks the Andaman Sea, and is spread among gardens and 2 low-rise wings. Nopparat Thara Beach is 1 km away, and it\'s 2 km from Krabi King Cobra Show.\n\nWith innovative design and Asian/modern decor, the rooms feature flat-screens, sitting areas and balconies. Upgraded units add hot tubs with sea views, while suites offer bedrooms, kitchenettes and terraces. Secluded hillside quarters come with outdoor tubs and rainfall showers.\n\nThere\'s a fitness room, a posh spa, and an infinity pool with a cafe/bar. Other amenities include a free local shuttle, towels, and picnic boxes for beach outings.', 'assets/images/hotels/pakasai-resort/1.webp', 1),
(210, 'H787', 'ramada-by-wyndham-aonang-krabi', 'Ramada by Wyndham Aonang Krabi', 'Krabi', 'Thailand', 'INTERNATIONAL', 'HOTEL', 'ASSOCIATED', 'hotels', '109 Ao Nang, Mueang Krabi District, Krabi 81000, Thailand', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15802.3723772387!2d98.8180058!3d8.0408183!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3051c13213531925%3A0xf7f0b7a0f172980c!2sRamada%20by%20Wyndham%20Aonang%20Krabi!5e0!3m2!1sen!2sin!4v1717385878196!5m2!1sen!2sin', 'Set on leafy grounds, this relaxed hotel is a 13-minute walk from Ao Nang Beach, 1 minute away on foot from Ao Nang Night Market and 26 km from Krabi International Airport.\n\nAiry, simply furnished rooms feature balconies, microwaves and minifridges, as well as flat-screen TVs, Wi-Fi, and tea and coffeemakers. Upgraded rooms add direct pool access or private pools. Room service is offered.\n\nThere\'s a free area shuttle. Other amenities include an outdoor pool, a swim-up bar and an open-air restaurant, plus a gym and a kids\' play area. A breakfast buffet and parking are available.', 'assets/images/hotels/ramada-by-wyndham-aonang-krabi/1.webp', 1),
