(216, 'LSD01', 'hotel-blue-pine', 'Hotel Blue Pine', 'Lansdowne', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Hotel Blue Pine, Main Road, Lansdowne, India', 'https://maps.google.com/?q=Hotel%20Blue%20Pine%20Lansdowne', 'Experience luxury hospitality at Hotel Blue Pine in Lansdowne, featuring modern amenities and exceptional service.', NULL, 1),
(217, 'H509', 'harrah-s-las-vegas', 'Harrah\'s Las Vegas', 'Las Vegas', 'United States', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '3475 S Las Vegas Blvd, Las Vegas, NV 89109', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KVsbkDA8xMiAMbMOPdooYRzh&daddr=Harrah%27s+Las+Vegas,+3475+S+Las+Vegas+Blvd,+Las+Vegas,+NV+89109,+United+States', 'At fun, friendly and action-packed Harrah\'s Las Vegas, you\'re always comfortable and welcome! At its location in the heart of the Las Vegas strip, you\'ll find a host of Las Vegas entertainment that extends throughout and beyond the gaming floor. Our new modern Valley Tower rooms have just what you\'re looking for to stay and play at Harrah\'s Casino Las Vegas! Harrah\'s Las Vegas is home to the hit shows Menopause and for a limited time, The Righteous Brothers! For those looking for a bite to eat, Harrah\'s Las Vegas is home to a variety of Las Vegas restaurants such as the unpretentious down-home cooking and laid back fun found at Toby Keith\'s I Love This Bar & Grill while Ruth Chris Steakhouse sets the scene for an elegant dinner. For seafood lovers, enjoy a meal at the Oyster Bar Las Vegas serving high-quality, fresh seafood including fresh-off-the-dock oysters. Looking for a quick bite, try the Fulton Street Food Hall offering a chef-driven assortment of items.', 'assets/images/hotels/harrah-s-las-vegas/1.webp', 1),
(218, 'H508', 'the-strat-hotel-casino-and-skypod', 'The STRAT Hotel, Casino & SkyPod', 'Las Vegas', 'United States', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '2000 Las Vegas Blvd S, Las Vegas, NV 89104, United States', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KfPtKRGIw8iAMQeI0CUeMZ8b&daddr=The+STRAT+Hotel,+Casino+%26+SkyPod,+2000+Las+Vegas+Blvd+S,+Las+Vegas,+NV+89104,+United+States', 'The STRAT Hotel, Casino & SkyPod is conveniently located between Downtown and Center Strip. It is close to shopping, the Las Vegas Monorail and the Convention Center, with easy access from I-15 and free valet and self-parking. The STRAT guests enjoy discounted access to one of the most iconic landmarks on the Las Vegas Strip, the 1,149-foot STRAT Tower. It is the tallest freestanding observation tower in the U.S.', 'assets/images/hotels/the-strat-hotel-casino-and-skypod/1.webp', 1),
(219, 'LNL02', 'della-resorts', 'Della Resorts', 'Lonavla', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', 'Della Resorts, Main Road, Lonavla, India', 'https://maps.google.com/?q=Della%20Resorts%20Lonavla', 'Experience luxury hospitality at Della Resorts in Lonavla, featuring modern amenities and exceptional service.', NULL, 1),
