(277, 'H718', 'hotel-highland-by-dls-mussoorie', 'HOTEL HIGHLAND BY DLS - Mussoorie', 'Mussoorie', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Hotel Highland, Barlowganj, Christian Village, Mussoorie, Uttarakhand 248122', NULL, 'Located in Mussoorie, India, HOTEL HIGHLAND BY DLS is part of the Galaxy Heritage World network of hotels and resorts. Find it at Hotel Highland, Barlowganj, Christian Village, Mussoorie, Uttarakhand 248122. Popular places to visit in Mussoorie include Kempty Falls, Lal Tibba and Gun Hill.', 'assets/images/hotels/hotel-highland-by-dls-mussoorie/1.webp', 1),
(278, 'H765', 'hotel-kahkashan-by-royal-collection-hotels', 'Hotel Kahkashan By Royal Collection Hotels', 'Mussoorie', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'F357+XR4, Mall Rd, The Mall Road, Mussoorie, Uttarakhand 248179', '-', 'Stay at Hotel Kahkashan By Royal Collection Hotels in Mussoorie, India. The address is F357+XR4, Mall Rd, The Mall Road, Mussoorie, Uttarakhand 248179. Popular places to visit in Mussoorie include Kempty Falls, Lal Tibba and Gun Hill.', 'assets/images/hotels/hotel-kahkashan-by-royal-collection-hotels/1.webp', 1),
(279, 'H347', 'hotel-shilton-mussoorie', 'Hotel Shilton Mussoorie', 'Mussoorie', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13758.334414675952!2d78.0884859!3d30.4479039!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x6570d230b30ac55b!2sHotel%20Shilton%20Mussoorie!5e0!3m2!1sen!2sin!4v1632474716164!5m2!1sen!2sin', 'On a mountainside overlooking the Doon Valley, this casual hotel is 1 km from Picture Palace Bus Station and 5 km from the Lal Tibba scenic point, which has an observation deck with views of the Himalayas.\n\nThe no-nonsense rooms provide Wi-Fi. Upgraded rooms offer air conditioning, flat-screen TVs, and balconies featuring valley views.\n\nAmenities include an informal restaurant, and table tennis and billiards tables. Limited parking is available.', 'assets/images/hotels/hotel-shilton-mussoorie/1.webp', 1),
(280, 'H764', 'hotel-shivalik-hills', 'Hotel Shivalik Hills', 'Mussoorie', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Big Bend Balahisar, opp. Wyne Allen School, near Picture Palace, Mussoorie, Uttarakhand 248179', NULL, 'Hotel Shivalik Hills is located in Mussoorie, India. Its address is Big Bend Balahisar, opp. Wyne Allen School, near Picture Palace, Mussoorie, Uttarakhand 248179. Popular places to visit in Mussoorie include Kempty Falls, Lal Tibba and Gun Hill.', 'assets/images/hotels/hotel-shivalik-hills/1.webp', 1)
