(300, 'PCK02', 'hotel-aster', 'Hotel Aster', 'Panchkula', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Hotel Aster, Main Road, Panchkula, India', 'https://maps.google.com/?q=Hotel%20Aster%20Panchkula', 'Experience luxury hospitality at Hotel Aster in Panchkula, featuring modern amenities and exceptional service.', NULL, 1),
(301, 'PCK01', 'hotel-maple', 'Hotel Maple', 'Panchkula', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Hotel Maple, Main Road, Panchkula, India', 'https://maps.google.com/?q=Hotel%20Maple%20Panchkula', 'Experience luxury hospitality at Hotel Maple in Panchkula, featuring modern amenities and exceptional service.', NULL, 1),
(302, 'H521', 'ibis-paris-tour-eiffel-cambronne-15eme', 'ibis Paris Tour Eiffel Cambronne 15ème', 'Paris', 'France', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '2 Rue Cambronne, 75015 Paris, France', 'https://www.google.com/maps/dir//ibis+Paris+Tour+Eiffel+Cambronne+15%C3%A8me,+2+Rue+Cambronne,+75015+Paris,+France/@48.8470081,2.2313106,12z/data=!4m8!4m7!1m0!1m5!1m1!1s0x47e67022d77fe41f:0x465bb7c0930ff4e6!2m2!1d2.3013502!2d48.8470293?hl=en-GB', 'Our Ibis Paris Eiffel Tower Cambronne 15th hotel is located in the center of Paris, near the Eiffel Tower. You can easily access the hotel by car (hotel parking lot) and by train. At the hotel, you will appreciate modern comfort. We propose a continental buffet breakfast. Our restaurant "La Brasserie Centrale" is a French bistro serving typical and generous dishes. From April to October, you can take advantage of our terrace for a drink or a meal. We hope to see you soon', 'assets/images/hotels/ibis-paris-tour-eiffel-cambronne-15eme/1.webp', 1),
(303, 'H520', 'paris-france-hotel', 'Paris France Hotel', 'Paris', 'France', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '72 R. de Turbigo, 75003 Paris, France', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KYV1i2YPbuZHMQ1cqqGWIHJo&daddr=Paris+France+Hotel,+72+R.+de+Turbigo,+75003+Paris,+France', 'Enjoy welcome serenity and comfort after a day exploring the streets of the capital. Relax in a club armchair in the lobby, on a plush sofa in the lounge, on the terrace or at the traditional pewter bar in the café ... Settle into one of these inviting communal spaces for a drink, to unwind, or to do some work before returning to your room', 'assets/images/hotels/paris-france-hotel/1.webp', 1),
(304, 'H519', 'virgina-hotel-paris', 'Virgina Hotel - Paris', 'Paris', 'France', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '66 Rue du Père Corentin, 75014 Paris, France', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KYUYrlWuceZHMYJHFKQ0i1Ey&daddr=Virgina+Hotel+-+Paris,+66+Rue+du+P%C3%A8re+Corentin,+75014+Paris,+France', 'Close to the famous Parc Montsouris and next to the university campus, the Virgina offers a quiet environment, while allowing direct access to central Paris. Located near the "Parc des Expositions" of Porte de Versailles, where important events are hold throughout the year, Hotel Virgina is ideal for exhibitors or visitors. The 55 comfortable rooms are equipped with private bathroom, safe, minibar and satellite TV. Free Wi-Fi is available throughout the hotel. A private parking is available on request, where you can leave your car safely', 'assets/images/hotels/virgina-hotel-paris/1.webp', 1),
(305, 'PRW02', 'hotel-parwanoo-heights', 'Hotel Parwanoo Heights', 'Parwanoo', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Hotel Parwanoo Heights, Main Road, Parwanoo, India', 'https://maps.google.com/?q=Hotel%20Parwanoo%20Heights%20Parwanoo', 'Experience luxury hospitality at Hotel Parwanoo Heights in Parwanoo, featuring modern amenities and exceptional service.', 'assets/images/hotels/hotel-parwanoo-heights/1.webp', 1),
(306, 'PRW01', 'timber-trail-resort', 'Timber Trail Resort', 'Parwanoo', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', 'Timber Trail Resort, Main Road, Parwanoo, India', 'https://maps.google.com/?q=Timber%20Trail%20Resort%20Parwanoo', 'Experience luxury hospitality at Timber Trail Resort in Parwanoo, featuring modern amenities and exceptional service.', 'assets/images/hotels/timber-trail-resort/1.webp', 1),
(307, 'H524', 'a-one-pattaya-beach-resort', 'A-ONE Pattaya Beach Resort', 'Pattaya', 'Thailand', 'INTERNATIONAL', 'RESORT', 'INTERNAL', 'resorts; beach-houses', 'หมู่ที่ 9 115/9 Beach Rd, Bang Lamung District, Chon Buri 20150, Thailand', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KZkWObsGlgIxMZTSSflGNDGf&daddr=A-ONE+Pattaya+Beach+Resort,+%E0%B8%AB%E0%B8%A1%E0%B8%B9%E0%B9%88%E0%B8%97%E0%B8%B5%E0%B9%88+9+115/9+Beach+Rd,+Bang+Lamung+District,+Chon+Buri+20150,+Thailand', 'If you’re looking for a family-friendly hotel in Pattaya, look no further than A-ONE Pattaya Beach Resort.\n\nClose to some of Pattaya\'s most popular landmarks, such as Beach road (1.1 mi) and Pattaya Floating Market (1.3 mi), A-ONE Pattaya Beach Resort is a great destination for tourists.', 'assets/images/hotels/a-one-pattaya-beach-resort/1.webp', 1),
(308, 'H523', 'beston-pattaya-hotel', 'Beston Pattaya Hotel', 'Pattaya', 'Thailand', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '321/11 Moo 10 Tambol S Pattaya Rd, Bang Lamung District, Chon Buri 20150, Thailand', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=Kec-ukNzlgIxMXrfka5Pw0mm&daddr=Beston+Pattaya+Hotel,+321/11+Moo+10+Tambol+S+Pattaya+Rd,+Bang+Lamung+District,+Chon+Buri+20150,+Thailand', 'Beston Pattaya is 4 Star hotel, located a short walk from the main road known as Pattaya South. It is 1.5 from the Pattaya beach, beach road and the famous nightlife along Walking Street. Using public transport, guests can easily get around the city and visit attractions nearby. Bangkok and Suvarnabhumi International Airport are approximately a 1.5 hour drive away', 'assets/images/hotels/beston-pattaya-hotel/1.webp', 1),
(309, 'H522', 'centara-pattaya-hotel', 'Centara Pattaya Hotel', 'Pattaya', 'Thailand', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '78/140 Moo 9 Nongprue, Bang Lamung District, Chon Buri 20150, Thailand', 'https://www.google.com/maps/dir//Centara+Pattaya+Hotel,+78%2F140+Moo+9+Nongprue,+Bang+Lamung+District,+Chon+Buri+20150,+Thailand/@12.9412036,100.8187085,12z/data=!4m8!4m7!1m0!1m5!1m1!1s0x310296017d947a5d:0x1aa80d52cc9470da!2m2!1d100.888749!2d12.9412129?hl=en-GB', 'Centara Pattaya Hotel is conveniently located in the heart of Central Pattaya, a short walk away from the beach and some serious shopping. You\'ll love relaxing by the hotel\'s swimming pool which has a swim-up bar and a children’s pool. The pool area has plenty of space for lounging whilst making use of the free Wi-Fi. There’s also a fitness centre with a sauna and a steam room, and Thai cooking classes. Each of the 152 rooms and suites features a light and bright décor and large picture windows that highlight views of the city or the pool. Spaciousness is a common feature to all room styles (up to 69 square metres) and there\'s the option of family studios with bunk beds or spacious two-bedroom units. Guests will also enjoy easy access to Spa Cenvaree at sister-hotel Centara Nova Hotel & Spa Pattaya. Golfing, visits to amusements parks and many other activities can all be arranged at the tour desk. Bangkok Suvarnabhumi International Airport is 90 minutes away by road', 'assets/images/hotels/centara-pattaya-hotel/1.webp', 1),
(310, 'H792', 'andaman-cannacia-resort-and-spa', 'Andaman Cannacia Resort & Spa', 'Phuket', 'Thailand', 'INTERNATIONAL', 'RESORT', 'ASSOCIATED', 'resorts; wellness-retreats', '212 Kok Tanod Rd., Kata Beach, T.Karon, A.Muang, Phuket 83100, Thailand', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15811.132113433872!2d98.3008333!3d7.8127778!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3050258d29877e7d%3A0xabfee8b06f4421ea!2sAndaman%20Cannacia%20Resort%20%26%20Spa%20(Sustainable%20Resort)!5e0!3m2!1sen!2sin!4v1717387747008!5m2!1sen!2sin', 'This polished resort overlooking the Andaman Sea is a 6-minute walk from Kata Beach and 10 km from the Wat Chalong Buddhist temple.\n\nOffering balconies, the refined rooms feature satellite TV, minibars, and tea and coffeemakers; some have sea views. Villas and suites add living rooms, whirlpool tubs, outdoor sunken hot tubs, and/or private gardens.\n\nA free beach shuttle is available. There\'s a laid-back restaurant with a terrace; breakfast is offered for a fee. Other amenities include a coffee shop, and a 3-tiered outdoor pool with a poolside bar, plus a hot tub and a spa. There\'s also a gym and a reading room, as well as gardens with cabanas.', 'assets/images/hotels/andaman-cannacia-resort-and-spa/1.webp', 1),
(311, 'H525', 'blu-monkey-hub-and-hotel-phuket', 'Blu Monkey Hub & Hotel Phuket', 'Phuket', 'Thailand', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '3 Soi Pradit, Talad Yai, Mueang Phuket District, Phuket 83000, Thailand', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KZsaQE74MVAwMSEzIw5KO908&daddr=Blu+Monkey+Hub+%26+Hotel+Phuket,+3+Soi+Pradit,+Talad+Yai,+Mueang+Phuket+District,+Phuket+83000,+Thailand', 'Blu Monkey is a Phuket Town bed & breakfast with a difference, offering so much more than a trendy room to rest your head. The striking monotone architecture and cutting-edge design at this Phuket Town hotel incorporates creative workspaces for guests and the urban community to share. The easy going Blu Monkey lifestyle is friendly and fun with games to share and a Blu Pool to chill out under the sun. Enjoy the freedom of our self-service concept, with 24 hour Monkey Desk assistance and an all-night Monkey Hub with super-fast Wi-Fi. There is no hurry, the healthy, homemade breakfast is available all morning followed by a complimentary afternoon selection of Precious Bakery treats. Located on Phangnga Road in the heart of Phuket Town Blu Monkey Phuket Phangnga Road is close to many restaurants, bars and attractions - grab yourself a Monkey Map and bicycle and go explore', 'assets/images/hotels/blu-monkey-hub-and-hotel-phuket/1.webp', 1),
(312, 'H795', 'journeyhub-phuket-patong', 'Journeyhub Phuket Patong', 'Phuket', 'Thailand', 'INTERNATIONAL', 'HOTEL', 'ASSOCIATED', 'hotels', 'Pa Tong, Kathu District, Phuket 83150, Thailand', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15807.746887589352!2d98.3050235!3d7.90168!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x30503aa45f0c41d7%3A0x546ed4dd0db5176f!2sJourneyhub%20Phuket%20Patong!5e0!3m2!1sen!2sin!4v1717388307901!5m2!1sen!2sin', 'Set along the Andaman Sea coast, this laid-back hotel is a 16-minute walk from Banzaan Fresh Market, 2 km from Patong Beach and 39 km from Phuket Airport.\n\nThe warmly furnished rooms feature free Wi-Fi, flat-screen TVs and minifridges, plus tea and coffeemaking facilities. Upgraded rooms add sofas, and suites have living rooms. Room service is available.\n\nParking and area shuttles are free. Breakfast is available (fee). A rooftop restaurant, an outdoor infinity pool and a poolside bar offer city, sea and mountain views. Other amenities include a gym and a terrace.', 'assets/images/hotels/journeyhub-phuket-patong/1.webp', 1),
(313, 'H526', 'novotel-phuket-city-phokeethra', 'Novotel Phuket City Phokeethra', 'Phuket', 'Thailand', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '40/5 Chanacharoen Rd, Tambon Talat Yai, Amphur Muang, Phuket 83000, Thailand', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KYs1yT__MVAwMZAadLhUg2EE&daddr=Novotel+Phuket+City+Phokeethra,+40/5+Chanacharoen+Rd,+Tambon+Talat+Yai,+Amphur+Muang,+Phuket+83000,+Thailand', 'Welcome to Novotel Phuket Phokeethra, your Talat Yai “home away from home.” Novotel Phuket Phokeethra aims to make your visit as relaxing and enjoyable as possible, which is why so many guests continue to come back year after year.\n\nGuest rooms offer amenities such as a minibar and air conditioning, and guests can go online with free wifi offered by the hotel', 'assets/images/hotels/novotel-phuket-city-phokeethra/1.webp', 1),
(314, 'H791', 'pakasai-resort-h791', 'Pakasai Resort', 'Phuket', 'Thailand', 'INTERNATIONAL', 'RESORT', 'ASSOCIATED', 'resorts', '88 Moo 3 Aonang Muang Krabi 81000, Thailand', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15802.490184200715!2d98.8194885!3d8.0377941!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3051c00facb4053f%3A0x16ade59b90f449db!2sPakasai%20Resort!5e0!3m2!1sen!2sin!4v1717387608698!5m2!1sen!2sin', 'This upscale beach resort overlooks the Andaman Sea, and is spread among gardens and 2 low-rise wings. Nopparat Thara Beach is 1 km away, and it\'s 2 km from Krabi King Cobra Show.\n\nWith innovative design and Asian/modern decor, the rooms feature flat-screens, sitting areas and balconies. Upgraded units add hot tubs with sea views, while suites offer bedrooms, kitchenettes and terraces. Secluded hillside quarters come with outdoor tubs and rainfall showers.\n\nThere\'s a fitness room, a posh spa, and an infinity pool with a cafe/bar. Other amenities include a free local shuttle, towels, and picnic boxes for beach outings.', 'assets/images/hotels/pakasai-resort-h791/1.webp', 1),
(315, 'H793', 'patong-resort', 'Patong Resort', 'Phuket', 'Thailand', 'INTERNATIONAL', 'RESORT', 'ASSOCIATED', 'resorts', '208 Raj-Uthit 200 Pee Rd., Patong Beach, Kathu, Phuket 83150, Thailand', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15808.127629344168!2d98.2963256!3d7.8917307!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x30503aba5f930a81%3A0xf6089eef194f5e09!2sPatong%20Resort!5e0!3m2!1sen!2sin!4v1717388031584!5m2!1sen!2sin', 'A 10-minute walk from the beach, this colorful, contemporary hotel is also 8 km from Tiger Kingdom Phuket zoo and 18 km from Wat Chalong temple.\n\nSleek rooms with warm teak furnishings feature free Wi-Fi, TVs, minibars, and tea and coffeemakers. Most have balconies, and suites add living areas.\n\nParking is free. Breakfast is extra. There\'s an Italian restaurant, a Japanese sushi bar and a cafe, as well as a casual bar/lounge. Other amenities include 2 outdoor pools, a hot tub and a gym, plus massage services, an Internet cafe and 5 meeting rooms.', 'assets/images/hotels/patong-resort/1.webp', 1),
(316, 'H794', 'the-nature-phuket', 'The Nature Phuket', 'Phuket', 'Thailand', 'INTERNATIONAL', 'HOTEL', 'ASSOCIATED', 'hotels', '322 Kammala - Patong Rd, Pa Tong, Kathu District, Phuket 83150, Thailand', '322 Kammala - Patong Rd, Pa Tong, Kathu District, Phuket 83150, Thailand', 'Across the street from a beach along Kalim Bay, this upscale resort is 1 km from lively Patong Beach and 32 km from Phuket International Airport.\n\nChic rooms have smart TVs, minibars and balconies. Upgraded rooms offer bay views; some provide hot tubs. Suites include sitting areas. Upgraded suites add direct pool access, and some have 2 bedrooms. Wi-Fi is available.\n\nParking and area shuttle service are complimentary. Other amenities consist of 3 restaurants, 1 with a rooftop lounge, plus a spa, a fitness center and an outdoor pool. There\'s also a kids\' club. Breakfast is offered for a fee.', 'assets/images/hotels/the-nature-phuket/1.webp', 1),
(317, 'H613', 'hotel-le-royal-park', 'HOTEL LE ROYAL PARK', 'Pondicherry', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', '168, Kamaraj Salai, Saram, Puducherry, 605013', 'https://www.google.com/maps/place/HOTEL+LE+ROYAL+PARK/@11.939188,79.8166892,15z/data=!4m2!3m1!1s0x0:0xa072c2f9f5d76cf7?sa=X&ved=2ahUKEwi0_d_y17D7AhXmB7cAHasiAZQQ_BJ6BAh7EAc', 'One of the elite hotel in pondicherry which is representing the french architecture and remembrance of anglo- french era. Ideally located in the mid of the city.the hotel has very easy access to all major tourist attractions within one kilometer.we have choice of 4 restaurants and 3 variety of halls to cater all sort of pepole and occasions.For fitness freak we have spa center and gym. we have 2 swimming pool for both adults and kids.24hrs coffee shop to serve round the clock food and bevarage.', 'assets/images/hotels/hotel-le-royal-park/1.webp', 1),
(318, 'H614', 'la-villa', 'La Villa', 'Pondicherry', 'India', 'DOMESTIC', 'VILLA', 'ASSOCIATED', 'villas', '11, Surcouf St, White Town, Puducherry, 605001', 'https://www.google.com/maps/place/La+Villa/@11.9300666,79.8325985,15z/data=!4m8!3m7!1s0x0:0x1ced2a90471dc4b6!5m2!4m1!1i2!8m2!3d11.9300889!4d79.8326027', 'Luxury and Sobriety in PondicherryLA VILLA is located in the heart of the old quarter of Pondicherry called ‘the white town’, at walking distance from the main attractions.Respecting the heritage of its colonial architecture, inspired by its Pondicherien past, the original walls of the ground floor converse with the immaculate white walls, teak wood, and glass and metal of the new extension. A second birth has been given to ancient materials and techniques like centuries-year-old bricks, lime plaster, colour cement flooring, and hand made tiles from the villages of Tamil Nadu as well as local granite. Old wood from levelled houses has been reused to create elegant contemporary furniture and local handicrafts are combined with the most luxurious and sophisticated western design. Avoiding the false interpretation of the city’s heritage and the mistakes of the modern developed world, the local environment has been treated as an ally, not as an enemy.', 'assets/images/hotels/la-villa/1.webp', 1),
(319, 'H612', 'the-residency-towers-puducherry', 'The Residency Towers Puducherry', 'Pondicherry', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'No.388, Anna Salai, Subbarayapillai Chathiram, Puducherry, 605001', 'https://www.google.com/maps/place/The+Residency+Towers+Puducherry/@11.9339244,79.8245326,15z/data=!4m2!3m1!1s0x0:0x4284c23a7a25d526?sa=X&ved=2ahUKEwj-k5L31rD7AhXzSHwKHRrVAWsQ_BJ6BAh2EAc', 'Situated in a strategic location, amid French-styled buildings and a calming ambience, resides one of the best 5-star hotels in Puducherry - The Residency Towers. It offers generously spacious and classy rooms for both corporate and leisure guests. The hotel is in close proximity to White Town, a popular landmark of the city. White Town is celebrated for its quirky cafes, restaurants and beaches that allures travellers.\n\nThe perfect fusion of comfort and sophistication, our hotel near White Town delivers top-notch services and amenities. There are a total of 75 fully-automated rooms accompanied by 3 lavish restaurants, a wellness spa, a swimming pool and innumerable other facilities. It is the haven you seek during your trip to this lovely French colonial settlement in India!', 'assets/images/hotels/the-residency-towers-puducherry/1.webp', 1),
(320, 'H617', 'four-points-by-sheraton-hotel-and-serviced-apartments-pune', 'Four Points by Sheraton Hotel & Serviced Apartments, Pune', 'Pune', 'India', 'DOMESTIC', 'APARTMENT', 'ASSOCIATED', 'apartments', '5th Mile Stone, Viman Nagar, Pune, Maharashtra 411014', 'https://www.google.com/maps/place/Four+Points+by+Sheraton+Hotel+%26+Serviced+Apartments,+Pune/@18.5629642,73.9222622,15z/data=!4m2!3m1!1s0x0:0x535235fae8ff371?sa=X&ved=2ahUKEwiqpKG23bD7AhXr13MBHWtuBmcQ_BJ6BQiAARAH', 'You\'re eligible for a Genius discount at Four Points by Sheraton Hotel and Serviced Apartments Pune! To save at this property, all you have to do is sign in.\n\nCommitment to Clean, as we welcome you back guests to our hotels around the world, we are committed to providing you with a safe environment that aligns with expert protocols for working to defeat COVID-19.\n\nFour Points By Sheraton Pune located in Viman Nagar, 3.9 Km Pune Airport, Phoenix Market City is 650 m & 4.9 km from Business Hubs like World Trade Center, EON IT Park, etc, the hotel is ideally located for Business Travelers.\n\nOur 5-star hotel has Well-Appointed 217 Rooms, Service Apartments (550-750 sq. ft) featuring Four Comfort™ Beds, Flat-screen TVs, and High-Speed Free Wi-Fi. Trendy F&B; 1st Story cum Co-Work Bar & Kitchen, All Day International dining at Eatery & Al-Fresco, 24X7 In-Room Dining with 15500 Sq. ft of banquets and meeting space. Spa, Well Equipped Fitness Center & Great Outdoor Swimming Pool to Relax & Un-Wind. Our Lobby Lounge at the Lobby Level offers an ideal networking and meeting zone for business travelers.', 'assets/images/hotels/four-points-by-sheraton-hotel-and-serviced-apartments-pune/1.webp', 1)
INSERT INTO `hotels` (id, hotel_code, slug, name, location_name, country, location_type, hotel_type, category, stay_types, address, map_link, description, image_path, is_published) VALUES
(321, 'H615', 'hyatt-pune', 'Hyatt Pune', 'Pune', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Adjacent To Aga Khan Palace, 88, Nagar Rd, Kalyani Nagar, Pune, Maharashtra 411006', 'https://www.google.com/maps/place/Hyatt+Pune/@18.554211,73.904698,15z/data=!4m2!3m1!1s0x0:0x3cfb9881ad224c0?sa=X&ved=2ahUKEwifiZLZ2rD7AhXOILcAHVSXDNQQ_BJ6BQiIARAH', 'Hyatt Pune is an upscale lifestyle hotel for the urban traveler looking for distinctive indulgences. The hotel offers unique inviting experiences benefiting from its modern downtown location just 10 mins from Pune Airport, 5 mins from Phoenix Market City and 15 mins away from business and IT hubs. Revel in our effortless personalized services ideal for solo, family, and romantic getaways in our rooms with large bay windows, tea-coffee setup, pet-friendly floors, iPod dock, 24-hour in-room dining services & minibar. Embark on a wellness journey with a scenic outdoor poolside & city’s only Garden suites. Get rejuvenated as you visit Hyatt Pune Spa for western or Ayurveda treatments, Reiki, or Yoga. The hotel has 3 restaurants serving authentic & aromatic regional & global cuisines enjoyed in the picturesque indoor & outdoor venues. Baan Tao, award winning Pan-Asian restaurant is surreal with unique marvels of a mystical waterfall & Open to sky Thaisala. The alfresco of Eighty Eight and Fishbowl restaurant that allows you to enjoy the curated culinary offerings. Located adjacent to Aga Khan Palace, guests can utilize the hotel’s car rental facilities to explore the city of Pune.', 'assets/images/hotels/hyatt-pune/1.webp', 1),
(322, 'H616', 'radisson-blu-hotel-pune-kharadi', 'Radisson Blu Hotel Pune Kharadi', 'Pune', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Nagar Bypass, Road, Kharadi, Pune, Maharashtra 411014', 'https://www.google.com/maps/place/Radisson+Blu+Hotel+Pune+Kharadi/@18.5533931,73.9379346,15z/data=!4m2!3m1!1s0x0:0x5984b80264a16012?sa=X&ved=2ahUKEwilkayc3LD7AhU8ILcAHdrYBawQ_BJ6BQiHARAH', 'Award-winning business hotel in Pune. Welcome to the Radisson Blu Hotel Pune Kharadi, where guests experience world-class personalized service with modern accommodations and close proximity to the business zones of EON IT Park,World Trade Centre, Magarpatta and Ranjangaon MIDC. Situated just five kilometers from Pune International Airport (PNQ), our sleek, stylish hotel offers all the comforts of home in 141 spacious, well-equipped guest rooms, including free high-speed, wireless Internet and flat-screen televisions. Make your mornings more prolific by enjoying a workout in the fitness center or a swim in the sparkling rooftop swimming pool. The hotel provides the latest security systems, CCTV cameras and a baggage scanner with 24 Hrs manned security. Enjoy our inspiring culinary experiences beginning with a multi-cuisine treat at Carmine, Mexican, Italian & Indian dishes at The Bridge-Connecting Cuisines with Live western music by our lady singer, tempting kababs at The Great Kabab Factory along with Live Ghazals on weekends and delicious baked goodies at Citrine. In addition to 1,400 square meters of meeting space and a state-of-the-art business center, the Radisson Blu Pune also offers a rejuvenating on-site Spa. Commuting in and out of the city is easier as it\'s conveniently located just five kilometers from Pune International Airport (PNQ). Exacting standards and a commitment to excellence drive the friendly, professional staff at the Radisson Blu Hotel Pune, where guests discover personalized attention and welcoming amenities like Free high-speed wireless, Internet, doctor on call, fitness centre, a spa, on-site dining, a swimming pool, laundry, valet parking, a modern business center and Express Check-Out are just a few of the amenities that make guests feel welcome The manager and reception staff is available 24 hours a day to ensure your visit is memorable for all the right reasons. Events both large and small shine in the event space at the Radisson Blu Hotel Pune Kharadi, featuring 1,400 square meters of flexible space for up to 600 guests. Choose the two banquet and convention halls for corporate conferences and gala wedding receptions, or select from three meeting rooms and a rooftop function area for more intimate gatherings.For weddings, Radisson Blu Hotel Pune Kharadi helps ensure that your special day is both stress free and one of a kind by assisting with every detail of the planning process as we help you make your dreams come to life. Select from a range of elegant options including cocktail receptions, sit-down dinners and stand-up buffets as guests dine on a delicious menu specially crafted from your selections. Whether you\'re hosting an intimate reception for 20 or a grand banquet for 600, the team at the Radisson Blu Pune stands ready to make your day one to remember. Refresh and rejuvenate at our spa in Pune, make your way to experience tranquility and personalized attention at Spa Blu, sleek and sophisticated on-site spa. Opt for a range of health treatments suited to meet your needs, including facial and body treatments that focus on repairing cell damage and rebalancing skin to its natural, youthful glow. Designed to promote deep relaxation, soothe the senses and calm the mind through massages like deep tissue, reflexology, relaxation/Swedish and remedial options. As part of our spa in Pune, guests enjoy a health club with a meditation room, a steam room and a gym. Salon services for both men and women are available, as are detoxifying wraps, body exfoliation, manicure and pedicure enjoying a workout in the fitness center or a swim in the sparkling rooftop swimming pool. Services near the hotel: Pune International Airport (5 km) Pune Railway Station (10 km) Directions from Pune International Airport Exit airport and drive towards the Nagar Road for 500 meters through New Viman Nagar Road. Take a left-turn towards Ahmednagar Maharashtra State Highway 27 and drive to Kharadi Magarpatta Bypass. Turn Right on Kharadi Bypass and take a Drive straight for about 550 Meters Radisson Blu Hotel Pune is the left.', 'assets/images/hotels/radisson-blu-hotel-pune-kharadi/1.webp', 1),
(323, 'H620', 'hotel-golden-palace-puri', 'Hotel Golden Palace Puri', 'Puri', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; heritage-homes; castles', 'On Blue Flag Golden Beach of VIP Road, near, Subash Chandra Bose Square, Puri, Odisha 752001', 'https://www.google.com/maps/place/Hotel+Golden+Palace+Puri/@19.7974131,85.831355,15z/data=!4m2!3m1!1s0x0:0xc218821c53e4e2a9?sa=X&ved=2ahUKEwj2nduo4LD7AhWCT3wKHZi6CQgQ_BJ6BAhvEAc', 'Sprawling over 2.5 acres with lush green landscaping, and being a Luxurious Accommodation hotel in Puri Golden Palace nestles amidst a natural lagoon, in a private beach with elegantly designed 94 Rooms & Suites to welcome you. Enjoy the legendary elegance and breath-taking beauty of the beaches of Puri and also enjoy business at our Conference Hotel in Puri LOCATION Golden Palace the leisure and Conference Hotel in Puri is 60kms away from BijuPattnaik International Airport in Bhubaneswar (the capital of Orissa) and 1kms away from the Puri Railway Station. The famous and revered Lord Jagannath Temple is just 3kms away, providing you with a luxurious accommodation hotel in puri', 'assets/images/hotels/hotel-golden-palace-puri/1.webp', 1),
(324, 'H700', 'hotel-holiday-resort-puri', 'Hotel Holiday Resort - Puri', 'Puri', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', '❮', NULL, 'Hotel Holiday Resort is located in Puri, India. Popular places to visit in Puri include Jagannath Temple, Puri Beach and Konark Sun Temple.', 'assets/images/hotels/hotel-holiday-resort-puri/1.webp', 1),
(325, 'H619', 'nrs-royal-palace', 'NRS Royal Palace', 'Puri', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; heritage-homes; castles', 'Shankar Rd, Baliapanda Housing Board Colony, Puri, Odisha 752001', 'https://www.google.com/maps/place/NRS+Royal+Palace/@19.7867652,85.7981874,15z/data=!4m2!3m1!1s0x0:0x9567c7c37a86971f?sa=X&ved=2ahUKEwiHzsm637D7AhXxHrcAHUMiDBkQ_BJ6BAh1EAc', 'NRS Royal Palace has emerged as a distinct name as a Sea Facing Hotel in Puri. Since, it`s started on April 2014; it`s adding the goodwill and creating rapport in the sector. Our aim and motto is very clear and transparent that is to excel in this Hotel Industry and as well to become a leader creating our own brand value and becoming one of the best hotels in puri.', 'assets/images/hotels/nrs-royal-palace/1.webp', 1),
(326, 'H618', 'sterling-puri', 'Sterling Puri', 'Puri', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', '255/2 and 255/3, Sipasarubali Village, Baliapanda, Puri, Odisha 752001', 'https://www.google.com/maps/place/Sterling+Puri/@19.7827668,85.7819481,15z/data=!4m2!3m1!1s0x0:0xc3ddb1f8d6913619?sa=X&ved=2ahUKEwjny4bV3rD7AhVy5nMBHQJ9DUYQ_BJ6BQiBARAH', 'Sterling Puri is in an estuary where the river meets the sea & is set in a sprawling 15 acres. Catch the sunrise on the beach or indulge in the spa, swimming pool, or games & activities. Enjoy authentic Odia delicacies in the multi-cuisine restaurant.\n\nWith the beach just a stone’s throw away, Sterling Puri is easily the best choice in this city. If you are a morning person, then don’t miss the sunrise on the sea. The renowned Puri Jagannath Temple is not far away from the resort.\n\nPuri is known for its art form called Pattachitra, an intricate painting done on silk and cotton fabric. Fringed by the shimmering blue sea and soft golden sand, this colourful temple town looks like a large Pattachitra.\n\nSterling Puri has 121 well-appointed rooms, and the beach is just a quick walk away from the resort. The lullaby of the waves will soothe your senses. Spend the day visiting the holy temple, and going on a trail to watch artists working on Pattachitra. You can take a short excursion to the renowned Konark Sun temple and Chilika lake. Don\'t forget to catch the sand art at the resort. For the adventurer in you, The resort\'s Holiday Activity Centre offers a variety of experiences like aqua zorbing, paddle boats and so on.', 'assets/images/hotels/sterling-puri/1.webp', 1),
(327, 'H271', 'aaram-baagh-pushkar', 'AARAM BAAGH PUSHKAR', 'Pushkar', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d14286.767977838175!2d74.5211215!3d26.4656555!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x5c08609b6c780fae!2sAaram%20Baagh%20by%20Pachar%20Group%2C%20Pushkar!5e0!3m2!1sen!2sin!4v1630390614531!5m2!1sen!2sin', 'Aaram Baagh Pushkar is located in the foothills of Aravali, near the Goddess Savitri Temple and 5 km from the bus stand. It offers Ayurvedic massage services, a restaurant and free parking on site. Air-conditioned guest rooms are fitted with a minibar, tea/coffee making facilities and a telephone set. The en suite bathroom comes with toiletries and shower. The hotel has an outdoor pool and a games room. Guests can also play outdoor sports such as volleyball and badminton. The staff at the tour desk can assist with making travel arrangements. Sauryavanshi restaurant serves a selection of regional cuisine. Both vegetarian and non-vegetarian options are available. Pushkar Aaram Baagh is 20 km from Ajmer Railway Station. Jaipur Airport is 150 km away. We speak your language!', 'assets/images/hotels/aaram-baagh-pushkar/1.webp', 1),
(328, 'H622', 'ananta-spa-and-resort-pushkar', 'Ananta Spa & Resort Pushkar', 'Pushkar', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts; wellness-retreats', 'Village-Leela Sevri, Ajmer, Pushkar Rd, Pushkar, Rajasthan 305022', 'https://www.google.com/maps/place/Ananta+Spa+%26+Resort+Pushkar/@26.4965379,74.5835585,15z/data=!4m2!3m1!1s0x0:0x6910cd2ebecb76df?sa=X&ved=2ahUKEwjHlrScnrP7AhUTg-YKHSf4Bz8Q_BJ6BQiCARAH', 'Set against the breath-taking backdrop of the Aravalli Hills, Ananta Spa & Resort Pushkar creates a fairy-tale like experience by offering the best of five-star luxuries. From blossoming verdure to 52 contemporary cottages,24 sprawling rooms,15 tents and a Ananta Villa coupled with service excellence, the picturesque facade aesthetically captures the beauty of your sojourn. Spread across 9-acres of lush greenery, this luxury resort features: • Two eclectic dining outlets • State-of-the-art banquet facilities • A well-equipped recreational room • Special kids\' activity area • Outdoor pool • A Superlative spa and fitness centre Ananta Spa & Resort Pushkar crafts a unique escape for leisure stays, destination weddings and corporate off-sites in the sacred city.', 'assets/images/hotels/ananta-spa-and-resort-pushkar/1.webp', 1),
(329, 'H702', 'dera-masuda-a-luxury-resort-in-pushkar-pushkar', 'Dera Masuda | A Luxury Resort in Pushkar - Pushkar', 'Pushkar', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', 'Motisar Rd, Pushkar, Rajasthan 305022', NULL, 'Stay at A Luxury Resort in Pushkar in Pushkar, India. The address is Motisar Rd, Pushkar, Rajasthan 305022. Popular places to visit in Pushkar include Pushkar Lake, Brahma Temple and Savitri Temple.', 'assets/images/hotels/dera-masuda-a-luxury-resort-in-pushkar-pushkar/1.webp', 1),
(330, 'H623', 'lalit-international-a-boutique-hotel', 'Lalit International - A Boutique Hotel', 'Pushkar', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Motisar Rd, Ganahera, Pushkar, Rajasthan 305022', 'https://www.google.com/maps/place/Lalit+International+-+A+Boutique+Hotel/@26.4902145,74.5275675,15z/data=!4m2!3m1!1s0x0:0xf3d6e3fccb925d8?sa=X&ved=2ahUKEwiow-f0nrP7AhVM93MBHQFcCAoQ_BJ6BAhxEAc', 'You\'re eligible for a Genius discount at Lalit International - A Boutique Hotel! To save at this property, all you have to do is sign in.\n\nSet in Pushkar, 1.2 km from Pushkar Fort, Lalit International - A Boutique Hotel features a terrace and views of the mountain. Among the facilities of this property are a restaurant, a 24-hour front desk and room service, along with free WiFi. The property offers car hire and features a garden and year-round outdoor pool.\n\nAll guest rooms come with air conditioning, a flat-screen TV with satellite channels, a kettle, a shower, free toiletries and a desk. All units at the hotel are equipped with a private bathroom and bed linen.\n\nGuests at Lalit International - A Boutique Hotel can enjoy a buffet or a à la carte breakfast.\n\nBrahma Temple is 3.3 km from the accommodation, while Varaha Temple is 3.5 km from the property. The nearest airport is Kishangarh Airport, 41 km from Lalit International - A Boutique Hotel.', 'assets/images/hotels/lalit-international-a-boutique-hotel/1.webp', 1),
(331, 'H701', 'lohana-village-resort-pushkar', 'Lohana Village Resort - Pushkar', 'Pushkar', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', 'Village:, Chawandiya, Ganahera, Pushkar, Rajasthan 305022', NULL, 'Stay at Lohana Village Resort in Pushkar, India. The address is Village:, Chawandiya, Ganahera, Pushkar, Rajasthan 305022. Popular places to visit in Pushkar include Pushkar Lake, Brahma Temple and Savitri Temple.', 'assets/images/hotels/lohana-village-resort-pushkar/1.webp', 1),
(332, 'H621', 'the-westin-pushkar-resort-and-spa', 'The Westin Pushkar Resort & Spa', 'Pushkar', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts; wellness-retreats', 'Khasra No. 1242 1243, 1196/1726, Village Surajkund, Motisar Rd, Pushkar, Rajasthan 305022', 'https://www.google.com/maps/place/The+Westin+Pushkar+Resort+%26+Spa/@26.4547497,74.5046009,15z/data=!4m2!3m1!1s0x0:0x1c9af3aaeeb9fbfa?sa=X&ved=2ahUKEwie3-qlnbP7AhVv7XMBHdOWDKwQ_BJ6BQiCARAH', 'Surrounded by the picturesque Aravalis, The Westin Pushkar Resort & Spa is an immaculate wellness and leisure gateway that offers everything from serene natural elements and beautiful sunsets to rejuvenating therapies and food for the soul. Ideally located in Pushkar, India to experience the cultural and historical offers of a vibrant city, the resort is 20 kms away from Ajmer, 158 kms from the Jaipur International Airport, 53 kms from the Kishangarh Airport and is also connected by rail to Ajmer Junction. Each of our 98 spacious guest rooms and villas which offer a panoramic view of the surrounding Aravali Hills and feature luxury amenities like high speed internet access and flat screen televisions, have been thoughtfully designed to leave you feeling cared for by providing revitalizing comfort. Set near the Sadar Bazaar and more, The Westin Pushkar Resort & Spa is an immaculate wellness and leisure gateway that offers everything from serene natural elements and beautiful suns', 'assets/images/hotels/the-westin-pushkar-resort-and-spa/1.webp', 1),
(333, 'H626', 'clarks-safari-ranthambore', 'Clarks Safari Ranthambore', 'Ranthambore', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Charoda Road Khasra No. 65-66, Gram- khawa Tehsil & Dist, Charoda Rd, Ranthambore, Rajasthan 322029', 'https://www.google.com/maps/place/Clarks+Safari+Ranthambore/@26.0874976,76.4340898,15z/data=!4m2!3m1!1s0x0:0x4a10aee493c83e2b?sa=X&ved=2ahUKEwj155OfobP7AhVmlNgFHSltALYQ_BJ6BQiIARAH', 'Stay at Clarks Safari Ranthambore, a hotel in Ranthambore, India. The address is Charoda Road Khasra No. 65-66, Gram- khawa Tehsil & Dist, Charoda Rd, Ranthambore, Rajasthan 322029. Popular places to visit in Ranthambore include Ranthambore National Park, Ranthambore Fort and Trinetra Ganesh Temple.', 'assets/images/hotels/clarks-safari-ranthambore/1.webp', 1),
(334, 'H699', 'ranthambore-national-resort-ranthambore', 'RANTHAMBORE NATIONAL RESORT - Ranthambore', 'Ranthambore', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', 'Ranthambhore Rd, opposite Saras Dairy, Saptar, Sawai Madhopur, Rajasthan 322001', NULL, 'RANTHAMBORE NATIONAL RESORT is located in Ranthambore, India. Its address is Ranthambhore Rd, opposite Saras Dairy, Saptar, Sawai Madhopur, Rajasthan 322001. Popular places to visit in Ranthambore include Ranthambore National Park, Ranthambore Fort and Trinetra Ganesh Temple.', 'assets/images/hotels/ranthambore-national-resort-ranthambore/1.webp', 1),
(335, 'H625', 'the-baagh-ananta-elite-ranthambore', 'The Baagh Ananta Elite, Ranthambore', 'Ranthambore', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Ranthambhor Road village Sherpur, Khilchipur, Rajasthan 322001', 'https://www.google.com/maps/place/The+Baagh+Ananta+Elite,+Ranthambore/@26.0629135,76.4280729,15z/data=!4m2!3m1!1s0x0:0xecfa442e857a3681?sa=X&ved=2ahUKEwju44a_oLP7AhUbxnMBHQR2AVMQ_BJ6BQiCARAH', 'The Baagh Ananta Elite is a luxurious property at the threshold of the National Park in Ranthambore. This resort is known for its impeccable services and world-class hospitality giving you all modern facilities in Ranthambore.', 'assets/images/hotels/the-baagh-ananta-elite-ranthambore/1.webp', 1),
(336, 'H628', 'anand-kashi-by-the-ganges-rishikesh-ihcl-seleqtions', 'Anand Kashi by the Ganges, Rishikesh – IHCL SeleQtions', 'Rishikesh', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Near 23rd Milestone, Badrinath Rd, Gular Dogi, Rishikesh, Uttarakhand 249303', 'https://www.google.com/maps/place/Anand+Kashi+by+the+Ganges,+Rishikesh+%E2%80%93+IHCL+SeleQtions/@30.1092816,78.4398515,15z/data=!4m2!3m1!1s0x0:0xe5563fa17656b5d8?sa=X&ved=2ahUKEwjY5531orP7AhVY5HMBHcIIAwUQ_BJ6BAhuEAc', 'A tranquil haven by the foothills of the Himalayas! The erstwhile summer residence of the Maharaja of Tehri Garhwal, Anand Kashi By The Ganges, Rishikesh - IHCL SeleQtions, is a hidden gem tucked away in the lush valley of the Himalayan mountains. Located by one of the most auspicious bends of the Ganges, it is resplendent with idyllic charm, mystical stories, and transcendent tranquillity. Set in the heart of the holy land of Uttarakhand, our serene hotel is woven in a rich tapestry of ancient folklore, untouched meadows, and sparkling springs. Cocooned by a rich expanse of lush fruit orchards and endless views of the ethereal Ganges, the property enfolds you with the promise of peace and purity. The hotel showcases an aesthetic play of traditional Garhwali architecture adorned by contemporary embellishments in its decor. The accommodation is conceptualised in the Vedic Panchamahabhuta philosophy – touch (Sparsh), taste (Kesari), sight (Dhrishti), sound (Ujala) and scent (Mehek) – with each room carefully crafted to indulge your senses. Wake up to the sun’s dance on the river’s surface or breathe in the abundant mountain air as you de-stress in our spacious rooms. Decorated with rich hues, subtle tones, and delicate floral designs, your stay is complemented by designer luxury essentials and generous vanity counters. Our all-day diner, Ana Rasa brings you a curated dining experience with global cuisines along with a slice of fresh organic produce from our very own orchards. Enjoy a starry night at our rooftop bar, Amrit Tara as your sip on a range of crafted cocktails and appetising bites or have a relaxed meal at the splendid Ganga deck. Our flexible conference rooms are perfectly equipped for intimate business meetings and conferences. Unwind as you take a leisurely swim in the infinity pool - shaped to the curvature of the Ganges - or surrender to the gentle strokes of wellness at our first-of-its-kind intimate spa, Amrit Kashi. Soak in the spiritual healing energy of Rishikesh at the hotel’s Shiv Mandir, or let your soul strum to the rhythm of the Ganga Aarti performed by our resident priests. Seize an opportunity to imbibe in the heavenly symphony of Rishikesh by taking a dip in the sacred waters at our private beach. With a skilled concierge and an array of bespoke experiences, Anand Kashi By The Ganges, Rishikesh - IHCL SeleQtions welcomes you to a realm of comfort, designed to delight.', 'assets/images/hotels/anand-kashi-by-the-ganges-rishikesh-ihcl-seleqtions/1.webp', 1),
(337, 'H303', 'grand-shiva-resort-rishikesh', 'GRAND SHIVA RESORT RISHIKESH', 'Rishikesh', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13802.348869051697!2d78.3857975!3d30.1346231!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xd42e9b852f05a4b8!2sThe%20Grand%20Shiva%20Resort%20and%20Spa!5e0!3m2!1sen!2sin!4v1631079059808!5m2!1sen!2sin', 'The Grand Shiva Resort appears on the map of adventure and holy destination Shivpuri- Rishikesh. The Resort is on arm of hills and green forest away from the hustle and bustle of the daily routine where you can wake with enchanting sound of water of holy river Ganga, twittering of the birds, whispering melodies of trees, the rippling of the stream. The Resort is just 30 minutes from Rishikesh and 45 minutes drive from Airport.\n\nThe Grand Shiva Resort is ideal place for Adventure, Conferences, Holidays, Aurvedic Treatment, Family outing, Birthday Party, Get together, Day out, marriage function and so many other programs according to your requirement with rooms having hill greenery view and River view. We always look for your pleasant holiday.', 'assets/images/hotels/grand-shiva-resort-rishikesh/1.webp', 1),
(338, 'H697', 'harmony-on-ganges-laxmi-heights-tapovan-rishikesh-rishikesh', 'Harmony on Ganges, Laxmi Heights, Tapovan, Rishikesh - Rishikesh', 'Rishikesh', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Nim Beach, Badrinath Rd, Tapovan, Rishikesh, Uttarakhand 249137', NULL, 'Located in Rishikesh, India, Harmony on Ganges, Laxmi Heights, Tapovan, Rishikesh is part of the Galaxy Heritage World network of hotels and resorts. Find it at Nim Beach, Badrinath Rd, Tapovan, Rishikesh, Uttarakhand 249137. Popular places to visit in Rishikesh include Lakshman Jhula, Ram Jhula and Triveni Ghat.', 'assets/images/hotels/harmony-on-ganges-laxmi-heights-tapovan-rishikesh-rishikesh/1.webp', 1),
(339, 'H302', 'howard-sanctuary-rishikesh', 'HOWARD SANCTUARY RISHIKESH', 'Rishikesh', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, NULL, 'HOWARD SANCTUARY RISHIKESH is a hotel in Rishikesh, India. Popular places to visit in Rishikesh include Lakshman Jhula, Ram Jhula and Triveni Ghat.', 'assets/images/hotels/howard-sanctuary-rishikesh/1.webp', 1),
(340, 'H627', 'justa-rasa-retreat-and-spa-rishikesh', 'jüSTa Rasa Retreat & Spa, Rishikesh', 'Rishikesh', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; wellness-retreats', 'Mohan Chatti, Rishikesh, Uttarakhand 249304', 'https://www.google.com/maps/place/j%C3%BCSTa+Rasa+Retreat+%26+Spa,+Rishikesh/@30.0633937,78.3789503,15z/data=!4m2!3m1!1s0x0:0xc13819c38320a280?sa=X&ved=2ahUKEwiB7deLorP7AhWBx3MBHU-gCHEQ_BJ6BAhxEAc', '“Rasa”, stands for aesthetic flavors of majestic artwork & essence of emotional feeling. Connect with the blissful experience of life by the river Ganges. Experience the unparalleled luxury and private abode of nature in the foothills of mountains. Sitting on the banks of the holy river, get a restful pause and let the time stands still in utter calmness and peace. jüSTa Rasa, a 5-star luxury resort in Rishikesh is a distinctive name in the realm of comfort, architecture, impeccable design, and of course, Ganges. Set in the perfect abode of a private river, a hill facing space, serene, and sylvan setting around. The exquisite retreat in the yoga capital of the world i.e., Rishikesh, offers an interesting blend of Rasa (Indian artwork), holistic view of hills, and private river access. Let your worries be behind and get indulged in the blissful practice of nature gazing, meditation, spa therapies, and more at one place of confined comfort and convenience. One of the best resorts in Rishikesh, jüSTa Rasa is at a short distance away from the bungee jumping point (2 Km) and the synonymous Ramjhula (14). The resort provides an eco-friendly staying pleasure, extensive line of activities, and direct access to the river itself.', 'assets/images/hotels/justa-rasa-retreat-and-spa-rishikesh/1.webp', 1),
(341, 'H696', 'kamay-the-grand-alova-rishikesh', 'Kamay The Grand Alova - Rishikesh', 'Rishikesh', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Neam Beach road Tapovan Rishikesh Badrinath Road, NH-58, Tapovan, Rishikesh, Uttarakhand 249192', NULL, 'Stay at Kamay The Grand Alova, a hotel in Rishikesh, India. The address is Neam Beach road Tapovan Rishikesh Badrinath Road, NH-58, Tapovan, Rishikesh, Uttarakhand 249192. Popular places to visit in Rishikesh include Lakshman Jhula, Ram Jhula and Triveni Ghat.', 'assets/images/hotels/kamay-the-grand-alova-rishikesh/1.webp', 1),
(342, 'H629', 'lamrin-boutique-cottages', 'Lamrin Boutique Cottages', 'Rishikesh', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels; cabins; cottages', 'Cottage No. C-7,Ganga Vatika, 2, Muni Ki Reti, Rishikesh, Uttarakhand 249201', 'https://www.google.com/maps/place/Lamrin+Boutique+Cottages/@30.1224791,78.3073293,15z/data=!4m2!3m1!1s0x0:0x315893c61551c493?sa=X&ved=2ahUKEwiBjbzbo7P7AhWC7HMBHbQhBDAQ_BJ6BAh-EAc', 'We at the Lamrin Boutique Cottages are dedicated to make the stay comfortable, relaxing and with a pleasant experience such as you are sitting surrounded by a forest area opposite a Rudrakasha tree overlooking serene gardens. If you don’t want to move about too much from your home like ambience just climb our wooden staircase to find the rooftop overlooking the Ganges meandering, while holding a cup of freshly brewed coffee. 700 meters walk from the Ram Jhula is an oasis of calm, close enough for you to unpack and be able to make a quick visit to the Ganges at any time. Sit by the source of life rippling past blessing all on lookers, dip your feet in the ice-cold water feel it invigorate every cell in your being. Every early morning and evening you hear the gentle ashram bells tolling, calling to you. A place to unwind let the spiritual in the air become a part of you without realizing it. Each cottage (250 sq. yard) has 4 bedrooms with attached bathrooms. Guests enjoy in house lounge, dining, private sit out area, gardens, large balconies, modern fittings. Our cottages can accommodate 20 people. Aesthetics with ancient replica paint work lets you feel the spiritual aura of the holy city. Come experience an era when the gods and humans lived in harmony. It is our Endeavor to make our Cottages as the destination at Rishikesh and to achieve that aspiration we need your support and cooperation. We are dedicated to offer you personalized and friendly service, but more than that is the Quality. Our aim is to make the Cottages your favorites place to stay at Dev Bhoomi. Moreover, we shall be constantly listening to our guests with open mind, so that we may, truly, emerge as the finest Resorts in the region.', 'assets/images/hotels/lamrin-boutique-cottages/1.webp', 1),
(343, 'H694', 'nishantam-rishikesh-rishikesh', 'Nishantam Rishikesh - Rishikesh', 'Rishikesh', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Neelkanth Temple Road, Rattapani, Rishikesh, Uttarakhand 249201', NULL, 'Nishantam Rishikesh is a hotel in Rishikesh, India. Its address is Neelkanth Temple Road, Rattapani, Rishikesh, Uttarakhand 249201. Popular places to visit in Rishikesh include Lakshman Jhula, Ram Jhula and Triveni Ghat.', 'assets/images/hotels/nishantam-rishikesh-rishikesh/1.webp', 1),
(344, 'H698', 'regenta-inn-on-the-ganges-rishikesh', 'Regenta Inn On The Ganges - Rishikesh', 'Rishikesh', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Badrinath Rd, near Neam Beach, Tapovan, Rishikesh, Uttarakhand 249192 Phone: 073021 11190', NULL, 'Regenta Inn On The Ganges is a hotel in Rishikesh, India. Its address is Badrinath Rd, near Neam Beach, Tapovan, Rishikesh, Uttarakhand 249192 Phone: 073021 11190. Popular places to visit in Rishikesh include Lakshman Jhula, Ram Jhula and Triveni Ghat.', 'assets/images/hotels/regenta-inn-on-the-ganges-rishikesh/1.webp', 1),
(345, 'H695', 'the-ayali-riverside-resort-rishikesh', 'The Ayali Riverside Resort - Rishikesh', 'Rishikesh', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', 'Neelkanth Temple Road, Ghattu Ghat, Taliyal Gaon, Uttarakhand 249201', NULL, 'Stay at The Ayali Riverside Resort in Rishikesh, India. The address is Neelkanth Temple Road, Ghattu Ghat, Taliyal Gaon, Uttarakhand 249201. Popular places to visit in Rishikesh include Lakshman Jhula, Ram Jhula and Triveni Ghat.', 'assets/images/hotels/the-ayali-riverside-resort-rishikesh/1.webp', 1),
(346, 'H529', 'hotel-artis', 'Hotel Artis', 'Rome', 'Italy', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Via Roberto Fancelli, 3, 00169 Roma RM, Italy', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KVPDrRSHYi8TMV8jNi5BUVpq&daddr=Hotel+Artis,+Via+Roberto+Fancelli,+3,+00169+Roma+RM,+Italy', 'Rome has plenty of wine bars. So when you’re here, be sure to check out popular spots like Largo8, Tramonti e Muffati, and Delponte, which are serving up some great dishes.\n\nThere is no shortage of things to do in the area: explore popular parks such as Villa Doria Pamphilj, Parco Tutti Insieme, and Parco Savello.', 'assets/images/hotels/hotel-artis/1.webp', 1),
(347, 'H528', 'hotel-roma-tor-vergata', 'Hotel Roma Tor Vergata', 'Rome', 'Italy', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Via Vico Viganò, 24, 00133 Roma RM, Italy', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KRmcFNdOfS8TMU-MbFZdnbr1&daddr=Hotel+Roma+Tor+Vergata,+Via+Vico+Vigan%C3%B2,+24,+00133+Roma+RM,+Italy', 'located 14 km from the centre of Rome, close to the A2 and Tor Vergata university. Close by are a theatre and a sports centre. Appreciated by guests on a business trip, the hotel has 211 air-conditioned rooms and 5 meeting rooms. A restaurant, a bar open 24/24, a terrace and a swimming pool are at your disposal. Wifi Internet access and parking possibilities are available', 'assets/images/hotels/hotel-roma-tor-vergata/1.webp', 1),
(348, 'H527', 'urban-garden-hotel', 'Urban Garden Hotel', 'Rome', 'Italy', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Via di Rebibbia, 18/34, 00156 Roma RM, Italy', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KeFJF4mbYy8TMSjF4kmKHV5i&daddr=Urban+Garden+Hotel,+Via+di+Rebibbia,+18/34,+00156+Roma+RM,+Italy', 'Located in Tiburtina area close to the metro station Rebibbia direct to the historical center, lively and interesting neighbourhood of Rome, the palace was an ancient barrack turned in his image and atmosphere, characterzing it with a murals of strong impact on the facade and a wonderful garden in the sorrounding courtyard. The elements in wood, the soft beds: our rooms, just restructured, are suitable to accomodate and relax. Complete the image our Garden bar, place ideal for meeting guests and visitors, where you can drink a glass of wine or cocktails studied from our mixologist and taste the special dishes. Our hotel boasts a huge meeting room, well illuminated thanks to the presence of a big skylight', 'assets/images/hotels/urban-garden-hotel/1.webp', 1),
(349, 'H632', 'clarks-hotel', 'Clarks Hotel', 'Shimla', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Road From Court Road to Mall Marg, opp. High Court, Shimla, Himachal Pradesh 171001', 'https://www.google.com/maps/place/Clarkes+Hotel/@31.1011641,77.1743983,15z/data=!4m2!3m1!1s0x0:0xcb2d063f0fd83612?sa=X&amp;ved=2ahUKEwj80Kax37X7AhWQ7XMBHWvTCC8Q_BJ6BAh3EAc', 'Located on the Shimla Mall Road, Clarkes Hotel is an oasis of calm on the bustling promenade. This Heritage hotel has recently been upgraded to Grand Heritage category and is one of the oldest hotels in Shimla. Clarkes is known for its architecture dating from the colonial era. The hotel is within walking distance of Shimla attractions - Gaiety Theatre, Groton Castle, Museum, Rothney Castle, Viceregal Lodge, Churches and other Colonial era buildings. Clarkes Hotel embodies the elegance and charm of yesteryear, with modern conveniences of today. The hotel maintains the highest levels of service and has all the amenities, facilities and levels of comfort you would expect from a hotel of this class. Clarkes Hotel is just 10 minutes from Shimla Station.', 'assets/images/hotels/clarks-hotel/1.webp', 1),
(350, 'H681', 'honeymoon-in-shimla-shimla', 'Honeymoon In Shimla - Shimla', 'Shimla', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'The Mall, Shimla, Himachal Pradesh 171001', NULL, 'Stay at Honeymoon In Shimla, a hotel in Shimla, India. The address is The Mall, Shimla, Himachal Pradesh 171001. Popular places to visit in Shimla include The Ridge, Mall Road and Jakhoo Temple.', 'assets/images/hotels/honeymoon-in-shimla-shimla/1.webp', 1),
(351, 'H294', 'honeymoon-inn-shimla', 'HONEYMOON INN SHIMLA', 'Shimla', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13665.777806592874!2d77.1774929!3d31.0973768!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xb7e3e5f998a3b5ae!2sHoneymoon%20Inn!5e0!3m2!1sen!2sin!4v1631011446497!5m2!1sen!2sin', 'Comfort, quality and friendliness decorates our quaint little resort in Shimla. Blessed with a truly beautiful location, Honeymoon Inn Shimla is located in the heart of the \'Summer Capital of the British Raj. The deodar lined roads around the hotel invite you to take long walks hand in hand with your loved one and immerse yourselves in the charm of a bygone era.\n\nLounging in the manicured garden full of pastel coloured Hydrangeas, one is treated to breath-taking view of the valley, green deodar trees and sunsets in the evening.\n\nWe offer you comfortable rooms and suites designed to provide excellent view of the mountains and valley’s twinkling lights.\n\nThe beautiful location and years of impeccable service have made Honeymoon Inn Shimla famous. If you are interested in hotels in Shimla near Mall Road, then Honeymoon Inn is sure to be the best choice. From the views to the architecture, from the lovely rooms to the dedicated staff, Honeymoon Inn is a jewel amongst Shimla hotels. With the reputation of being the best 3 star hotel in Shimla, we endeavour to provide an unforgettable experience to every guest.', 'assets/images/hotels/honeymoon-inn-shimla/1.webp', 1),
(352, 'H301', 'larisa-resort-shimla', 'Larisa Resort Shimla', 'Shimla', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13666.503481813977!2d77.1370944!3d31.0923323!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x51ce9953a87f2fee!2sLarisa%20Resort%20Shimla!5e0!3m2!1sen!2sin!4v1631078412159!5m2!1sen!2sin', 'As you approach the South-Western Himalayan ranges along NH 22, you get a pleasant aesthetic view of the Himachal capital, nestled amidst steep hills that seem to trail away. Ensconced by the sky above and surrounded by the jagged hilltops painted in hues of blue and white; Our shimla resort offers you a happy indulgence in pure luxury.', 'assets/images/hotels/larisa-resort-shimla/1.webp', 1),
(353, 'H682', 'larisa-resort-shimla-shimla', 'Larisa Resort Shimla - Shimla', 'Shimla', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', 'NH5, near Joshi Bhawan, Kachi Ghatti, Shimla, Himachal Pradesh 171010', NULL, 'Located in Shimla, India, Larisa Resort Shimla is part of the Galaxy Heritage World network of hotels and resorts. Find it at NH5, near Joshi Bhawan, Kachi Ghatti, Shimla, Himachal Pradesh 171010. Popular places to visit in Shimla include The Ridge, Mall Road and Jakhoo Temple.', 'assets/images/hotels/larisa-resort-shimla-shimla/1.webp', 1),
(354, 'H756', 'manla-homes-resort', 'Manla Homes Resort', 'Shimla', 'India', 'DOMESTIC', 'RESORT', 'ASSOCIATED', 'resorts; vacation-homes', 'Mohanpur Rd, Baldeyan, Himachal Pradesh 171007', NULL, 'Manla Homes Resort has a fitness center, garden, a terrace and restaurant in Mashobra. Offering a bar, the property is located within 6.6 miles of Victory Tunnel. The property has room service, a 24-hour front desk and currency exchange for guests.\n\nAt the hotel, the rooms include a balcony. Featuring a private bathroom with a shower and free toiletries, some accommodations at Manla Homes Resort also feature a mountain view. All rooms at the accommodation come with a flat-screen TV with satellite channels.\n\nYou can play table tennis and tennis at Manla Homes Resort, and car rental is available.\n\nCircular Road is 5.7 miles from the hotel, while Jakhoo Gondola is 5.7 miles from the property. The nearest airport is Simla Airport, 19 miles from Manla Homes Resort.', 'assets/images/hotels/manla-homes-resort/1.webp', 1),
(355, 'H276', 'marigold-sarovar-portico-shimla', 'MARIGOLD SAROVAR PORTICO SHIMLA', 'Shimla', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13656.898112250821!2d77.2042704!3d31.1590441!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xc1430fcfbe9bb133!2sMarigold%20Sarovar%20Portico%2C%20Shimla%20-%20A%20Premium%20Hotel%20in%20Shimla!5e0!3m2!1sen!2sin!4v1630398957891!5m2!1sen!2sin', 'Marigold Sarovar Portico is located at Mashobra Hills in Shimla. The resort offers a virtual bonanza for nature-walk lovers and trekkers. Unearthing the most exciting Shimla trekking, water rafting & picnic opportunities of the hotel. The resort offers a platform to its guests to experience nature and his real self on one hand and on the other acquaint oneself with the country life in Himalayan Villages. The cottages at the resort are made of Himalayan Stone, which are a unique and specialized specimen of Shimla Architecture. Besides, the hotel will offer all modern facilities including all day dining, restaurant, bar, , gym and spa, meeting rooms, banqueting facilities, conferencing and destination weddings and other services required for a good 4 Star Hotel.', 'assets/images/hotels/marigold-sarovar-portico-shimla/1.webp', 1),
(356, 'H630', 'radisson-jass-shimla', 'Radisson Jass Shimla', 'Shimla', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Goodwood Estate, Lower, Bharari, Shimla, Himachal Pradesh 171001', 'https://www.google.com/maps/place/Radisson+Jass+Shimla/@31.1115226,77.1772136,15z/data=!4m2!3m1!1s0x0:0x8abb096952dfec2a?sa=X&ved=2ahUKEwj7rsW43bX7AhV963MBHUR4CzQQ_BJ6BQiAARAH', 'Located at an altitude of 2200meters above mean sea level, amidst Cedar forests the Radisson Jass hotel has 67 well-appointed suites and guest rooms overlooking magnificent mountains, beautiful valleys and dense pine forests. The finest resort in Shimla with a recreation area featuring among other leisure facilities, our resort has an all day dining restaurant with a selection of Continental, Oriental and Indian specialties opening into a garden that overlooks the magnificent mountain ranges and valleys, bar with an Open deck terrace offers gorgeous views as well as a choice selection of wines and spirits and Round the clock dining offering selection of Indian, Oriental and Continental cuisine.', 'assets/images/hotels/radisson-jass-shimla/1.webp', 1),
(357, 'H684', 'snow-valley-resort-shimla', 'SNOW VALLEY RESORT - Shimla', 'Shimla', 'India', 'DOMESTIC', 'RESORT', 'INTERNAL', 'resorts', 'Ghora Chowki, Shimla, Himachal Pradesh 171004', NULL, 'SNOW VALLEY RESORT is located in Shimla, India. Its address is Ghora Chowki, Shimla, Himachal Pradesh 171004. Popular places to visit in Shimla include The Ridge, Mall Road and Jakhoo Temple.', 'assets/images/hotels/snow-valley-resort-shimla/1.webp', 1),
(358, 'H683', 'the-zion-hotel-shimla-shimla', 'The Zion Hotel Shimla - Shimla', 'Shimla', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Nexa showroom, District Court Road, near Sankat Mochan, Temple, Kachi Ghatti, Shimla, Himachal Pradesh 171010', NULL, 'Located in Shimla, India, The Zion Hotel Shimla is part of the Galaxy Heritage World network of hotels and resorts. Find it at Nexa showroom, District Court Road, near Sankat Mochan, Temple, Kachi Ghatti, Shimla, Himachal Pradesh 171010. Popular places to visit in Shimla include The Ridge, Mall Road and Jakhoo Temple.', 'assets/images/hotels/the-zion-hotel-shimla-shimla/1.webp', 1),
(359, 'H324', 'toshali-royal-view-shimla', 'Toshali Royal View Shimla', 'Shimla', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13672.306879691761!2d77.2682512!3d31.0519637!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x39709054f3ecc955!2sToshali%20Royal%20View%20Shimla!5e0!3m2!1sen!2sin!4v1631949693866!5m2!1sen!2sin', 'Set 7.4 km from Himalayan Nature Park, this tranquil mountain hotel is 12 km from Kufri Fun World theme park and 25 km from Mall Road, Shimla\'s main shopping district.\n\nTraditional rooms have colonial decor and come with satellite TV and tea and coffeemaking facilities. All feature balconies with mountain views, and upgraded rooms add sofabeds and dining areas.\n\nThere\'s a restaurant serving Indian and international cuisine, along with a bar and a terrace with mountain views. The spa features treatment rooms, a hot tub, a steam room and a sauna. Other amenities include a game room, a fitness room and function rooms.', 'assets/images/hotels/toshali-royal-view-shimla/1.webp', 1),
(360, 'H691', 'daiwik-hotel-shirdi-shirdi', 'DAIWIK HOTEL SHIRDI - Shirdi', 'Shirdi', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'New Pimpalwadi Road, Behind B.S.N.L. Bldg., Tal – Rahata, Dist. Ahmednagar, Shirdi, Maharashtra 423109', NULL, 'DAIWIK HOTEL SHIRDI is located in Shirdi, India. Its address is New Pimpalwadi Road, Behind B.S.N.L. Bldg., Tal – Rahata, Dist. Ahmednagar, Shirdi, Maharashtra 423109. Popular places to visit in Shirdi include Sai Baba Samadhi Mandir, Shani Shingnapur and Dwarkamai.', 'assets/images/hotels/daiwik-hotel-shirdi-shirdi/1.webp', 1)
INSERT INTO `hotels` (id, hotel_code, slug, name, location_name, country, location_type, hotel_type, category, stay_types, address, map_link, description, image_path, is_published) VALUES
(361, 'H633', 'hotel-temple-tree', 'Hotel Temple Tree', 'Shirdi', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Plot No. 01, Ring Road, behind Sai Ashram, Shirdi, Maharashtra 423109', 'https://www.google.com/maps/place/Hotel+Temple+Tree/@19.754684,74.481495,15z/data=!4m2!3m1!1s0x0:0xdfafe3ae5f227cf0?sa=X&ved=2ahUKEwi1kOT737X7AhUq5XMBHVaAAdgQ_BJ6BAh3EAc', 'Newly renovated. Travellers Choice 2022. Award winning 4 Star, 87 room hotel with a Multi-Cuisine restaurant, entertainment lounge, swimming pool, lawn and a conference hall. Toddler-friendly Play Zone. Sai Mandir in premises. With all Covid-19 precautions.', 'assets/images/hotels/hotel-temple-tree/1.webp', 1),
(362, 'H634', 'renest-shraddha-inn-shirdi', 'Renest Shraddha Inn - Shirdi', 'Shirdi', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Ground floor, Lobby Level, Pimpalwadi Rd, Dattanagar, Shirdi, Maharashtra 423109', 'https://www.google.com/maps/place/Renest+Shraddha+Inn+-+Shirdi/@19.7690934,74.4838602,15z/data=!4m2!3m1!1s0x0:0xe185e27032167955?sa=X&ved=2ahUKEwjruavI4LX7AhWE0HMBHQqNDEQQ_BJ6BQiJARAH', 'Renest Shraddha inn - Shirdi exudes luxury with its majestic architecture, lush green landscape and superlative services. It is an ideal destination for a pilgrimage stayover, a getaway with family as well as a host for marriages and corporate events. The resort is equiped with an outdoor and indoor gaming arena, souvenir shop, swimming pool, kids play area, well-manicured gardens and an onsite Spa. The resort is located in close proximity of 700 mtrs. from Shirdi Sai Baba Temple and a short drive of 25 minutes from the airport.', 'assets/images/hotels/renest-shraddha-inn-shirdi/1.webp', 1),
(363, 'H635', 'shri-sainivas-mega-residency', 'Shri Sainivas Mega Residency', 'Shirdi', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Opp. Shiva Temple, Manmad Nagar Road, near Sri Sai Aasram 1000 Rooms, Shirdi, Maharashtra 423109', 'https://www.google.com/maps/place/Shri+Sainivas+Mega+Residency/@19.7513281,74.4789833,15z/data=!4m2!3m1!1s0x0:0xb4fbc398e274a6ca?sa=X&ved=2ahUKEwi4vJyn4bX7AhUih-YKHXGcBq4Q_BJ6BAhvEAc', 'OUR HOTEL IS LOCATED 1KM FROM TEMPLE total 156 room details are as per below MASTER SUITE 4 (no of rooms) 2945(price) EXCUTIVE SUITE 21(no of rooms) 2652(price) DELUXE SUITE 24 (no of rooms)1889(price) SUITE 24(no of rooms) 1291(price) DELUXE ROOM A/C 39(no of rooms) 842(price) SPl ROOM NON A/C24(no of rooms) 660(price) DELROOM NON A/C 20(no of rooms) 510(price)', 'assets/images/hotels/shri-sainivas-mega-residency/1.webp', 1),
(364, 'H532', 'hotel-81-orchid', 'Hotel 81 Orchid', 'Singapore', 'Singapore', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '21 Lor 8 Geylang, Singapore 399090', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KUtsWSI3GNoxMfnexnfAvZNi&daddr=21+Lor+8+Geylang,+Hotel+81+Orchid,+Singapore+399090', 'Singapore has plenty of seafood restaurants. So when you’re here, be sure to check out popular spots like Palm Beach Seafood Restaurant, JUMBO Seafood, and Colony, which are serving up some great dishes.', 'assets/images/hotels/hotel-81-orchid/1.webp', 1),
(365, 'H530', 'the-great-madras-by-hotel-calmo', 'The Great Madras by Hotel Calmo', 'Singapore', 'Singapore', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '28 Madras St, Singapore 208422', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=Kb_HtAW5GdoxMZjIRI9HJx7Z&daddr=28+Madras+St,+The+Great+Madras+by+Hotel+Calmo,+Singapore+208422', 'About The Great Madras by Hotel Calmo\n\nLocated on Madras Street in Singapore, The Great Madras offers luxurious views of the city and is just a 13-minute walk from the City Square Mall', 'assets/images/hotels/the-great-madras-by-hotel-calmo/1.webp', 1),
(366, 'H533', 'v-hotel-lavender', 'V Hotel Lavender', 'Singapore', 'Singapore', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '70 Jellicoe Rd, Singapore 208767', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=Kc9BXgfKGdoxMbZnMOPi4rXB&daddr=70+Jellicoe+Rd,+V+Hotel+Lavender,+Singapore+208767', 'V Hotel Lavender is an exciting new hotel located just above Lavender MRT station with direct access (via MRT/tube/subway) to/from the airport and various parts of Singapore (for instance, only stops to City Hall or Promenade Station', 'assets/images/hotels/v-hotel-lavender/1.webp', 1),
(367, 'H531', 'wink-mosque-street', 'Wink @ Mosque Street', 'Singapore', 'Singapore', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '8A Mosque St, Singapore 059488', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KYUX7FBzGdoxMZOE3kjcAx_M&daddr=8A+Mosque+St,+Wink+@+Mosque+Street,+Singapore+059488', 'Housed in a historic shophouse that\'s nestled in the cultural heart of Singapore, Wink offers travellers private sleeping sanctums that are inviting and decked in plush designer finishing. Our secure tap card system grants access to spacious dorms that are air-conditioned, fully carpeted and furnished with cushy couches. You will find our custom pods come in unique designs with plentiful headroom and side-allowances. Breakfast is served daily in our guest kitchenette that comes microwave oven and refrigerator. Other facilities include showers & toilets, a relaxing café lounge, internet stations, laundry & ironing. Wink is mere minutes away from numerous must-see heritage and cultural attractions. Nearby Clarke Quay and the bohemian Club Street also serves up an exciting array of nightlife and dining destinations. With Chinatown\'s Mass Rapid Transit (MRT) station and several bus-stops a short walk away, you will find Wink the perfect location from which to start exploring Singapore', 'assets/images/hotels/wink-mosque-street/1.webp', 1),
(368, 'H534', 'hotel-nuevo-madrid', 'Hotel Nuevo Madrid', 'Spain', 'Spain', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'C. Bausá, 27, 28033 Madrid, Spain', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KXG5D8Q2KUINMRTnhlB4Dcz7&daddr=Hotel+Nuevo+Madrid,+C.+Baus%C3%A1,+27,+28033+Madrid,+Spain', 'Located in the business area of Chamartín, with excellent transport communications with the main access routes to the centre of Madrid. Close to Plaza Castilla, the airport and IFEMA', 'assets/images/hotels/hotel-nuevo-madrid/1.webp', 1),
(369, 'H535', 'hotel-sterling-gran-via', 'Hotel Sterling Gran Vía', 'Spain', 'Spain', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'C. de San Bernardo, 29, 31, 28015 Madrid, Spain', 'https://www.google.com/maps/dir//Hotel+Sterling+Gran+V%C3%ADa,+C.+de+San+Bernardo,+29,+31,+28015+Madrid,+Spain/@40.4229939,-3.7777009,12z/data=!4m8!4m7!1m0!1m5!1m1!1s0xd42286353a0f2d5:0x195ac8405c87afc0!2m2!1d-3.707661!2d40.423015?hl=en-GB', 'Hotel Sterling features 24 hour front desk, a concierge, and baggage storage, to help make your stay more enjoyable. The property also boasts breakfast buffet.\n\nWhile visiting Madrid, you may want to try some lobster at one of the nearby restaurants, such as Ten Con Ten, El Paraguas, or La Terraza del Casino de Madrid', 'assets/images/hotels/hotel-sterling-gran-via/1.webp', 1),
(370, 'H538', 'grand-oriental-hotel', 'Grand Oriental Hotel', 'Sri Lanka', 'Sri Lanka', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '2 York St, Colombo 00200, Sri Lanka', 'https://www.google.com/maps/dir//Grand+Oriental+Hotel,+2+York+St,+Colombo+00200,+Sri+Lanka/@6.9373364,79.7748929,12z/data=!4m8!4m7!1m0!1m5!1m1!1s0x3ae25920c53a5e23:0x56efc3724db4f567!2m2!1d79.8449335!2d6.9373415?hl=en-GB', 'An iconic building at the heart of Colombo, located overlooking the busy harbor; gifted with history, it is where comfort blends with affordability for the most discerning traveler. This fine piece of architecture speaks of the country\'s colonial times and with a spectacular view of Colombo Harbour. The splendidly decorated 80 rooms are fully air-conditioned while Queen Elizabeth (2) , Anton Chekhov and Joze Rizal, are the luxury suites overlooking the Colombo harbor, offering a fantastic view for their guests. It is more than just a hotel. It is home away from home', 'assets/images/hotels/grand-oriental-hotel/1.webp', 1),
(371, 'H537', 'juliana-hotel', 'Juliana Hotel', 'Sri Lanka', 'Sri Lanka', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '316 Galle Rd, Colombo 00300, Sri Lanka', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KT8_bMVCWeI6Mam6dYi7Jdwl&daddr=Juliana+Hotel,+316+Galle+Rd,+Colombo+00300,+Sri+Lanka', 'Finding an ideal budget friendly hotel in Colombo does not have to be difficult. Welcome to Juliana Hotel, a nice option for travellers like you.\n\nGuest rooms offer air conditioning, a desk, and a sofa, and Juliana Hotel makes getting online easy as free wifi is available', 'assets/images/hotels/juliana-hotel/1.webp', 1),
(372, 'H536', 'mandarina-colombo', 'Mandarina Colombo', 'Sri Lanka', 'Sri Lanka', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', '433 A2, Colombo 00300, Sri Lanka', 'https://www.google.com/maps?hl=en-GB&gl=IN&um=1&ie=UTF-8&fb=1&sa=X&geocode=KTmQrEFgWeI6MdvQMwMH4us5&daddr=Mandarina+Colombo,+433+A2,+Colombo+00300,+Sri+Lanka', 'Strategically located in Colombo and only 1.5 km from the U.S Embassy and 5 min walk from the British Council, Mandarina Colombo offers modern and comfortable accommodation with free WiFi access throughout the property. It features a rooftop infinity outdoor pool and provides complimentary parking on site. The hotel is just a 10-minute walk from Majestic City, Majestic Cinema, Barefoot Gallery, Casino Marina Colombo, Bellagio Colombo and 1.5km from Sri Lanka National Museum.', 'assets/images/hotels/mandarina-colombo/1.webp', 1),
(373, 'H636', 'courtyard-by-marriott-surat', 'Courtyard by Marriott Surat', 'Surat', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Earthspace, Hazira Rd, Surat, Gujarat 394510', 'https://www.google.com/maps/place/Courtyard+by+Marriott+Surat/@21.1762209,72.7326277,15z/data=!4m2!3m1!1s0x0:0x413469905499ee62?sa=X&ved=2ahUKEwjZ0eK94rX7AhV1xTgGHVBUDeUQ_BJ6BAh5EAc', 'Welcome to Courtyard by Marriott Surat, your Surat “home away from home.” Courtyard by Marriott Surat aims to make your visit as relaxing and enjoyable as possible, which is why so many guests continue to come back year after year.\n\nGuest rooms offer amenities such as air conditioning, a minibar, and a kitchenette, and guests can go online with free wifi offered by the hotel.\n\nCourtyard by Marriott Surat features 24 hour front desk, room service, and 24 hour check-in, to help make your stay more enjoyable. The property also boasts a pool and an on-site restaurant. If you are driving to Courtyard by Marriott Surat, free parking is available.\n\nIf you are looking for a good spot to eat nearby, you may want to check out Charcoal (1.1 mi), which is within walking distance of Courtyard by Marriott Surat.\n\nCourtyard by Marriott Surat puts the best of Surat at your fingertips, making your stay both relaxing and enjoyable.', 'assets/images/hotels/courtyard-by-marriott-surat/1.webp', 1),
(374, 'H637', 'jeel-elite-inn', 'JEEL ELITE INN', 'Surat', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', 'Rajhans Belliza - 1 A - G 20 Rajhans Belliza - 2 B 1106, Airport Road, near DPS School, Dumas, Gujarat 395007', 'https://www.google.com/maps/place/JEEL+ELITE+INN/@21.1237684,72.7191439,15z/data=!4m2!3m1!1s0x0:0xf0fb009ec7c13bc2?sa=X&ved=2ahUKEwioovSK47X7AhUwyDgGHcEhAfMQ_BJ6BQiFARAH', 'Featuring a restaurant, a fitness center, and a garden, Jeel Elite Inn provides accommodations in Surat with free WiFi and garden views. This beachfront property offers access to a pool table, ping-pong and free private parking. The apartment is equipped with 2 bedrooms, 2 bathrooms, bed linen, towels, a flat-screen TV with cable channels, a dining area, a fully equipped kitchenette, and a patio with pool views. For added convenience, the property can provide towels and bed linen for an extra charge. Around the clock guidance is available at the reception, where staff speak Hindi, English and Gujarati. The apartment offers a children\'s playground. Guests can swim in the indoor pool, or go cycling.', 'assets/images/hotels/jeel-elite-inn/1.webp', 1),
(375, 'H638', 'the-park-celebration', 'The Park Celebration', 'Surat', 'India', 'DOMESTIC', 'HOTEL', 'ASSOCIATED', 'hotels', '4th Floor, Atlantis Square, Opp Vesu Fire Station, Vesu, Surat, Gujarat 395007', 'https://www.google.com/maps/place/The+Park+Celebration/@21.1424815,72.7810157,15z/data=!4m2!3m1!1s0x0:0xc6a54e4a813e743e?sa=X&ved=2ahUKEwjp8pTU47X7AhU66XMBHcjOBNkQ_BJ6BAh8EAc', 'Get your trip off to a great start with a stay at this property, which offers free Wi-Fi in all rooms. Conveniently situated in the Vesu part of Surat, this property puts you close to attractions and interesting dining options. Don\'t leave before paying a visit to the famous Surat Airport. As an added bonus, restaurant is provided on-site to conveniently serve your needs.', 'assets/images/hotels/the-park-celebration/1.webp', 1),
(376, 'H541', 'hotel-splendide-royal-lugano', 'Hotel Splendide Royal Lugano', 'Switzerland', 'Switzerland', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Riva Antonio Caccia 7, 6900 Lugano, Switzerland', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d55735162.5358212!2d6.66177837327898!3d31.50206110701318!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x47842d97b245b197%3A0x3822612db45ce95b!2sHotel%20Splendide%20Royal%20Lugano!5e0!3m2!1sen!2sin!4v1667458189039!5m2!1sen!2sin', 'Set in a 19th-century palace across the street from Lake Lugano, this luxe hotel is a 12-minute walk from shops along Via Nassa and 5 km from Lugano Airport.\n\nWarm rooms with a traditional vibe feature marble bathrooms, free Wi-Fi, satellite TV and minibars. Upgraded rooms offer balconies with lake views. Opulent suites come with separate living areas. There\'s 24-hour room service.\n\nA breakfast buffet is included. Amenities consist of a wine bar, an elegant lounge and 2 upscale restaurants, both with lake views. Pets are welcome; fees may apply.', 'assets/images/hotels/hotel-splendide-royal-lugano/1.webp', 1),
(377, 'H540', 'movenpick-hotel-lausanne', 'Mövenpick Hotel Lausanne', 'Switzerland', 'Switzerland', 'INTERNATIONAL', 'HOTEL', 'INTERNAL', 'hotels', 'Av. de Rhodanie 4, 1007 Lausanne, Switzerland', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d55586210.33293004!2d5.535849647072831!3d31.7510330024223!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x478c2fd07e2dea5b%3A0x3bf1f76e0fe78e3!2sM%C3%B6venpick%20Hotel%20Lausanne!5e0!3m2!1sen!2sin!4v1667457019557!5m2!1sen!2sin', 'Across from a harbor on the shores of Lake Geneva, this conservative hotel is a 13-minute walk from the Olympic Museum.\n\nRooms range from low-key to sophisticated in styling, and they all offer free Wi-Fi, minifridges, flat-screens, and tea and coffeemakers. Upgraded rooms add lake views, Nespresso coffeemakers, rainfall showers and/or balconies. Suites add sitting areas, and an upgraded 2-level suite features a whirlpool tub.\n\nBreakfast (fee) is served in a relaxed buffet restaurant with outdoor seating. There\'s also an upscale brasserie and a formal fish eatery. Other amenities include a fitness center and a sauna, as well as 18 meeting rooms.', 'assets/images/hotels/movenpick-hotel-lausanne/1.webp', 1),
(378, 'H693', 'spice-grove-thekkady', 'Spice Grove - Thekkady', 'Thekkady', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Plot No. IV/426A, Thekkady - Munnar Highway, Dist, Anakkara, Kerala 685512', NULL, 'Located in Thekkady, India, Spice Grove is part of the Galaxy Heritage World network of hotels and resorts. Find it at Plot No. IV/426A, Thekkady - Munnar Highway, Dist, Anakkara, Kerala 685512. Popular places to visit in Thekkady include Periyar National Park, Thekkady Lake and Mangala Devi Temple.', 'assets/images/hotels/spice-grove-thekkady/1.webp', 1),
(379, 'H692', 'sterling-thekkady-thekkady', 'Sterling Thekkady - Thekkady', 'Thekkady', 'India', 'DOMESTIC', 'HOTEL', 'INTERNAL', 'hotels', 'Kottayam - Kumily Rd, opp. Holiday Home, Thekkady, Kumily, Kerala 685509', NULL, 'Located in Thekkady, India, Sterling Thekkady is part of the Galaxy Heritage World network of hotels and resorts. Find it at Kottayam - Kumily Rd, opp. Holiday Home, Thekkady, Kumily, Kerala 685509. Popular places to visit in Thekkady include Periyar National Park, Thekkady Lake and Mangala Devi Temple.', 'assets/images/hotels/sterling-thekkady-thekkady/1.webp', 1),
